package com.personalbis;

import java.util.EnumMap;
import java.util.Map;
import javax.inject.Inject;
import javax.inject.Singleton;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.Skill;
import net.runelite.api.Quest;
import net.runelite.api.QuestState;

@Singleton
public class AccountSnapshot
{
    private final Client client;
    private final Map<Skill, Integer> real = new EnumMap<>(Skill.class);
    private final Map<Skill, Integer> boosted = new EnumMap<>(Skill.class);
    // Permanent prayer unlock varbits (server-backed account state).
    private static final int RIGOUR_UNLOCKED_VARBIT = 5451;
    private static final int AUGURY_UNLOCKED_VARBIT = 5452;
    private static final int DEADEYE_UNLOCKED_VARBIT = 16097;
    private static final int MYSTIC_VIGOUR_UNLOCKED_VARBIT = 16098;
    // RuneLite Varbits.CAMELOT_TRAINING_ROOM_STATUS: 8 = Knight Waves complete.
    private static final int CAMELOT_TRAINING_ROOM_STATUS_VARBIT = 3909;
    // RuneLite Varbits.DIARY_KANDARIN_HARD. Completion grants +10% enchanted-bolt proc chance.
    private static final int KANDARIN_HARD_DIARY_VARBIT = 4477;
    private boolean rigourUnlocked, auguryUnlocked, deadeyeUnlocked, mysticVigourUnlocked, chivalryUnlocked, pietyUnlocked;
    private boolean ancientMagicksUnlocked, kingdomDividedUnlocked, kandarinHardCompleted;

    @Inject
    public AccountSnapshot(Client client)
    {
        this.client = client;
    }

    public void refresh()
    {
        if (client.getGameState() != GameState.LOGGED_IN) return;
        for (Skill skill : Skill.values())
        {
            real.put(skill, client.getRealSkillLevel(skill));
            boosted.put(skill, client.getBoostedSkillLevel(skill));
        }
        rigourUnlocked = client.getVarbitValue(RIGOUR_UNLOCKED_VARBIT) > 0;
        auguryUnlocked = client.getVarbitValue(AUGURY_UNLOCKED_VARBIT) > 0;
        deadeyeUnlocked = client.getVarbitValue(DEADEYE_UNLOCKED_VARBIT) > 0;
        mysticVigourUnlocked = client.getVarbitValue(MYSTIC_VIGOUR_UNLOCKED_VARBIT) > 0;
        int knightWaves = client.getVarbitValue(CAMELOT_TRAINING_ROOM_STATUS_VARBIT);
        chivalryUnlocked = knightWaves >= 8;
        pietyUnlocked = knightWaves >= 8;
        ancientMagicksUnlocked = questFinished("DESERT_TREASURE_I");
        kingdomDividedUnlocked = questFinished("A_KINGDOM_DIVIDED");
        kandarinHardCompleted = client.getVarbitValue(KANDARIN_HARD_DIARY_VARBIT) > 0;
    }

    public int real(Skill skill) { return real.getOrDefault(skill, 0); }
    public int boosted(Skill skill) { return boosted.getOrDefault(skill, real(skill)); }
    public boolean isRigourUnlocked() { return rigourUnlocked; }
    public boolean isAuguryUnlocked() { return auguryUnlocked; }
    public boolean isDeadeyeUnlocked() { return deadeyeUnlocked; }
    public boolean isMysticVigourUnlocked() { return mysticVigourUnlocked; }
    public boolean isChivalryUnlocked() { return chivalryUnlocked; }
    public boolean isPietyUnlocked() { return pietyUnlocked; }
    public boolean isAncientMagicksUnlocked() { return ancientMagicksUnlocked; }
    public boolean isKingdomDividedUnlocked() { return kingdomDividedUnlocked; }
    public boolean isKandarinHardCompleted() { return kandarinHardCompleted; }

    private boolean questFinished(String enumName)
    {
        try { return Quest.valueOf(enumName).getState(client) == QuestState.FINISHED; }
        catch (IllegalArgumentException ex) { return false; }
    }

    public String recommendedPrayer(AttackStyle style)
    {
        int p = real(Skill.PRAYER);
        switch (style)
        {
            case MELEE_STAB:
            case MELEE_SLASH:
            case MELEE_CRUSH:
                if (p >= 70 && pietyUnlocked) return "Piety";
                if (p >= 60 && chivalryUnlocked) return "Chivalry";
                if (p >= 34) return "Incredible Reflexes + Ultimate Strength";
                if (p >= 31) return "Ultimate Strength";
                return "Best available melee prayer";
            case RANGED:
                if (p >= 74 && rigourUnlocked) return "Rigour";
                if (p >= 62 && deadeyeUnlocked) return "Deadeye";
                if (p >= 44) return "Eagle Eye";
                if (p >= 26) return "Hawk Eye";
                return "Sharp Eye";
            case MAGIC:
                if (p >= 77 && auguryUnlocked) return "Augury";
                if (p >= 63 && mysticVigourUnlocked) return "Mystic Vigour";
                if (p >= 45) return "Mystic Might";
                if (p >= 27) return "Mystic Lore";
                return "Mystic Will";
            default:
                return "None";
        }
    }
}

package com.personalbis;
public final class AncientSpellEffects {
 private AncientSpellEffects(){}
 public static boolean isAncient(MagicSpell s){return s!=null&&"ancient".equals(s.spellbook);}
 public static boolean isMultiTarget(MagicSpell s){return isAncient(s)&&(s.name.contains("Burst")||s.name.contains("Barrage"));}
 public static int maxTargets(MagicSpell s){return isMultiTarget(s)?9:1;}
 public static double bloodHealFraction(MagicSpell s){return isAncient(s)&&s.name.startsWith("Blood ")?0.25:0.0;}
 public static int freezeTicks(MagicSpell s){
  if(!isAncient(s)||!s.name.startsWith("Ice "))return 0;
  if(s.name.endsWith("Rush"))return 8;if(s.name.endsWith("Burst"))return 16;
  if(s.name.endsWith("Blitz"))return 24;if(s.name.endsWith("Barrage"))return 32;return 0;
 }
 public static int attackReductionPercent(MagicSpell s){
  if(!isAncient(s)||!s.name.startsWith("Shadow "))return 0;
  return (s.name.endsWith("Rush")||s.name.endsWith("Burst"))?10:15;
 }
 public static int startingPoison(MagicSpell s){return isAncient(s)&&s.name.startsWith("Smoke ")?4:0;}
 public static boolean isAncientSceptre(String weapon){
  String w=weapon==null?"":weapon.toLowerCase();return w.equals("ancient sceptre")||w.contains("ancient sceptre (l)")
   ||w.startsWith("blood ancient sceptre")||w.startsWith("ice ancient sceptre")
   ||w.startsWith("shadow ancient sceptre")||w.startsWith("smoke ancient sceptre");
 }
 public static double secondaryEffectMultiplier(String weapon){return isAncientSceptre(weapon)?1.10:1.0;}
 public static double bloodHealFraction(MagicSpell s,String weapon){return bloodHealFraction(s)*secondaryEffectMultiplier(weapon);}
 public static double freezeSeconds(MagicSpell s,String weapon){return freezeTicks(s)*0.6*secondaryEffectMultiplier(weapon);}
 public static String note(MagicSpell s){return note(s,null);}
 public static String note(MagicSpell s,String weapon){
  if(!isAncient(s))return "";
  String w=weapon==null?"":weapon.toLowerCase();
  StringBuilder n=new StringBuilder("Ancient");
  if(isMultiTarget(s))n.append(": up to 9 targets");
  if(bloodHealFraction(s)>0)n.append(isMultiTarget(s)?", heals ":"; heals ").append(trim(bloodHealFraction(s,weapon)*100)).append("% damage");
  int f=freezeTicks(s);if(f>0)n.append(isMultiTarget(s)?", freeze ":"; freeze ").append(trim(freezeSeconds(s,weapon))).append("s");
  int a=attackReductionPercent(s);if(a>0)n.append(isMultiTarget(s)?", Attack -":"; Attack -").append(a).append("%");
  int poison=startingPoison(s);if(poison>0)n.append(isMultiTarget(s)?", poison starts ":"; poison starts ").append(poison);
  if(isAncientSceptre(weapon))n.append("; sceptre +10% secondary effects");
  if(w.startsWith("blood ancient sceptre")&&s.name.startsWith("Blood "))n.append("; can overheal +10% HP");
  if(w.startsWith("ice ancient sceptre")&&s.name.startsWith("Ice "))n.append("; +10% accuracy if target is freezable and unfrozen (conditional; not ranked)");
  if(w.startsWith("shadow ancient sceptre")&&s.name.startsWith("Shadow "))n.append("; also drains Strength/Defence");
  if(w.startsWith("smoke ancient sceptre")&&s.name.startsWith("Smoke "))n.append("; poisoned target healing -20%");
  n.append("; ranked by single-target DPS");return n.toString();
 }
 private static String trim(double x){String s=String.format(java.util.Locale.ROOT,"%.2f",x);while(s.endsWith("0"))s=s.substring(0,s.length()-1);if(s.endsWith("."))s=s.substring(0,s.length()-1);return s;}
}

