package com.personalbis;
import java.util.Map;
public final class BestStyleSelection {
 private BestStyleSelection(){}
 public static AttackStyle best(Map<AttackStyle,Double> scores){
  AttackStyle best=null; double score=Double.NEGATIVE_INFINITY;
  for(AttackStyle s:AttackStyle.values()){double v=scores.getOrDefault(s,Double.NEGATIVE_INFINITY);if(v>score){score=v;best=s;}}
  return best;
 }
}

package com.personalbis;
public final class CombatEffectiveLevels {
 private CombatEffectiveLevels(){}
 public static int melee(int boosted,double prayer,int styleBonus,boolean voidMelee){
  int e=(int)Math.floor(Math.max(1,boosted)*prayer)+styleBonus+8;
  return voidMelee?(int)Math.floor(e*1.10):e;
 }
 public static int ranged(int boosted,double prayer,int styleBonus,boolean voidRanged){
  int e=(int)Math.floor(Math.max(1,boosted)*prayer)+styleBonus+8;
  return voidRanged?(int)Math.floor(e*11.0/10.0):e;
 }
 public static int rangedDamage(int boosted,double prayer,int styleBonus,boolean voidRanged,boolean eliteVoidRanged){
  int e=(int)Math.floor(Math.max(1,boosted)*prayer)+styleBonus+8;
  if(eliteVoidRanged)return (int)Math.floor(e*9.0/8.0);
  return voidRanged?(int)Math.floor(e*11.0/10.0):e;
 }
 public static int magic(int boosted,double prayer,boolean voidMagic,int poweredStyleBonus){
  int e=(int)Math.floor(Math.max(1,boosted)*prayer);
  if(voidMagic)e=(int)Math.floor(e*1.45);
  return e+poweredStyleBonus+9;
 }
}

package com.personalbis;

public final class CombatResult
{
    private final double dps;
    private final double expectedTtkSeconds;
    private final double accuracy;
    private final int maxHit;
    private final int attackRoll;
    private final int defenceRoll;
    private final int attackBonus;
    private final int strengthBonus;
    private final int attackSpeed;
    private final int effectiveAttack;
    private final int effectiveStrength;
    private final int preWeaponAttackRoll;
    private final int preWeaponMaxHit;
    private final MeleeStance stance;
    private final MeleePrayer prayer;

    public CombatResult(double dps, double accuracy, int maxHit, int attackRoll, int defenceRoll,
        int attackBonus, int strengthBonus, int attackSpeed, int effectiveAttack, int effectiveStrength,
        MeleeStance stance, MeleePrayer prayer, int preWeaponAttackRoll, int preWeaponMaxHit)
    {
        this(dps,Double.POSITIVE_INFINITY,accuracy,maxHit,attackRoll,defenceRoll,attackBonus,
            strengthBonus,attackSpeed,effectiveAttack,effectiveStrength,stance,prayer,
            preWeaponAttackRoll,preWeaponMaxHit);
    }

    public CombatResult(double dps, double expectedTtkSeconds, double accuracy, int maxHit,
        int attackRoll, int defenceRoll, int attackBonus, int strengthBonus, int attackSpeed,
        int effectiveAttack, int effectiveStrength, MeleeStance stance, MeleePrayer prayer,
        int preWeaponAttackRoll, int preWeaponMaxHit)
    {
        this.dps=dps; this.expectedTtkSeconds=expectedTtkSeconds; this.accuracy=accuracy; this.maxHit=maxHit; this.attackRoll=attackRoll;
        this.defenceRoll=defenceRoll; this.attackBonus=attackBonus; this.strengthBonus=strengthBonus;
        this.attackSpeed=attackSpeed; this.effectiveAttack=effectiveAttack; this.effectiveStrength=effectiveStrength;
        this.stance=stance; this.prayer=prayer;
        this.preWeaponAttackRoll=preWeaponAttackRoll; this.preWeaponMaxHit=preWeaponMaxHit;
    }

    public double getDps(){return dps;}
    public double getExpectedTtkSeconds(){return expectedTtkSeconds;}
    public double getAccuracy(){return accuracy;}
    public int getMaxHit(){return maxHit;}
    public int getAttackRoll(){return attackRoll;}
    public int getDefenceRoll(){return defenceRoll;}
    public int getAttackBonus(){return attackBonus;}
    public int getStrengthBonus(){return strengthBonus;}
    public int getAttackSpeed(){return attackSpeed;}
    public int getEffectiveAttack(){return effectiveAttack;}
    public int getEffectiveStrength(){return effectiveStrength;}
    public MeleeStance getStance(){return stance;}
    public MeleePrayer getPrayer(){return prayer;}
    public int getPreWeaponAttackRoll(){return preWeaponAttackRoll;}
    public int getPreWeaponMaxHit(){return preWeaponMaxHit;}
}

package com.personalbis;
/** Wiki DPS parity rules for Corporeal Beast damage reduction. */
public final class CorporealBeastRules {
 private CorporealBeastRules(){}
 public static boolean isCorp(MonsterDefinition m){return m!=null&&"Corporeal Beast".equalsIgnoreCase(m.getName());}
 public static boolean meleeCorpbane(EquipmentCandidate w,AttackStyle style){
  if(w==null||style==null)return false; String n=w.getItem().getName().toLowerCase();
  if(MeleeWeaponEffects.isFang(w))return style==AttackStyle.MELEE_STAB;
  if(n.endsWith("halberd"))return style==AttackStyle.MELEE_STAB;
  if(n.contains("spear")&&!n.equals("blue moon spear"))return style==AttackStyle.MELEE_STAB;
  return false;
 }
 public static boolean reduced(MonsterDefinition m,EquipmentCandidate w,AttackStyle style){return isCorp(m)&&!meleeCorpbane(w,style);}
 /** Corp's divisionTransformer(2) floors each hitsplat after accurate-zero conversion. */
 public static double dividedSuccessfulAverage(int max){
  if(max<=0)return 0.0; return HitDistribution.linear(1.0,0,max).accurateZeroToOne().transform(HitDistribution.divide(2,0)).expectedHit();
 }
 public static double dividedUniformAverage(int min,int max){
  if(max<min)return 0.0; return HitDistribution.linear(1.0,min,max).transform(HitDistribution.divide(2,0)).expectedHit();
 }
}

package com.personalbis;

/** Wiki-source demonbane vulnerability scaling. */
public final class DemonbaneEffects {
 private DemonbaneEffects(){}
 public static int vulnerability(MonsterDefinition m){
  if(m==null)return 100;
  if(m.getId()==14179)return 200; // Yama void flare
  if(m.getId()==14176)return 120; // Yama
  if(m.getId()==7584||m.getId()==7585)return 115; // Ice Demon
  if(m.getName()!=null&&m.getName().equalsIgnoreCase("Duke Sucellus"))return 70;
  return 100;
 }
 public static double multiplier(MonsterDefinition m,int weaponPercent){
  int scaled=(int)Math.floor(weaponPercent*vulnerability(m)/100.0);
  return 1.0+scaled/100.0;
 }
}

package com.personalbis;
import java.util.*;
public final class ElementalAmuletEffects {
 private ElementalAmuletEffects(){}
 public static final class Effect {
  public final int flatMaxHit; public final String note;
  Effect(int h,String n){flatMaxHit=h;note=n;}
 }
 public static Effect evaluate(Collection<EquipmentCandidate> gear,MagicSpell spell){
  String amulet="";if(gear!=null)for(EquipmentCandidate e:gear)if(e!=null&&e.getItem()!=null&&e.getSlot()==EquipmentSlot.NECK){
   String n=e.getItem().getName().toLowerCase();
   if(n.equals("amulet of air")||n.equals("amulet of water")||n.equals("amulet of earth")||n.equals("amulet of fire")||n.equals("elemental amulet"))amulet=n;
  }
  return evaluateName(amulet,spell);
 }
 static Effect evaluateName(String amulet,MagicSpell spell){
  if(spell==null||!"standard".equals(spell.spellbook)||spell.element().isEmpty())return new Effect(0,"");
  String a=amulet==null?"":amulet.toLowerCase(), el=spell.element().toLowerCase();
  boolean matching=a.equals("elemental amulet")||a.equals("amulet of "+el);
  if(!matching)return new Effect(0,"");
  String label=a.equals("elemental amulet")?"Elemental amulet":"Amulet of "+Character.toUpperCase(el.charAt(0))+el.substring(1);
  return new Effect(2,label+": +10 Magic accuracy, +2 "+el+" max hit");
 }
}

package com.personalbis;

public final class ElementalWeaknessEffects
{
    private ElementalWeaknessEffects(){}

    public static double multiplier(MonsterDefinition monster, MagicSpell spell)
    {
        if (monster == null || spell == null || !"standard".equals(spell.spellbook)
            || spell.element().isEmpty() || spell.tier().isEmpty() || !monster.weakTo(spell.element()))
            return 0.0;
        return monster.getWeaknessSeverity() / 100.0;
    }

    public static boolean applies(MonsterDefinition monster, MagicSpell spell)
    {
        return multiplier(monster, spell) > 0.0;
    }
}

package com.personalbis;
/**
 * PvM expected-value enchanted bolt effects.
 * Accuracy-bypassing procs are modelled separately from procs which require
 * the ordinary hit to pass. Non-damage utility effects are deliberately not
 * converted into invented DPS.
 */
public final class EnchantedBoltEffects {
 private EnchantedBoltEffects(){}
 public static boolean enchanted(EquipmentCandidate a){return a!=null&&a.getItem().getName().toLowerCase().contains("(e)");}
 private static double proc(double base,boolean kandarinHard){return base*(kandarinHard?1.10:1.0);}

 /** Backwards-compatible entry point for tests/callers without weapon context. */
 public static double expectedDamagePerAttack(EquipmentCandidate ammo, MonsterDefinition m, int rangedLevel, int normalMax, double accuracy, boolean kandarinHard){
  return expectedDamagePerAttack(null,ammo,m,rangedLevel,normalMax,accuracy,kandarinHard,false);
 }

 /** Expected PvM damage for one attack, including the ordinary projectile. */
 public static double expectedDamagePerAttack(EquipmentCandidate weapon, EquipmentCandidate ammo, MonsterDefinition m, int rangedLevel, int normalMax, double accuracy, boolean kandarinHard){
  return expectedDamagePerAttack(weapon,ammo,m,rangedLevel,normalMax,accuracy,kandarinHard,false);
 }
 public static double expectedDamagePerAttack(EquipmentCandidate weapon, EquipmentCandidate ammo, MonsterDefinition m, int rangedLevel, int normalMax, double accuracy, boolean kandarinHard, boolean corpReduced){
  return damageDistribution(weapon,ammo,m,rangedLevel,normalMax,accuracy,kandarinHard,corpReduced).expectedHit();
 }

 /**
  * Wiki-style bolt pipeline. Non-ruby bolt transforms happen before accurate-zero
  * conversion; Corp then divides each hitsplat; Ruby transforms last so its proc
  * retains full damage against Corp.
  */
 public static HitDistribution damageDistribution(EquipmentCandidate weapon, EquipmentCandidate ammo, MonsterDefinition m, int rangedLevel, int normalMax, double accuracy, boolean kandarinHard, boolean corpReduced){
  HitDistribution dist=preAccurateZeroDistribution(ammo,m,rangedLevel,normalMax,accuracy,kandarinHard).accurateZeroToOne();
  if(corpReduced) dist=dist.transform(HitDistribution.divide(2,0)).flatten();
  return applyRubyAfterCorp(dist,ammo,m,kandarinHard).flatten();
 }

 /** Wiki bolt stage before modern accurate-zero conversion. Ruby is deliberately excluded. */
 public static HitDistribution preAccurateZeroDistribution(EquipmentCandidate ammo, MonsterDefinition m, int rangedLevel, int normalMax, double accuracy, boolean kandarinHard){
  HitDistribution dist=HitDistribution.linear(Math.max(0.0,Math.min(1.0,accuracy)),0,Math.max(0,normalMax));
  String n=enchanted(ammo)&&m!=null?ammo.getItem().getName().toLowerCase():"";
  if(!n.isEmpty()&&!n.contains("ruby")){
   if(n.contains("opal")) dist=bonusDamage(dist,proc(.05,kandarinHard),(int)Math.floor(rangedLevel/10.0),false);
   else if(n.contains("pearl")) dist=bonusDamage(dist,proc(.06,kandarinHard),(int)Math.floor(rangedLevel/(m.hasAttribute("fiery")?15.0:20.0)),false);
   else if(n.contains("diamond")) dist=independentReplacement(dist,proc(.10,kandarinHard),(int)Math.floor(normalMax*1.15));
   else if(n.contains("dragonstone")&&!dragonstoneBlocked(m)) dist=bonusDamage(dist,proc(.06,kandarinHard),(int)Math.floor(rangedLevel*.20),true);
   else if(n.contains("onyx")&&!m.hasAttribute("undead")) dist=accurateReplacement(dist,proc(.11,kandarinHard),(int)Math.floor(normalMax*1.20));
  }
  return dist.flatten();
 }

 /** Wiki Ruby stage after Corp division: Blood Forfeit remains full damage against Corp. */
 public static HitDistribution applyRubyAfterCorp(HitDistribution dist, EquipmentCandidate ammo, MonsterDefinition m, boolean kandarinHard){
  return applyRubyAfterCorp(dist,ammo,m,kandarinHard,m==null?0:m.getHitpoints());
 }
 public static HitDistribution applyRubyAfterCorp(HitDistribution dist, EquipmentCandidate ammo, MonsterDefinition m, boolean kandarinHard, int currentHp){
  if(dist==null||m==null||!enchanted(ammo)) return dist;
  String n=ammo.getItem().getName().toLowerCase();
  if(!n.contains("ruby")) return dist;
  double p=proc(.06,kandarinHard);
  int effect=(int)Math.min(100.0,Math.floor(Math.max(0,currentHp)*.20));
  return replaceIndependent(dist,p,effect).flatten();
 }

 /** HP values in the same bucket produce the identical Blood Forfeit damage. */
 public static int rubyHpBucket(int currentHp){
  int hp=Math.max(0,currentHp);
  return hp>=500?500:(hp/5)*5;
 }

 private static HitDistribution bonusDamage(HitDistribution base,double chance,int bonus,boolean accurateOnly){
  return base.transform(h->{
   if(accurateOnly&&!h.accurate)return HitDistribution.single(h.damage,false);
   java.util.List<HitDistribution.WeightedHit> out=new java.util.ArrayList<>();
   out.add(new HitDistribution.WeightedHit(chance,java.util.Collections.singletonList(new HitDistribution.Hitsplat(h.damage+bonus,h.accurate))));
   out.add(new HitDistribution.WeightedHit(1.0-chance,java.util.Collections.singletonList(new HitDistribution.Hitsplat(h.damage,h.accurate))));
   return new HitDistribution(out);
  });
 }
 private static HitDistribution independentReplacement(HitDistribution base,double chance,int effectMax){
  HitDistribution effect=HitDistribution.linear(1.0,0,effectMax);
  return branchReplacement(base,chance,effect,false);
 }
 private static HitDistribution accurateReplacement(HitDistribution base,double chance,int effectMax){
  HitDistribution effect=HitDistribution.linear(1.0,0,effectMax);
  return branchReplacement(base,chance,effect,true);
 }
 private static HitDistribution branchReplacement(HitDistribution base,double chance,HitDistribution effect,boolean accurateOnly){
  java.util.List<HitDistribution.WeightedHit> out=new java.util.ArrayList<>();
  for(HitDistribution.WeightedHit wh:base.hits()){
   HitDistribution.Hitsplat h=wh.hitsplats.get(0);
   if(accurateOnly&&!h.accurate){out.add(wh);continue;}
   for(HitDistribution.WeightedHit ew:effect.hits())
    out.add(new HitDistribution.WeightedHit(wh.probability*chance*ew.probability,ew.hitsplats));
   out.add(new HitDistribution.WeightedHit(wh.probability*(1.0-chance),wh.hitsplats));
  }
  return new HitDistribution(out).flatten();
 }
 private static HitDistribution replaceIndependent(HitDistribution base,double chance,int damage){
  java.util.List<HitDistribution.WeightedHit> out=new java.util.ArrayList<>();
  for(HitDistribution.WeightedHit wh:base.hits()){
   out.add(new HitDistribution.WeightedHit(wh.probability*chance,java.util.Collections.singletonList(new HitDistribution.Hitsplat(damage,true))));
   out.add(new HitDistribution.WeightedHit(wh.probability*(1.0-chance),wh.hitsplats));
  }
  return new HitDistribution(out).flatten();
 }
 /** Highest projectile hit used by the currently validated proc models.
  * Returns the ordinary max when the effect does not replace/increase the hit
  * in a way we have explicitly validated.  This is diagnostic only; EV ranking
  * continues to use expectedDamagePerAttack().
  */
 public static int validatedProcMaxHit(EquipmentCandidate ammo, MonsterDefinition m, int rangedLevel, int normalMax){
  if(!enchanted(ammo)||m==null)return normalMax;
  String n=ammo.getItem().getName().toLowerCase();
  if(n.contains("diamond"))return (int)Math.floor(normalMax*1.15);
  if(n.contains("ruby"))return (int)Math.min(100.0,Math.floor(m.getHitpoints()*.20));
  if(n.contains("opal"))return normalMax+(int)Math.floor(rangedLevel/10.0);
  if(n.contains("pearl"))return normalMax+(int)Math.floor(rangedLevel/(m.hasAttribute("fiery")?15.0:20.0));
  if(n.contains("dragonstone")&&!dragonstoneBlocked(m))return normalMax+(int)Math.floor(rangedLevel*.20);
  if(n.contains("onyx")&&!m.hasAttribute("undead"))return (int)Math.floor(normalMax*1.20);
  return normalMax;
 }

 public static boolean damageEffectModelled(EquipmentCandidate ammo){
  if(!enchanted(ammo))return false;
  String n=ammo.getItem().getName().toLowerCase();
  return n.contains("opal")||n.contains("pearl")||n.contains("ruby")||n.contains("diamond")||n.contains("dragonstone")||n.contains("onyx");
 }
 /** Target-aware diagnostic label used by the DEV bolt harness. */
 public static String validationLabel(EquipmentCandidate ammo, MonsterDefinition m, int rangedLevel, boolean kandarinHard){
  if(!enchanted(ammo))return "";
  String n=ammo.getItem().getName().toLowerCase();
  if(n.contains("opal"))return String.format("Lucky Lightning | proc %.2f%% independent accuracy | +%d damage",proc(.05,kandarinHard)*100.0,(int)Math.floor(rangedLevel/10.0));
  if(n.contains("jade"))return String.format("Earth's Fury | proc %.2f%% | utility, +0 direct DPS",proc(.05,kandarinHard)*100.0);
  if(n.contains("pearl"))return String.format("Sea Curse%s | proc %.2f%% independent accuracy | +%d damage",m!=null&&m.hasAttribute("fiery")?" (fiery)":"",proc(.06,kandarinHard)*100.0,(int)Math.floor(rangedLevel/(m!=null&&m.hasAttribute("fiery")?15.0:20.0)));
  if(n.contains("topaz"))return "Down to Earth | PvP only | +0 PvM DPS";
  if(n.contains("sapphire"))return String.format("Clear Mind | proc %.2f%% | utility, +0 direct DPS",proc(.05,kandarinHard)*100.0);
  if(n.contains("emerald"))return String.format("Magical Poison | proc %.2f%% after hit | poison DoT not ranked",proc(.55,kandarinHard)*100.0);
  if(n.contains("ruby"))return String.format("Blood Forfeit | proc %.2f%% independent accuracy | replaces hit",proc(.06,kandarinHard)*100.0);
  if(n.contains("diamond"))return String.format("Armour Piercing | proc %.2f%% independent accuracy | +15%% max",proc(.10,kandarinHard)*100.0);
  if(n.contains("onyx")){
   if(m!=null&&m.hasAttribute("undead"))return "Life Leech BLOCKED (undead) | proc 0.00%";
   return String.format("Life Leech | proc %.2f%% after hit | +20%% hit damage",proc(.11,kandarinHard)*100.0);
  }
  if(n.contains("dragonstone")){
   if(dragonstoneBlocked(m))return "Dragon's Breath BLOCKED (dragonfire immune) | proc 0.00%";
   return String.format("Dragon's Breath | proc %.2f%% after hit | +%d damage",proc(.06,kandarinHard)*100.0,(int)Math.floor(0.20*rangedLevel));
  }
  return effectLabel(ammo);
 }

 public static String validationLabel(EquipmentCandidate ammo, MonsterDefinition m, boolean kandarinHard){ return validationLabel(ammo,m,99,kandarinHard); }

 private static boolean dragonstoneBlocked(MonsterDefinition m){
  return m!=null&&(m.hasAttribute("dragonfire immune")||m.hasAttribute("dragon")||m.hasAttribute("fiery"));
 }

 public static String effectLabel(EquipmentCandidate ammo){
  if(!enchanted(ammo))return "";
  String n=ammo.getItem().getName().toLowerCase();
  if(n.contains("opal"))return "Lucky Lightning EV";
  if(n.contains("pearl"))return "Sea Curse EV";
  if(n.contains("ruby"))return "Blood Forfeit EV";
  if(n.contains("diamond"))return "Armour Piercing EV";
  if(n.contains("onyx"))return "Life Leech EV";
  if(n.contains("dragonstone"))return "Dragon's Breath EV";
  if(n.contains("jade"))return "Earth's Fury (utility; no DPS EV)";
  if(n.contains("topaz"))return "Down to Earth (PvP only)";
  if(n.contains("sapphire"))return "Clear Mind (utility; no DPS EV)";
  if(n.contains("emerald"))return "Magical Poison (DoT not ranked yet)";
  return "";
 }
}

package com.personalbis;

public final class EquipmentAuditPolicy
{
    private EquipmentAuditPolicy(){}

    public static boolean shieldAllowed(EquipmentCandidate weapon)
    {
        return weapon == null || !weapon.isTwoHanded();
    }

    public static boolean slayerAppliesToRangedOrMagic(String name)
    {
        if (name == null) return false;
        String n=name.toLowerCase();
        boolean slayer=n.contains("slayer helmet")||n.contains("slayer helm")||n.contains("black mask");
        return slayer && (n.contains("(i)")||n.contains("imbued"));
    }

    public static boolean monsterSpecificMeleeWeapon(String name, MonsterDefinition m)
    {
        if(name==null||m==null)return false;
        String n=name.toLowerCase();
        if(m.hasAttribute("demon")&&(n.contains("arclight")||n.contains("emberlight")||n.contains("silverlight")||n.contains("darklight")))return true;
        if((m.hasAttribute("dragon")||m.hasAttribute("draconic"))&&n.contains("dragon hunter lance"))return true;
        if((m.hasAttribute("kalphite")||m.hasAttribute("scabarite"))&&n.contains("keris"))return true;
        return n.contains("osmumten")&&n.contains("fang") || n.contains("scythe of vitur");
    }


    public static int magicWeaponEvaluationLimit(){ return 12; }

    /**
     * Full-set Magic synergies must enter the optimizer before ordinary slot pruning,
     * otherwise individually weak pieces can never be evaluated as a complete set.
     */
    public static boolean seedCompleteMagicSetsBeforePruning(){ return true; }
    public static int meleeWeaponEvaluationLimit(){ return 12; }
    public static int rangedWeaponEvaluationLimit(){ return 12; }

    // Alpha 50.4: retained legacy limits document the old heuristic, but weapon
    // optimizers deliberately evaluate all owned/equippable candidates.
    public static boolean evaluateAllOwnedMeleeWeapons(){ return true; }
    public static boolean evaluateAllOwnedRangedWeapons(){ return true; }

    public static boolean specialMagicWeapon(String name, MonsterDefinition m)
    {
        if(name==null)return false; String n=name.toLowerCase();
        if(PoweredStaff.forWeapon(n)!=null||PoweredStaff.requiresContext(n))return true;
        if(n.contains("iban")||n.contains("slayer's staff")||n.contains("slayer staff")
            ||n.contains("ancient staff")||n.contains("ancient sceptre")||n.contains("kodai")
            ||n.contains("nightmare staff")||n.contains("master wand")
            ||n.contains("saradomin staff")||n.contains("guthix staff")||n.contains("zamorak staff")
            ||n.contains("staff of light")||n.contains("staff of balance")||n.contains("staff of the dead")
            ||n.contains("dragon hunter wand")||n.contains("twinflame")||n.contains("smoke battlestaff")
            ||n.contains("mystic smoke staff"))return true;
        String e=m==null?"":m.getWeaknessElement();
        return !e.isEmpty()&&elementalRuneProvider(n,e);
    }
    private static boolean elementalRuneProvider(String n,String e)
    {
        if(!(n.contains("staff")||n.contains("battlestaff")))return false;
        if(e.equals("air"))return n.contains("air")||n.contains("smoke")||n.contains("dust")||n.contains("mist");
        if(e.equals("water"))return n.contains("water")||n.contains("steam")||n.contains("mud")||n.contains("mist");
        if(e.equals("earth"))return n.contains("earth")||n.contains("lava")||n.contains("mud")||n.contains("dust");
        if(e.equals("fire"))return n.contains("fire")||n.contains("lava")||n.contains("smoke")||n.contains("steam");
        return false;
    }
    public static boolean specialRangedWeapon(String name)
    {
        if(name==null)return false; String n=name.toLowerCase();
        return n.contains("twisted bow")||n.contains("bow of faerdhinen")||n.contains("crystal bow")
            ||n.contains("blowpipe")||n.contains("dragon hunter crossbow")||n.contains("webweaver")
            ||n.contains("craw's bow")||n.contains("venator bow")||n.contains("dark bow")
            ||n.contains("tonalztics of ralos")||n.contains("karil's crossbow");
    }
}

package com.personalbis;

public class EquipmentCandidate
{
    private final BankItem item;
    private final EquipmentSlot slot;
    private final int score;
    private final int attackBonus;
    private final int strengthBonus;
    private final int rangedAttack;
    private final int rangedStrength;
    private final int magicAttack;
    private final float magicDamage;
    private final int prayer;
    private final int attackSpeed;
    private final boolean twoHanded;
    private final String weaponCategory;
    private final RequirementResult requirementResult;

    public EquipmentCandidate(BankItem item, EquipmentSlot slot, int score,
        int attackBonus, int strengthBonus, int rangedAttack, int rangedStrength,
        int magicAttack, float magicDamage, int prayer, int attackSpeed,
        boolean twoHanded, String weaponCategory, RequirementResult requirementResult)
    {
        this.item = item;
        this.slot = slot;
        this.score = score;
        this.attackBonus = attackBonus;
        this.strengthBonus = strengthBonus;
        this.rangedAttack = rangedAttack;
        this.rangedStrength = rangedStrength;
        this.magicAttack = magicAttack;
        this.magicDamage = magicDamage;
        this.prayer = prayer;
        this.attackSpeed = attackSpeed;
        this.twoHanded = twoHanded;
        this.weaponCategory = weaponCategory == null ? "" : weaponCategory;
        this.requirementResult = requirementResult;
    }

    public BankItem getItem() { return item; }
    public EquipmentSlot getSlot() { return slot; }
    public int getScore() { return score; }
    public int getAttackBonus() { return attackBonus; }
    public int getStrengthBonus() { return strengthBonus; }
    public int getRangedAttack() { return rangedAttack; }
    public int getRangedStrength() { return rangedStrength; }
    public int getMagicAttack() { return magicAttack; }
    public float getMagicDamage() { return magicDamage; }
    public int getPrayer() { return prayer; }
    public int getAttackSpeed() { return attackSpeed; }
    public boolean isTwoHanded() { return twoHanded; }
    public String getWeaponCategory() { return weaponCategory; }
    public RequirementResult getRequirementResult() { return requirementResult; }
}

package com.personalbis;

import java.util.ArrayList;
import java.util.Collections;
import java.util.Comparator;
import java.util.EnumMap;
import java.util.List;
import java.util.Map;
import javax.inject.Inject;
import net.runelite.client.game.ItemEquipmentStats;
import net.runelite.client.game.ItemManager;
import net.runelite.client.game.ItemStats;
import com.personalbis.wiki.WikiDataPack;
import com.personalbis.wiki.WikiEquipment;

public class EquipmentIntelligence
{
    private final ItemManager itemManager;
    private final ItemRequirementRegistry requirementRegistry;
    private final WikiDataPack wikiDataPack;

    @Inject
    public EquipmentIntelligence(ItemManager itemManager, ItemRequirementRegistry requirementRegistry, WikiDataPack wikiDataPack)
    {
        this.itemManager = itemManager;
        this.requirementRegistry = requirementRegistry;
        this.wikiDataPack = wikiDataPack;
    }

    public Map<EquipmentSlot, List<EquipmentCandidate>> rank(List<BankItem> bank, AttackStyle style)
    {
        return rank(bank, style, false);
    }

    public Map<EquipmentSlot, List<EquipmentCandidate>> rank(List<BankItem> bank, AttackStyle style, boolean onSlayerTask)
    {
        Map<EquipmentSlot, List<EquipmentCandidate>> ranked = new EnumMap<>(EquipmentSlot.class);
        for (EquipmentSlot slot : EquipmentSlot.values())
        {
            ranked.put(slot, new ArrayList<EquipmentCandidate>());
        }

        for (BankItem bankItem : bank)
        {
            int canonicalId = itemManager.canonicalize(bankItem.getItemId());
            ItemStats itemStats = itemManager.getItemStats(canonicalId);
            if (itemStats == null || !itemStats.isEquipable() || itemStats.getEquipment() == null)
            {
                continue;
            }

            ItemEquipmentStats equipment = itemStats.getEquipment();
            EquipmentSlot slot = EquipmentSlot.fromRuneLiteSlot(equipment.getSlot());
            if (slot == null)
            {
                continue;
            }

            RequirementResult requirements = requirementRegistry.check(bankItem, slot);
            WikiEquipment wiki = wikiDataPack.getEquipment(WikiEquipmentEngine.canonicalId(canonicalId));
            int attackBonus = wiki != null ? attackForStyle(wiki, style) : attackForStyle(equipment, style);
            int score = (wiki != null ? score(wiki, style, requirements) : score(equipment, style, requirements))
                + slayerTaskBonus(bankItem.getName(), style, onSlayerTask);

            ranked.get(slot).add(new EquipmentCandidate(
                bankItem,
                slot,
                score,
                attackBonus,
                wiki != null && wiki.bonuses != null ? wiki.bonuses.str : equipment.getStr(),
                wiki != null && wiki.offensive != null ? wiki.offensive.ranged : equipment.getArange(),
                wiki != null && wiki.bonuses != null ? wiki.bonuses.ranged_str : equipment.getRstr(),
                wiki != null && wiki.offensive != null ? wiki.offensive.magic : equipment.getAmagic(),
                wiki != null && wiki.bonuses != null ? (float)(wiki.bonuses.magic_str / 1000.0) : equipment.getMdmg(),
                wiki != null && wiki.bonuses != null ? wiki.bonuses.prayer : equipment.getPrayer(),
                wiki != null ? wiki.speed : equipment.getAspeed(),
                wiki != null ? wiki.isTwoHanded : equipment.isTwoHanded(),
                wiki != null ? wiki.category : "",
                requirements));
        }

        Comparator<EquipmentCandidate> comparator = new Comparator<EquipmentCandidate>()
        {
            @Override
            public int compare(EquipmentCandidate a, EquipmentCandidate b)
            {
                if (a.getRequirementResult().isBlocked() != b.getRequirementResult().isBlocked())
                {
                    return a.getRequirementResult().isBlocked() ? 1 : -1;
                }
                int scoreCompare = Integer.compare(b.getScore(), a.getScore());
                if (scoreCompare != 0)
                {
                    return scoreCompare;
                }
                return a.getItem().getName().compareToIgnoreCase(b.getItem().getName());
            }
        };

        for (List<EquipmentCandidate> candidates : ranked.values())
        {
            Collections.sort(candidates, comparator);
        }

        return ranked;
    }

    public List<EquipmentCandidate> allForSlot(List<BankItem> bank, AttackStyle style, EquipmentSlot slot)
    {
        Map<EquipmentSlot, List<EquipmentCandidate>> ranked = rank(bank, style);
        List<EquipmentCandidate> candidates = ranked.get(slot);
        return candidates == null ? Collections.<EquipmentCandidate>emptyList() : candidates;
    }

    private int attackForStyle(WikiEquipment stats, AttackStyle style)
    {
        if (stats.offensive == null) return 0;
        switch (style)
        {
            case MELEE_STAB: return stats.offensive.stab;
            case MELEE_SLASH: return stats.offensive.slash;
            case MELEE_CRUSH: return stats.offensive.crush;
            case RANGED: return stats.offensive.ranged;
            case MAGIC: return stats.offensive.magic;
            default: return 0;
        }
    }

    private int score(WikiEquipment stats, AttackStyle style, RequirementResult requirements)
    {
        int attack = attackForStyle(stats, style);
        int prayer = stats.bonuses == null ? 0 : stats.bonuses.prayer;
        int base;
        switch (style)
        {
            case MELEE_STAB:
            case MELEE_SLASH:
            case MELEE_CRUSH:
                base = attack * 2 + (stats.bonuses == null ? 0 : stats.bonuses.str) * 5 + prayer;
                break;
            case RANGED:
                base = attack * 2 + (stats.bonuses == null ? 0 : stats.bonuses.ranged_str) * 5 + prayer;
                break;
            case MAGIC:
                base = attack * 2 + (stats.bonuses == null ? 0 : (int)Math.round(stats.bonuses.magic_str * 10.0)) + prayer;
                break;
            default:
                base = 0;
        }
        return requirements.isBlocked() ? base - 1000000 : base;
    }

    private int attackForStyle(ItemEquipmentStats stats, AttackStyle style)
    {
        switch (style)
        {
            case MELEE_STAB: return stats.getAstab();
            case MELEE_SLASH: return stats.getAslash();
            case MELEE_CRUSH: return stats.getAcrush();
            case RANGED: return stats.getArange();
            case MAGIC: return stats.getAmagic();
            default: return 0;
        }
    }

    private int slayerTaskBonus(String itemName, AttackStyle style, boolean onSlayerTask)
    {
        if (!onSlayerTask || itemName == null)
        {
            return 0;
        }

        String name = itemName.toLowerCase();

        // Slayer helmets and black masks are deliberately given a large selection
        // bonus while on-task so the owned-gear planner accounts for their task
        // damage/accuracy effect. Imbued variants also apply to ranged and magic.
        boolean slayerHelm = name.contains("slayer helmet") || name.contains("slayer helm");
        boolean blackMask = name.contains("black mask");
        if (!slayerHelm && !blackMask)
        {
            return 0;
        }

        if (style == AttackStyle.RANGED || style == AttackStyle.MAGIC)
        {
            return name.contains("(i)") || name.contains("imbued") ? 100000 : 0;
        }

        return 100000;
    }

    private int score(ItemEquipmentStats stats, AttackStyle style, RequirementResult requirements)
    {
        int base;
        switch (style)
        {
            case MELEE_STAB:
                base = stats.getAstab() * 2 + stats.getStr() * 5 + stats.getPrayer();
                break;
            case MELEE_SLASH:
                base = stats.getAslash() * 2 + stats.getStr() * 5 + stats.getPrayer();
                break;
            case MELEE_CRUSH:
                base = stats.getAcrush() * 2 + stats.getStr() * 5 + stats.getPrayer();
                break;
            case RANGED:
                base = stats.getArange() * 2 + stats.getRstr() * 5 + stats.getPrayer();
                break;
            case MAGIC:
                base = stats.getAmagic() * 2 + Math.round(stats.getMdmg() * 1000f) + stats.getPrayer();
                break;
            default:
                base = 0;
        }

        return requirements.isBlocked() ? base - 1000000 : base;
    }
}

package com.personalbis;

import net.runelite.api.EquipmentInventorySlot;

public enum EquipmentSlot
{
    HEAD("Head", EquipmentInventorySlot.HEAD),
    CAPE("Cape", EquipmentInventorySlot.CAPE),
    NECK("Neck", EquipmentInventorySlot.AMULET),
    WEAPON("Weapon", EquipmentInventorySlot.WEAPON),
    BODY("Body", EquipmentInventorySlot.BODY),
    SHIELD("Shield", EquipmentInventorySlot.SHIELD),
    LEGS("Legs", EquipmentInventorySlot.LEGS),
    HANDS("Hands", EquipmentInventorySlot.GLOVES),
    FEET("Feet", EquipmentInventorySlot.BOOTS),
    RING("Ring", EquipmentInventorySlot.RING),
    AMMO("Ammo", EquipmentInventorySlot.AMMO);

    private final String displayName;
    private final EquipmentInventorySlot runeLiteSlot;

    EquipmentSlot(String displayName, EquipmentInventorySlot runeLiteSlot)
    {
        this.displayName = displayName;
        this.runeLiteSlot = runeLiteSlot;
    }

    public String getDisplayName()
    {
        return displayName;
    }

    public int getSlotIndex()
    {
        return runeLiteSlot.getSlotIdx();
    }

    public static EquipmentSlot fromRuneLiteSlot(int slot)
    {
        for (EquipmentSlot value : values())
        {
            if (value.getSlotIndex() == slot)
            {
                return value;
            }
        }
        return null;
    }

    @Override
    public String toString()
    {
        return displayName;
    }
}

package com.personalbis;

/** Shared expected-damage formula for a successful OSRS hit. */
public final class ExpectedHitFormula
{
    private ExpectedHitFormula(){}

    public static double successfulHitAverage(int maxHit)
    {
        if(maxHit<=0)return 0.0;
        return maxHit/2.0 + 1.0/(maxHit+1.0);
    }
}

package com.personalbis;

import java.util.function.IntFunction;
import java.util.Map;
import java.util.TreeMap;
import java.util.concurrent.ConcurrentHashMap;

/** Expected attacks/time to reduce a finite HP pool to zero. */
public final class ExpectedKillTime
{
    private static final Map<String,Double> STATIC_CACHE=new ConcurrentHashMap<>();
    private static final int CACHE_LIMIT=32768;

    private ExpectedKillTime(){}

    public static double seconds(HitDistribution.AttackDistribution distribution, int hitpoints, int attackTicks)
    {
        if (hitpoints <= 0) return 0.0;
        if (attackTicks <= 0 || distribution == null) return Double.POSITIVE_INFINITY;
        return seconds(distribution.zipped().cumulative(),hitpoints,attackTicks);
    }

    private static double seconds(HitDistribution total, int hitpoints, int attackTicks)
    {
        Map<Integer,Double> probabilities=new TreeMap<>();
        for(HitDistribution.WeightedHit hit:total.hits())
        {
            int damage=Math.max(0,hit.sum());
            probabilities.put(damage,probabilities.getOrDefault(damage,0.0)+hit.probability);
        }
        double zero=probabilities.getOrDefault(0,0.0),progress=1.0-zero;
        if(progress<=1e-12)return Double.POSITIVE_INFINITY;
        String key=cacheKey(probabilities,hitpoints,attackTicks);
        Double cached=STATIC_CACHE.get(key);
        if(cached!=null)return cached;
        if(STATIC_CACHE.size()>CACHE_LIMIT)STATIC_CACHE.clear();

        double[] attacks=new double[hitpoints+1];
        int maximum=probabilities.isEmpty()?0:((TreeMap<Integer,Double>)probabilities).lastKey();
        double base=maximum>0?probabilities.getOrDefault(maximum,0.0):0.0;
        boolean dense=base>0.0;
        for(int damage=2;damage<=maximum&&dense;damage++)
            dense=close(probabilities.getOrDefault(damage,0.0),base);
        double first=probabilities.getOrDefault(1,0.0);
        boolean uniform=dense&&close(first,base),modern=dense&&close(first,2.0*base);
        if(uniform||modern)
        {
            double window=0.0;
            for(int hp=1;hp<=hitpoints;hp++)
            {
                window+=attacks[hp-1];
                int expired=hp-maximum-1;
                if(expired>=0)window-=attacks[expired];
                double continuation=base*window+(modern?base*attacks[hp-1]:0.0);
                attacks[hp]=(1.0+continuation)/progress;
            }
        }
        else for(int hp=1;hp<=hitpoints;hp++)
        {
            double continuation=0.0;
            for(Map.Entry<Integer,Double> outcome:probabilities.entrySet())
            {
                int damage=outcome.getKey();
                if(damage>0&&damage<hp)continuation+=outcome.getValue()*attacks[hp-damage];
            }
            attacks[hp]=(1.0+continuation)/progress;
        }
        double result=attacks[hitpoints]*attackTicks*0.6;
        STATIC_CACHE.put(key,result);
        return result;
    }

    private static boolean close(double a,double b)
    {
        return Math.abs(a-b)<=1e-12*Math.max(1.0,Math.max(Math.abs(a),Math.abs(b)));
    }

    private static String cacheKey(Map<Integer,Double> probabilities,int hitpoints,int attackTicks)
    {
        StringBuilder key=new StringBuilder().append(hitpoints).append('/').append(attackTicks);
        for(Map.Entry<Integer,Double> outcome:probabilities.entrySet())key.append(';').append(outcome.getKey())
            .append(':').append(Long.toHexString(Double.doubleToLongBits(outcome.getValue())));
        return key.toString();
    }

    /** Supports effects such as Ruby bolts whose distribution changes with remaining HP. */
    public static double seconds(int hitpoints, int attackTicks,
        IntFunction<HitDistribution.AttackDistribution> distributionAtHp)
    {
        if (hitpoints <= 0) return 0.0;
        if (attackTicks <= 0 || distributionAtHp == null) return Double.POSITIVE_INFINITY;
        double[] attacks = new double[hitpoints + 1];
        for (int hp = 1; hp <= hitpoints; hp++)
        {
            HitDistribution.AttackDistribution attack = distributionAtHp.apply(hp);
            if (attack == null) return Double.POSITIVE_INFINITY;
            HitDistribution total = attack.zipped().cumulative();
            double zero = 0.0, continuation = 0.0;
            for (HitDistribution.WeightedHit hit : total.hits())
            {
                int damage = Math.max(0, hit.sum());
                if (damage == 0) zero += hit.probability;
                else if (damage < hp) continuation += hit.probability * attacks[hp - damage];
            }
            double progress = 1.0 - zero;
            if (progress <= 1e-12) return Double.POSITIVE_INFINITY;
            attacks[hp] = (1.0 + continuation) / progress;
        }
        return attacks[hitpoints] * attackTicks * 0.6;
    }

    public static double approximateSeconds(int hitpoints, double dps)
    {
        return hitpoints > 0 && dps > 0.0 && Double.isFinite(dps)
            ? hitpoints / dps : Double.POSITIVE_INFINITY;
    }
}

package com.personalbis;

public final class FinalLoadoutSelection
{
    private FinalLoadoutSelection(){}

    public static boolean better(double candidateDps, double currentDps)
    {
        return Double.isFinite(candidateDps) &&
            (!Double.isFinite(currentDps) || candidateDps > currentDps);
    }

    /** Finite-fight ordering: lower expected TTK wins, sustained DPS breaks ties. */
    public static boolean betterTtk(double candidateTtk, double candidateDps,
        double currentTtk, double currentDps)
    {
        if (!Double.isFinite(candidateTtk)) return false;
        if (!Double.isFinite(currentTtk)) return true;
        int ttk = Double.compare(candidateTtk,currentTtk);
        return ttk < 0 || (ttk == 0 && better(candidateDps,currentDps));
    }

    public static int compareTtk(double leftTtk, double leftDps, double rightTtk, double rightDps)
    {
        double l=Double.isFinite(leftTtk)?leftTtk:Double.POSITIVE_INFINITY;
        double r=Double.isFinite(rightTtk)?rightTtk:Double.POSITIVE_INFINITY;
        int ttk=Double.compare(l,r);
        return ttk!=0?ttk:Double.compare(rightDps,leftDps);
    }

    public static boolean compatibleShield(EquipmentCandidate weapon, EquipmentCandidate shield)
    {
        return shield == null || weapon == null || !weapon.isTwoHanded();
    }

    public static boolean compatibleAmmo(EquipmentCandidate weapon, EquipmentCandidate ammo)
    {
        if (weapon == null) return ammo == null;
        if (!RangedAmmoRules.usesExternalAmmo(weapon)) return ammo == null;
        return ammo != null && RangedAmmoRules.compatible(weapon, ammo);
    }
}

package com.personalbis;

import java.util.*;
import java.util.function.Function;

/**
 * Integer hitsplat distribution model ported from the OSRS Wiki DPS calculator HitDist layer.
 * Keeps accuracy state separate from damage so target transforms can operate per hitsplat.
 */
public final class HitDistribution {
    public static final class Hitsplat {
        public final int damage;
        public final boolean accurate;
        public Hitsplat(int damage, boolean accurate){ this.damage=damage; this.accurate=accurate; }
    }
    public static final class WeightedHit {
        public final double probability;
        public final List<Hitsplat> hitsplats;
        public WeightedHit(double probability,List<Hitsplat> hitsplats){this.probability=probability;this.hitsplats=Collections.unmodifiableList(new ArrayList<>(hitsplats));}
        int sum(){int s=0;for(Hitsplat h:hitsplats)s+=h.damage;return s;}
        boolean anyAccurate(){for(Hitsplat h:hitsplats)if(h.accurate)return true;return false;}
    }
    public interface Transformer extends Function<Hitsplat,HitDistribution>{}
    private final List<WeightedHit> hits;
    public HitDistribution(List<WeightedHit> hits){this.hits=Collections.unmodifiableList(new ArrayList<>(hits));}
    public List<WeightedHit> hits(){return hits;}

    public static HitDistribution linear(double accuracy,int minimum,int maximum){
        List<WeightedHit> out=new ArrayList<>();
        double p=accuracy/(maximum-minimum+1.0);
        for(int i=minimum;i<=maximum;i++)out.add(new WeightedHit(p,Collections.singletonList(new Hitsplat(i,true))));
        if(accuracy!=1.0)out.add(new WeightedHit(1.0-accuracy,Collections.singletonList(new Hitsplat(0,false))));
        return new HitDistribution(out);
    }
    /** Wiki modern successful-zero conversion: an accurate zero becomes one. */
    public HitDistribution accurateZeroToOne(){return transform(h->single(Math.max(1,h.damage),h.accurate),false);}
    public HitDistribution transform(Transformer t){return transform(t,true);}
    public HitDistribution transform(Transformer t,boolean transformInaccurate){
        List<WeightedHit> out=new ArrayList<>();
        for(WeightedHit wh:hits){
            HitDistribution acc=new HitDistribution(Collections.singletonList(new WeightedHit(wh.probability,Collections.emptyList())));
            for(Hitsplat h:wh.hitsplats){
                HitDistribution part=(!h.accurate&&!transformInaccurate)?single(h.damage,false):t.apply(h);
                acc=acc.zip(part);
            }
            out.addAll(acc.hits);
        }
        return new HitDistribution(out).flatten();
    }
    public HitDistribution zip(HitDistribution other){
        List<WeightedHit> out=new ArrayList<>();
        for(WeightedHit a:hits)for(WeightedHit b:other.hits){List<Hitsplat> hs=new ArrayList<>(a.hitsplats);hs.addAll(b.hitsplats);out.add(new WeightedHit(a.probability*b.probability,hs));}
        return new HitDistribution(out);
    }
    public HitDistribution flatten(){
        Map<String,Double> probs=new LinkedHashMap<>(); Map<String,List<Hitsplat>> lists=new LinkedHashMap<>();
        for(WeightedHit wh:hits){StringBuilder k=new StringBuilder();for(Hitsplat h:wh.hitsplats)k.append(h.damage).append(':').append(h.accurate?'1':'0').append(';');String key=k.toString();probs.put(key,probs.getOrDefault(key,0.0)+wh.probability);lists.putIfAbsent(key,wh.hitsplats);}
        List<WeightedHit> out=new ArrayList<>();for(Map.Entry<String,Double> e:probs.entrySet())if(e.getValue()>0)out.add(new WeightedHit(e.getValue(),lists.get(e.getKey())));return new HitDistribution(out);
    }
    public HitDistribution cumulative(){
        Map<String,Double> probs=new LinkedHashMap<>();
        for(WeightedHit wh:hits){String key=wh.sum()+":"+(wh.anyAccurate()?1:0);probs.put(key,probs.getOrDefault(key,0.0)+wh.probability);}
        List<WeightedHit> out=new ArrayList<>();for(Map.Entry<String,Double> e:probs.entrySet()){String[] p=e.getKey().split(":");out.add(new WeightedHit(e.getValue(),Collections.singletonList(new Hitsplat(Integer.parseInt(p[0]),"1".equals(p[1])))));}return new HitDistribution(out);
    }
    public double expectedHit(){double v=0;for(WeightedHit wh:hits)v+=wh.probability*wh.sum();return v;}
    public int size(){return hits.size();}
    /** Wiki HitDist.scaleProbability. */
    public HitDistribution scaleProbability(double factor){List<WeightedHit> out=new ArrayList<>();for(WeightedHit wh:hits)out.add(new WeightedHit(wh.probability*factor,wh.hitsplats));return new HitDistribution(out);}
    /** Wiki HitDist.scaleDamage with per-hitsplat truncation. */
    public HitDistribution scaleDamage(int numerator,int divisor){if(divisor==0)throw new IllegalArgumentException("divisor");List<WeightedHit> out=new ArrayList<>();for(WeightedHit wh:hits){List<Hitsplat> hs=new ArrayList<>();for(Hitsplat h:wh.hitsplats)hs.add(new Hitsplat((int)(((long)h.damage*numerator)/divisor),h.accurate));out.add(new WeightedHit(wh.probability,hs));}return new HitDistribution(out);}
    public HitDistribution scaleDamage(int factor){return scaleDamage(factor,1);}
    public int min(){int v=Integer.MAX_VALUE;for(WeightedHit wh:hits)v=Math.min(v,wh.sum());return v==Integer.MAX_VALUE?0:v;}
    public int max(){int v=Integer.MIN_VALUE;for(WeightedHit wh:hits)v=Math.max(v,wh.sum());return v==Integer.MIN_VALUE?0:v;}
    public double probability(){double p=0;for(WeightedHit wh:hits)p+=wh.probability;return p;}

    public static HitDistribution single(int damage,boolean accurate){return new HitDistribution(Collections.singletonList(new WeightedHit(1.0,Collections.singletonList(new Hitsplat(damage,accurate)))));}
    /** Wiki HitDistribution.single(accuracy, hitsplats). */
    public static HitDistribution single(double accuracy,List<Hitsplat> hitsplats){List<WeightedHit> out=new ArrayList<>();out.add(new WeightedHit(accuracy,hitsplats));if(accuracy!=1.0)out.add(new WeightedHit(1.0-accuracy,Collections.singletonList(new Hitsplat(0,false))));return new HitDistribution(out);}
    public static Transformer flatLimit(int maximum,int minimum){return h->single(Math.max(minimum,Math.min(h.damage,maximum)),h.accurate);}
    public static Transformer multiply(int numerator,int divisor,int minimum){return h->{int d=(numerator*h.damage)/divisor;if(minimum!=0)d=h.damage>=minimum?Math.max(minimum,d):Math.max(h.damage,d);return single(d,h.accurate);};}
    public static Transformer divide(int divisor,int minimum){return multiply(1,divisor,minimum);}
    public static Transformer flatAdd(int addend,int minimum){return h->single(Math.max(minimum,h.damage+addend),h.accurate);}
    public static Transformer linearMin(int maximum,int offset){return h->{List<WeightedHit> out=new ArrayList<>();double p=1.0/(maximum+1.0);for(int i=0;i<=maximum;i++)out.add(new WeightedHit(p,Collections.singletonList(new Hitsplat(Math.min(h.damage,i+offset),h.accurate))));return new HitDistribution(out).flatten();};}
    public static Transformer cappedReroll(int limit,int rollMax,int offset){return h->{if(h.damage<=limit)return single(h.damage,h.accurate);List<WeightedHit> out=new ArrayList<>();double p=1.0/(rollMax+1.0);for(int i=0;i<=rollMax;i++)out.add(new WeightedHit(p,Collections.singletonList(new Hitsplat(i+offset,h.accurate))));return new HitDistribution(out).flatten();};}

    /** Structural port of Wiki HitDist.AttackDistribution. */
    public static final class AttackDistribution {
        private final List<HitDistribution> dists;
        public AttackDistribution(List<HitDistribution> dists){this.dists=new ArrayList<>(dists);}
        public List<HitDistribution> dists(){return Collections.unmodifiableList(dists);}
        public void addDist(HitDistribution d){dists.add(d);}
        public HitDistribution zipped(){if(dists.isEmpty())return HitDistribution.single(0,false);HitDistribution r=dists.get(0);for(int i=1;i<dists.size();i++)r=r.zip(dists.get(i));return r;}
        public HitDistribution singleHitsplat(){if(dists.isEmpty())return HitDistribution.single(0,false);HitDistribution r=dists.get(0);for(int i=1;i<dists.size();i++)r=r.zip(dists.get(i)).cumulative();return r;}
        public AttackDistribution transform(Transformer t,boolean transformInaccurate){List<HitDistribution> o=new ArrayList<>();for(HitDistribution d:dists)o.add(d.transform(t,transformInaccurate));return new AttackDistribution(o);}
        public AttackDistribution flatten(){List<HitDistribution> o=new ArrayList<>();for(HitDistribution d:dists)o.add(d.flatten());return new AttackDistribution(o);}
        public AttackDistribution scaleProbability(double f){List<HitDistribution> o=new ArrayList<>();for(HitDistribution d:dists)o.add(d.scaleProbability(f));return new AttackDistribution(o);}
        public AttackDistribution scaleDamage(int n,int div){List<HitDistribution> o=new ArrayList<>();for(HitDistribution d:dists)o.add(d.scaleDamage(n,div));return new AttackDistribution(o);}
        public int min(){int v=0;for(HitDistribution d:dists)v+=d.min();return v;} public int max(){int v=0;for(HitDistribution d:dists)v+=d.max();return v;} public double expectedDamage(){double v=0;for(HitDistribution d:dists)v+=d.expectedHit();return v;}
        public AttackDistribution firstHitMax(){if(dists.isEmpty())return this;HitDistribution first=dists.get(0);int mx=0;for(WeightedHit wh:first.hits)if(!wh.hitsplats.isEmpty()&&wh.hitsplats.get(0).accurate)mx=Math.max(mx,wh.hitsplats.get(0).damage);List<WeightedHit> hs=new ArrayList<>();for(WeightedHit wh:first.hits){if(wh.hitsplats.isEmpty()||!wh.hitsplats.get(0).accurate){hs.add(wh);continue;}List<Hitsplat> spl=new ArrayList<>(wh.hitsplats);spl.set(0,new Hitsplat(mx,true));hs.add(new WeightedHit(wh.probability,spl));}List<HitDistribution> o=new ArrayList<>();o.add(new HitDistribution(hs).flatten());o.addAll(dists.subList(1,dists.size()));return new AttackDistribution(o);}
        public AttackDistribution firstHitAccurate(){if(dists.isEmpty())return this;List<WeightedHit> hs=new ArrayList<>();double p=0;for(WeightedHit wh:dists.get(0).hits)if(!wh.hitsplats.isEmpty()&&wh.hitsplats.get(0).accurate){hs.add(wh);p+=wh.probability;}if(p==0)return this;List<HitDistribution> o=new ArrayList<>();o.add(new HitDistribution(hs).scaleProbability(1.0/p));o.addAll(dists.subList(1,dists.size()));return new AttackDistribution(o);}
        public AttackDistribution firstHitMinimum(int minimum){if(dists.isEmpty())return this;List<HitDistribution> o=new ArrayList<>();o.add(dists.get(0).transform(h->HitDistribution.single(Math.max(h.damage,minimum),h.accurate),false));o.addAll(dists.subList(1,dists.size()));return new AttackDistribution(o).flatten();}
    }

}

package com.personalbis;

import java.util.HashMap;
import java.util.Map;
import javax.inject.Inject;
import net.runelite.api.Client;
import net.runelite.api.Quest;
import net.runelite.api.QuestState;
import net.runelite.api.Skill;

/**
 * Eligibility checks used by the equipment intelligence layer.
 *
 * r0.3.0 includes a working requirement framework plus common high-value gear
 * rules. Unknown item-specific requirements are marked UNVERIFIED instead of
 * being silently treated as known-good. The complete generated OSRS requirement
 * table is the next data-layer milestone.
 */
public class ItemRequirementRegistry
{
    private final Client client;

    @Inject
    public ItemRequirementRegistry(Client client)
    {
        this.client = client;
    }

    public RequirementResult check(BankItem item, EquipmentSlot slot)
    {
        String name = item.getName().toLowerCase();
        Map<Skill, Integer> required = inferCommonLevelRequirements(name, slot);

        for (Map.Entry<Skill, Integer> requirement : required.entrySet())
        {
            int current = client.getRealSkillLevel(requirement.getKey());
            if (current < requirement.getValue())
            {
                return RequirementResult.blocked(
                    "Requires " + requirement.getValue() + " " + pretty(requirement.getKey()) +
                    " (you have " + current + ")");
            }
        }

        QuestCheck questCheck = inferQuestRequirement(name);
        if (questCheck != null)
        {
            try
            {
                Quest quest = Quest.valueOf(questCheck.questEnumName);
                if (quest.getState(client) != QuestState.FINISHED)
                {
                    return RequirementResult.blocked("Requires quest: " + quest.getName());
                }
            }
            catch (IllegalArgumentException ignored)
            {
                return RequirementResult.unverified("Quest requirement could not be verified");
            }
        }

        if (required.isEmpty() && questCheck == null)
        {
            return RequirementResult.unverified("Equipable; specific skill/quest requirements not yet verified");
        }

        return RequirementResult.usable("Meets known level/quest requirements");
    }

    private Map<Skill, Integer> inferCommonLevelRequirements(String name, EquipmentSlot slot)
    {
        Map<Skill, Integer> req = new HashMap<>();

        if (name.contains("rune "))
        {
            req.put(isArmourSlot(slot) ? Skill.DEFENCE : Skill.ATTACK, 40);
        }
        if (name.contains("dragon "))
        {
            req.put(isArmourSlot(slot) ? Skill.DEFENCE : Skill.ATTACK, 60);
        }

        if (containsAny(name, "dharok", "guthan", "karil", "ahrim", "torag", "verac")) req.put(Skill.DEFENCE, 70);
        if (name.contains("bandos chestplate") || name.contains("bandos tassets")) req.put(Skill.DEFENCE, 65);
        // Dragonhide / clue ranged armour. These checks are important because
        // offensive stats alone can otherwise make unavailable gear look best.
        if (containsAny(name, "black d'hide", "black dragonhide"))
        {
            req.put(Skill.RANGED, 70);
            if (slot == EquipmentSlot.BODY || slot == EquipmentSlot.SHIELD)
            {
                req.put(Skill.DEFENCE, 40);
            }
        }
        if (containsAny(name,
            "ancient d'hide", "armadyl d'hide", "bandos d'hide",
            "guthix d'hide", "saradomin d'hide", "zamorak d'hide",
            "ancient coif", "armadyl coif", "bandos coif",
            "guthix coif", "saradomin coif", "zamorak coif",
            "ancient bracers", "armadyl bracers", "bandos bracers",
            "guthix bracers", "saradomin bracers", "zamorak bracers",
            "ancient chaps", "armadyl chaps", "bandos chaps",
            "guthix chaps", "saradomin chaps", "zamorak chaps",
            "ancient boots", "armadyl boots", "bandos boots",
            "guthix boots", "saradomin boots", "zamorak boots"))
        {
            req.put(Skill.RANGED, 70);
            if (slot != EquipmentSlot.LEGS && slot != EquipmentSlot.HANDS)
            {
                req.put(Skill.DEFENCE, 40);
            }
        }
        if (name.contains("blue d'hide")) req.put(Skill.RANGED, 50);
        if (name.contains("red d'hide")) req.put(Skill.RANGED, 60);
        if (name.contains("green d'hide")) req.put(Skill.RANGED, 40);

        if (containsAny(name, "karil's", "karils")) { req.put(Skill.RANGED, 70); req.put(Skill.DEFENCE, 70); }
        if (containsAny(name, "armadyl helmet", "armadyl chestplate", "armadyl chainskirt")) { req.put(Skill.RANGED, 70); req.put(Skill.DEFENCE, 70); }
        if (name.contains("crystal helm") || name.contains("crystal body") || name.contains("crystal legs"))
        {
            req.put(Skill.RANGED, 70);
            req.put(Skill.DEFENCE, 70);
        }
        if (name.contains("slayer helmet") || name.contains("slayer helm") || name.contains("black mask"))
        {
            req.put(Skill.DEFENCE, 10);
        }
        if (name.contains("masori")) req.put(Skill.RANGED, 80);
        if (name.contains("ancestral")) { req.put(Skill.MAGIC, 75); req.put(Skill.DEFENCE, 65); }
        if (name.contains("torva")) { req.put(Skill.DEFENCE, 80); req.put(Skill.STRENGTH, 80); }
        if (name.contains("abyssal whip")) req.put(Skill.ATTACK, 70);
        if (name.contains("abyssal tentacle")) req.put(Skill.ATTACK, 75);
        if (name.contains("godsword")) req.put(Skill.ATTACK, 75);
        if (name.contains("scythe of vitur")) { req.put(Skill.ATTACK, 80); req.put(Skill.STRENGTH, 90); }
        if (name.contains("bow of faerdhinen")) req.put(Skill.RANGED, 80);
        if (name.contains("twisted bow")) req.put(Skill.RANGED, 85);
        if (name.contains("toxic blowpipe")) req.put(Skill.RANGED, 75);
        if (name.contains("dragon hunter crossbow")) req.put(Skill.RANGED, 70);
        if (name.contains("trident of the seas")) req.put(Skill.MAGIC, 75);
        if (name.contains("trident of the swamp")) req.put(Skill.MAGIC, 78);
        if (name.contains("sanguinesti staff")) req.put(Skill.MAGIC, 82);
        if (name.contains("tumeken's shadow")) req.put(Skill.MAGIC, 85);

        return req;
    }

    private QuestCheck inferQuestRequirement(String name)
    {
        if (name.contains("dragon scimitar")) return new QuestCheck("MONKEY_MADNESS_I");
        if (name.contains("barrows gloves")) return new QuestCheck("RECIPE_FOR_DISASTER");
        if (name.contains("ava's assembler")) return new QuestCheck("DRAGON_SLAYER_II");
        if (name.contains("mythical cape")) return new QuestCheck("DRAGON_SLAYER_II");
        if (name.contains("crystal helm") || name.contains("crystal body") || name.contains("crystal legs") || name.contains("bow of faerdhinen")) return new QuestCheck("SONG_OF_THE_ELVES");
        return null;
    }

    private boolean isArmourSlot(EquipmentSlot slot)
    {
        return slot == EquipmentSlot.HEAD || slot == EquipmentSlot.BODY || slot == EquipmentSlot.LEGS || slot == EquipmentSlot.SHIELD || slot == EquipmentSlot.HANDS || slot == EquipmentSlot.FEET;
    }

    private boolean containsAny(String text, String... terms)
    {
        for (String term : terms)
        {
            if (text.contains(term)) return true;
        }
        return false;
    }

    private String pretty(Skill skill)
    {
        String lower = skill.name().toLowerCase();
        return Character.toUpperCase(lower.charAt(0)) + lower.substring(1);
    }

