package com.personalbis;
import java.util.*;
public final class MagicSpellCompatibility {
 private MagicSpellCompatibility(){}
 public static boolean canAutocast(String rawWeapon,MagicSpell spell){
  if(rawWeapon==null||spell==null)return false;String w=rawWeapon.toLowerCase();String n=spell.name;
  if(PoweredStaff.forWeapon(w)!=null||PoweredStaff.requiresContext(w))return false;
  if("ancient".equals(spell.spellbook))return canAutocastAncient(w);
  if("arceuus".equals(spell.spellbook))return canAutocastArceuus(w);
  if("Iban Blast".equals(n))return one(w,"iban's staff","iban's staff (u)");
  if("Magic Dart".equals(n))return one(w,"slayer's staff","slayer's staff (e)","staff of the dead","toxic staff of the dead","staff of light","staff of balance");
  if("Saradomin Strike".equals(n))return one(w,"saradomin staff","staff of light");
  if("Claws of Guthix".equals(n))return one(w,"guthix staff","void knight mace","staff of balance");
  if("Flames of Zamorak".equals(n))return one(w,"zamorak staff","staff of the dead","toxic staff of the dead");
  if(!spell.element().isEmpty())return w.contains("staff")||w.contains("battlestaff")||w.contains("wand")
    ||w.contains("ancient sceptre")||w.contains("skull sceptre")||w.equals("blue moon spear");
  return false;
 }
 public static int attackTicks(String rawWeapon,MagicSpell spell){
  String w=rawWeapon==null?"":rawWeapon.toLowerCase();
  // Wiki Equipment.calculateAttackSpeed(): cast stances are normally 5t.
  // Harmonised is 4t only for STANDARD spellbook autocasts; Twinflame is 6t.
  if(w.equals("harmonised nightmare staff") && spell!=null && "standard".equals(spell.spellbook)) return 4;
  if(w.equals("twinflame staff")) return 6;
  return 5;
 }
 public static String note(String rawWeapon,MagicSpell spell){
  if(rawWeapon!=null&&rawWeapon.equalsIgnoreCase("Harmonised nightmare staff")&&"standard".equals(spell.spellbook))return "Harmonised: standard spell autocast 4t";
  if(rawWeapon!=null&&rawWeapon.equalsIgnoreCase("Twinflame staff"))return "Twinflame: spellcasting attack speed 6t";
  if("ancient".equals(spell.spellbook))return AncientSpellEffects.note(spell,rawWeapon);
  if("arceuus".equals(spell.spellbook))return spell.markOfDarkness?"Arceuus Demonbane + Mark of Darkness":"Arceuus Demonbane";
  if("Iban Blast".equals(spell.name))return "Requires Iban's staff";
  if("Magic Dart".equals(spell.name))return "Magic Dart: level-scaled max hit";
  if(spell.name.equals("Saradomin Strike")||spell.name.equals("Claws of Guthix")||spell.name.equals("Flames of Zamorak"))return "God spell: weapon-restricted; Charge not assumed";
  return "";
 }
 public static boolean canAutocastArceuus(String w){
  return w.equals("skull sceptre (i)")||w.equals("slayer's staff")||w.equals("slayer's staff (e)")
    ||w.equals("ahrim's staff")||w.equals("blue moon spear")||w.equals("staff of the dead")
    ||w.equals("toxic staff of the dead")||w.equals("purging staff")||w.equals("master wand")
    ||w.equals("kodai wand");
 }
 public static boolean canAutocastAncient(String w){
  return w.equals("ancient staff")||w.contains("ancient sceptre")||w.equals("master wand")||w.equals("kodai wand")
    ||w.equals("nightmare staff")||w.equals("eldritch nightmare staff")||w.equals("volatile nightmare staff")
    ||w.equals("harmonised nightmare staff")||w.equals("thammaron's sceptre (a)")||w.equals("accursed sceptre (a)")
    ||w.equals("blue moon spear");
 }
 private static boolean one(String w,String... names){for(String n:names)if(w.equals(n))return true;return false;}
}

package com.personalbis;
import java.util.*;
public final class MagicTomeEffects {
 private MagicTomeEffects(){}
 public static final class Effect {
  public final double accuracy, damage; public final String rune, note;
  Effect(double a,double d,String r,String n){accuracy=a;damage=d;rune=r;note=n;}
 }
 public static Effect evaluate(Collection<EquipmentCandidate> gear,MagicSpell spell){
  String tome=""; if(gear!=null)for(EquipmentCandidate e:gear)if(e!=null&&e.getItem()!=null){
   String n=e.getItem().getName().toLowerCase();
   if(n.equals("tome of fire")||n.equals("tome of water")||n.equals("tome of earth"))tome=n;
  }
  return evaluateName(tome,spell);
 }
 static Effect evaluateName(String tome,MagicSpell spell){
  String t=tome==null?"":tome.toLowerCase(); String el=spell==null?"":spell.element();
  if(t.equals("tome of fire")) return new Effect(1.0, "fire".equals(el)&&isStandardElemental(spell)?1.10:1.0,"fire rune",
    "Tome of fire: unlimited fire runes"+("fire".equals(el)&&isStandardElemental(spell)?", +10% fire damage":""));
  if(t.equals("tome of water")) return new Effect("water".equals(el)&&isStandardElemental(spell)?1.20:1.0,
    "water".equals(el)&&isStandardElemental(spell)?1.10:1.0,"water rune",
    "Tome of water: unlimited water runes"+("water".equals(el)&&isStandardElemental(spell)?", +10% water accuracy/damage":""));
  if(t.equals("tome of earth")) return new Effect(1.0, "earth".equals(el)&&isStandardElemental(spell)?1.10:1.0,"earth rune",
    "Tome of earth: unlimited earth runes"+("earth".equals(el)&&isStandardElemental(spell)?", +10% earth damage":""));
  return new Effect(1.0,1.0,"","");
 }
 private static boolean isStandardElemental(MagicSpell s){return s!=null&&"standard".equals(s.spellbook)&&!s.element().isEmpty();}
 public static boolean providesRune(Collection<EquipmentCandidate> gear,String rune){
  if(gear==null)return false;for(EquipmentCandidate e:gear)if(e!=null&&e.getItem()!=null){
   String n=e.getItem().getName().toLowerCase();
   if(n.equals("tome of fire")&&rune.equals("fire rune"))return true;
   if(n.equals("tome of water")&&rune.equals("water rune"))return true;
   if(n.equals("tome of earth")&&rune.equals("earth rune"))return true;
  }return false;
 }
}

package com.personalbis;
public final class MagicWeaponEffects {
 private MagicWeaponEffects(){}
 public static boolean isTwinflame(String raw){return norm(raw).equals("twinflame staff");}
 public static boolean isSmokeStaff(String raw){
  String n=norm(raw); return n.equals("smoke battlestaff")||n.equals("mystic smoke staff");
 }
 public static boolean isDragonHunterWand(String raw){return norm(raw).equals("dragon hunter wand");}
 public static boolean isStandardElemental(MagicSpell spell){return spell!=null&&!spell.element().isEmpty();}
 public static boolean isDraconic(MonsterDefinition m){
  return m!=null&&(m.hasAttribute("dragon")||m.hasAttribute("draconic"));
 }
 public static double accuracyMultiplier(String weapon,MagicSpell spell,MonsterDefinition m){
  if(isDragonHunterWand(weapon)&&isDraconic(m))return 1.75;
  if((isSmokeStaff(weapon)||isTwinflame(weapon))&&isStandardElemental(spell))return 1.10;
  return 1.0;
 }
 public static double damageMultiplier(String weapon,MagicSpell spell,MonsterDefinition m){
  if(isDragonHunterWand(weapon)&&isDraconic(m))return 1.40;
  if((isSmokeStaff(weapon)||isTwinflame(weapon))&&isStandardElemental(spell))return 1.10;
  return 1.0;
 }
 public static int attackTicks(String weapon){return isTwinflame(weapon)?6:5;}
 public static boolean twinflameEcho(String weapon,MagicSpell spell){
  if(!isTwinflame(weapon)||spell==null)return false;
  String t=spell.tier();return "bolt".equals(t)||"blast".equals(t)||"wave".equals(t);
 }
 public static double expectedHitMultiplier(String weapon,MagicSpell spell){
  return twinflameEcho(weapon,spell)?1.40:1.0;
 }
 public static String note(String weapon,MagicSpell spell,MonsterDefinition m){
  if(isDragonHunterWand(weapon)&&isDraconic(m))return "Dragonbane: +75% accuracy, +40% damage";
  if(isTwinflame(weapon)&&isStandardElemental(spell)){
   return twinflameEcho(weapon,spell)?"Twinflame: +10% accuracy/damage, 40% echo, 6t":"Twinflame: +10% accuracy/damage, 6t";
  }
  if(isSmokeStaff(weapon)&&isStandardElemental(spell))return "Smoke staff: +10% accuracy/damage";
  return "";
 }
 private static String norm(String x){return x==null?"":x.toLowerCase().trim();}
}

package com.personalbis;

import java.util.EnumSet;

/**
 * Maps Wiki DPS weapon categories to attack types the weapon can actually use.
 * Unknown categories are rejected rather than being granted fictional styles.
 */
public final class MeleeAttackStyleResolver
{
    private MeleeAttackStyleResolver() {}

    public static EnumSet<MeleeStance> legalStances(EquipmentCandidate weapon, AttackStyle style)
    {
        if (weapon == null) return EnumSet.allOf(MeleeStance.class);
        String c=weapon.getWeaponCategory()==null?"":weapon.getWeaponCategory().trim().toLowerCase();

        switch(c)
        {
            case "stab sword":
                // Dagger-style interface (including the original Keris):
                // Stab/Accurate, Lunge/Stab/Aggressive, Slash/Slash/Aggressive.
                if(style==AttackStyle.MELEE_STAB)return set(MeleeStance.ACCURATE,MeleeStance.AGGRESSIVE);
                if(style==AttackStyle.MELEE_SLASH)return set(MeleeStance.AGGRESSIVE);
                return none();

            case "partisan":
                // Keris partisan interface: Stab/Accurate, Lunge/Stab/Aggressive,
                // Pound/Crush/Aggressive. It has no Slash attack option.
                if(style==AttackStyle.MELEE_STAB)return set(MeleeStance.ACCURATE,MeleeStance.AGGRESSIVE);
                if(style==AttackStyle.MELEE_CRUSH)return set(MeleeStance.AGGRESSIVE);
                return none();

            case "slash sword":
            case "claw":
                if(style==AttackStyle.MELEE_SLASH)return set(MeleeStance.ACCURATE,MeleeStance.AGGRESSIVE);
                if(style==AttackStyle.MELEE_STAB)return set(MeleeStance.CONTROLLED);
                return none();

            case "2h sword":
            case "axe":
                if(style==AttackStyle.MELEE_SLASH)return set(MeleeStance.ACCURATE,MeleeStance.AGGRESSIVE);
                if(style==AttackStyle.MELEE_CRUSH)return set(MeleeStance.AGGRESSIVE);
                return none();

            case "blunt":
            case "bludgeon":
            case "staff":
            case "bulwark":
                if(style==AttackStyle.MELEE_CRUSH)return set(MeleeStance.ACCURATE,MeleeStance.AGGRESSIVE);
                return none();

            case "spiked":
            case "flail":
                if(style==AttackStyle.MELEE_CRUSH)return set(MeleeStance.ACCURATE,MeleeStance.AGGRESSIVE);
                if(style==AttackStyle.MELEE_STAB)return set(MeleeStance.CONTROLLED);
                return none();

            case "pickaxe":
                if(style==AttackStyle.MELEE_STAB)return set(MeleeStance.ACCURATE);
                if(style==AttackStyle.MELEE_CRUSH)return set(MeleeStance.AGGRESSIVE);
                return none();

            case "whip":
                if(style==AttackStyle.MELEE_SLASH)return set(MeleeStance.ACCURATE,MeleeStance.CONTROLLED);
                return none();

            case "spear":
                if(style==AttackStyle.MELEE_STAB||style==AttackStyle.MELEE_SLASH||style==AttackStyle.MELEE_CRUSH)
                    return set(MeleeStance.CONTROLLED);
                return none();

            case "polearm":
            case "scythe":
                // Halberd/polearm Slash is represented by the aggressive stance in
                // the Wiki attack interface; do not invent an Accurate option.
                if(style==AttackStyle.MELEE_SLASH)return set(MeleeStance.AGGRESSIVE);
                if(style==AttackStyle.MELEE_CRUSH)return set(MeleeStance.AGGRESSIVE);
                return none();

            case "polestaff":
            case "bladed staff":
                if(style==AttackStyle.MELEE_STAB)return set(MeleeStance.ACCURATE,MeleeStance.CONTROLLED);
                if(style==AttackStyle.MELEE_SLASH)return set(MeleeStance.AGGRESSIVE);
                return none();

            case "multi-melee":
                return style==AttackStyle.MELEE_STAB||style==AttackStyle.MELEE_SLASH||style==AttackStyle.MELEE_CRUSH
                    ? set(MeleeStance.ACCURATE,MeleeStance.AGGRESSIVE,MeleeStance.CONTROLLED) : none();

            // Ranged/magic/non-melee and unknown categories cannot be assumed to
            // possess a melee attack interface.
            default:
                return none();
        }
    }

    public static boolean supports(EquipmentCandidate weapon,AttackStyle style)
    {
        return !legalStances(weapon,style).isEmpty();
    }

    private static EnumSet<MeleeStance> set(MeleeStance first,MeleeStance... rest)
    {
        return EnumSet.of(first,rest);
    }

    private static EnumSet<MeleeStance> none()
    {
        return EnumSet.noneOf(MeleeStance.class);
    }
}

package com.personalbis;

import java.util.Map;
import javax.inject.Inject;
import net.runelite.api.Skill;

public class MeleeCombatCalculator
{
    private final AccountSnapshot account;

    @Inject
    public MeleeCombatCalculator(AccountSnapshot account)
    {
        this.account=account;
    }

    public CombatResult calculate(Map<EquipmentSlot,EquipmentCandidate> gear, AttackStyle style,
        MonsterDefinition monster, boolean onSlayerTask)
    {
        CombatResult best = null;
        EquipmentCandidate weapon = gear.get(EquipmentSlot.WEAPON);
        for (MeleeStance stance : MeleeAttackStyleResolver.legalStances(weapon, style))
        {
            for (MeleePrayer prayer : availablePrayers())
            {
            CombatResult result = calculateForStance(gear, style, monster, onSlayerTask, stance, prayer);
            if (best == null || FinalLoadoutSelection.betterTtk(
                result.getExpectedTtkSeconds(),result.getDps(),best.getExpectedTtkSeconds(),best.getDps()))
            {
                best = result;
            }
            }
        }
        return best;
    }

    public CombatResult calculateForStance(Map<EquipmentSlot,EquipmentCandidate> gear, AttackStyle style,
        MonsterDefinition monster, boolean onSlayerTask, MeleeStance stance, MeleePrayer prayer)
    {
        int attackBonus=0, strBonus=0, speed=4;
        boolean slayer=false;
        EquipmentCandidate weapon = gear.get(EquipmentSlot.WEAPON);

        for (EquipmentCandidate c : gear.values())
        {
            if (c==null) continue;
            attackBonus += c.getAttackBonus();
            strBonus += c.getStrengthBonus();
            if (c.getSlot()==EquipmentSlot.WEAPON && c.getAttackSpeed()>0) speed=c.getAttackSpeed();
            String n=c.getItem().getName().toLowerCase();
            if (c.getSlot()==EquipmentSlot.HEAD &&
                (n.contains("slayer helmet") || n.contains("slayer helm") || n.contains("black mask")))
            {
                slayer=true;
            }
        }

        attackBonus=WikiEquipmentEngine.transformMeleeAttack(gear,monster,attackBonus);
        WikiEquipmentEngine.Totals wikiEq=WikiEquipmentEngine.transform(gear,monster,null,strBonus,0,0,0.0,0); strBonus=wikiEq.str;

        int atk=Math.max(1,account.boosted(Skill.ATTACK));
        int str=Math.max(1,account.boosted(Skill.STRENGTH));

        // No prayer multiplier yet. Alpha4 makes the stance contribution explicit so close
        // weapon comparisons can be audited instead of hiding the +3/+1 style bonuses.
        boolean voidMelee=MeleeLoadoutEffects.hasVoidMelee(gear);
        int effAtk=CombatEffectiveLevels.melee(atk,prayer.getAttack(),stance.getAttackBoost(),voidMelee);
        int effStr=CombatEffectiveLevels.melee(str,prayer.getStrength(),stance.getStrengthBoost(),voidMelee);

        double salve=MeleeLoadoutEffects.salveMultiplier(gear,monster);
        final boolean avariceRevenant=WikiMeleeEffects.avariceRevenant(gear.values(),monster);

        final boolean slayerMeleeBonus = onSlayerTask && slayer && salve <= 1.0 && !avariceRevenant;
        int attackRoll=effAtk*(attackBonus+64);
        if (avariceRevenant)
        {
            attackRoll=WikiMeleeEffects.accuracyAfterAvarice(attackRoll,gear.values(),monster);
        }
        else if (salve > 1.0)
        {
            // Salve is a completed-roll modifier. Apply it after the ordinary
            // effective-level × equipment-bonus roll, preserving OSRS integer rounding.
            // Salve and Slayer helmet/black mask do not stack; Salve takes precedence.
            attackRoll=MeleeLoadoutEffects.salveAttackRoll(attackRoll,gear,monster);
        }
        if (slayerMeleeBonus)
        {
            // Black mask / Slayer helmet is a target-specific gear bonus:
            // apply x7/6 to the completed attack roll, not to effective Attack.
            attackRoll=SlayerMeleeEffects.attackRoll(attackRoll,true,true,false);
        }
        int preWeaponAttackRoll=attackRoll;
        attackRoll=(int)Math.floor(attackRoll
            *MeleeWeaponEffects.accuracyMultiplier(weapon,monster,style)
            *VampyreTargetRules.meleeAccuracyMultiplier(gear,weapon,monster)
            *MeleeLoadoutEffects.inquisitorMultiplier(gear,style)
            *MeleeLoadoutEffects.obsidianAccuracyMultiplier(gear,weapon));
        attackRoll=WikiMeleeEffects.postAccuracy(attackRoll,weapon,monster);
        int defLevel=monster==null ? 1 : Math.max(1,monster.getDefenceLevel());
        int defBonus=monster==null ? 0 : monster.defenceFor(style);
        int defenceRoll=(defLevel+9)*(defBonus+64);

        double accuracy=WikiAccuracyRoll.normal(attackRoll,defenceRoll);
        if(MeleeWeaponEffects.isFang(weapon)&&style==AttackStyle.MELEE_STAB)
            accuracy=WikiAccuracyRoll.fang(attackRoll,defenceRoll);

        int maxHit=WikiIntegerStages.maxHitFromEffective(effStr,strBonus+64);
        maxHit=WikiMeleeEffects.maxAfterCrystalBlessing(maxHit,gear.values());
        if (avariceRevenant)
        {
            maxHit=WikiMeleeEffects.maxAfterAvarice(maxHit,gear.values(),monster);
        }
        else if (salve > 1.0)
        {
            // Damage modifiers are applied before the final /640 truncation.
            // Keep the base max-hit numerator intact through Salve so fractional
            // pre-Salve damage is not discarded too early.
            maxHit=MeleeLoadoutEffects.salveMaxHitFromNumerator(effStr,strBonus,gear,monster);
        }
        if (slayerMeleeBonus)
        {
            // Target-specific damage bonuses are applied after the ordinary max-hit
            // calculation and floored at this stage.
            maxHit=SlayerMeleeEffects.maxHit(maxHit,true,true,false);
        }
        int preWeaponMaxHit=maxHit;
        speed=WikiAttackSpeedRules.attackTicks(speed,weapon,monster);
        double seconds=Math.max(1,speed)*0.6;
        int scytheHits=MeleeWeaponEffects.scytheHitCount(weapon,monster);

        // Weapon-specific damage multipliers modify the integer max hit first.
        // This rounding stage matters for Keris: e.g. 26 * 1.33 floors to 34,
        // then the ordinary hit distribution averages from that 34 max.
        int displayedMaxHit=maxHit;
        double averageHit;
        if(MeleeWeaponEffects.isScythe(weapon))
        {
            // Scythe rolls each size-dependent splat independently. Production DPS
            // uses the same Wiki-validated EV path as the DEV harness, while the
            // displayed max is the combined theoretical maximum (1/2/3 splats).
            displayedMaxHit=MeleeWeaponEffects.scytheCombinedMax(maxHit,scytheHits);
            averageHit=MeleeWeaponEffects.scytheAverageHit(maxHit,scytheHits);
        }
        else
        {
            double weaponDamage=MeleeWeaponEffects.damageMultiplier(weapon,monster,style);
            double obsidianDamage=MeleeLoadoutEffects.obsidianDamageMultiplier(gear,weapon);
            displayedMaxHit=(int)Math.floor(maxHit*weaponDamage*obsidianDamage*VampyreTargetRules.meleeDamageMultiplier(gear,weapon,monster));
            displayedMaxHit=WikiMeleeEffects.postDamage(displayedMaxHit,weapon,monster);
            // Colossal blade adds a flat +2 max hit per target tile, capped at size 5.
            // This is a max-hit addition, not a percentage multiplier.
            displayedMaxHit += MeleeWeaponEffects.colossalBladeBonusMax(weapon,monster);
            // Wiki parity: rat-bone weapons add +10 max against rat-attributed targets before later armour transforms.
            displayedMaxHit += MeleeWeaponEffects.ratbaneBonusMax(weapon,monster);
            if(obsidianDamage>1.0 && weaponDamage==1.0)
                averageHit=MeleeLoadoutEffects.obsidianModifiedRollAverage(maxHit,obsidianDamage);
            else
                averageHit=MeleeWeaponEffects.successfulHitAverage(displayedMaxHit);
            if(MeleeWeaponEffects.isFang(weapon))
            {
                // Fang's displayed normal max is 85% of its true max and its
                // successful damage roll is uniformly constrained to 15%-85%.
                displayedMaxHit=MeleeWeaponEffects.fangDisplayedMaxHit(maxHit);
                averageHit=MeleeWeaponEffects.fangAverageHit(maxHit);
            }
            if(MeleeWeaponEffects.isKeris(weapon) && monster!=null &&
                (monster.hasAttribute("kalphite")||monster.hasAttribute("scabarite")))
            {
                // Model the ordinary and 1/51 triple-hit distributions separately;
                // each successful zero roll is converted to 1 by the game.
                averageHit=MeleeWeaponEffects.kerisAverageHit(displayedMaxHit);
            }
        }
        double inquisitor=MeleeLoadoutEffects.inquisitorMultiplier(gear,style);
        // Inquisitor's Crush damage bonus is applied to the integer ordinary/weapon
        // max hit, floored, and that modified max defines the successful-hit damage
        // distribution. Wiki checkpoint: 42 * 1.025 -> 43, whose successful-hit
        // average is 43/2 + 1/44 = 21.522727..., yielding 3.29106 DPS at the
        // Vorkath no-shield checkpoint. Do not multiply the old average by 1.025.
        if (inquisitor > 1.0 && !MeleeWeaponEffects.isScythe(weapon))
        {
            displayedMaxHit=(int)Math.floor(displayedMaxHit*inquisitor);
            if(MeleeWeaponEffects.isKeris(weapon) && monster!=null &&
                (monster.hasAttribute("kalphite")||monster.hasAttribute("scabarite")))
            {
                averageHit=MeleeWeaponEffects.kerisAverageHit(displayedMaxHit);
            }
            else
            {
                averageHit=MeleeWeaponEffects.successfulHitAverage(displayedMaxHit);
            }
        }
        // alpha50.4.50.10: preserve the complete melee attacker distribution until
        // after Corp and NPC transforms. This is required for per-hitsplat armour,
        // caps and reductions on Scythe/Keris/Fang/two-hit weapons.
        HitDistribution.AttackDistribution attackDist;
        if (MeleeWeaponEffects.isScythe(weapon))
            attackDist=WikiPlayerVsNpcCalc.scytheAttacker(maxHit,scytheHits,accuracy);
        else if (MeleeWeaponEffects.isDualMacuahuitl(weapon))
            attackDist=WikiPlayerVsNpcCalc.dualMacuahuitlAttacker(displayedMaxHit,accuracy);
        else if (MeleeWeaponEffects.isIndependentTwoHit(weapon))
            attackDist=WikiPlayerVsNpcCalc.independentTwoHitAttacker(displayedMaxHit,accuracy);
        else if (MeleeWeaponEffects.isFang(weapon))
            attackDist=WikiPlayerVsNpcCalc.fangAttacker(preWeaponMaxHit,accuracy);
        else if (MeleeWeaponEffects.isKeris(weapon) && monster!=null &&
            (monster.hasAttribute("kalphite")||monster.hasAttribute("scabarite")))
            attackDist=WikiPlayerVsNpcCalc.kerisAttacker(displayedMaxHit,accuracy);
        else if (MeleeLoadoutEffects.obsidianDamageMultiplier(gear,weapon)>1.0
            && MeleeWeaponEffects.damageMultiplier(weapon,monster,style)==1.0 && inquisitor==1.0)
            attackDist=WikiPlayerVsNpcCalc.obsidianAttacker(preWeaponMaxHit,accuracy,MeleeLoadoutEffects.obsidianDamageMultiplier(gear,weapon));
        else if ((weapon!=null&&weapon.getItem()!=null&&weapon.getItem().getName().equalsIgnoreCase("Gadderhammer")
            && monster!=null&&monster.hasAttribute("shade")) || fullVerac(gear))
            attackDist=WikiPlayerVsNpcCalc.meleeSustainedAttacker(displayedMaxHit,accuracy,gear.values(),monster);
        else
            attackDist=WikiPlayerVsNpcCalc.standardAttacker(displayedMaxHit,accuracy);

        attackDist=WikiPlayerVsNpcCalc.applyCorp(attackDist,monster,weapon,style);
        attackDist=WikiPlayerVsNpcCalc.finalDistribution(attackDist,monster,style,weapon,null,false);
        double dps=WikiPlayerVsNpcCalc.expectedDamage(attackDist)/seconds;
        int targetHp=monster==null?1:Math.max(1,monster.getHitpoints());
        double ttk=ExpectedKillTime.seconds(attackDist,targetHp,speed);
        displayedMaxHit=attackDist.max();

        // Soulreaper is stateful: production ranking starts at zero stacks, then
        // scores the actual 0/1/2/3/4 -> 5-stack ramp over this target's HP.
        // Accuracy does not change with stacks; only Strength/max hit does.
        if(SoulreaperAxeEffects.isSoulreaper(weapon))
        {
            double[] stackEv=new double[6];
            int potentialMax=displayedMaxHit;
            for(int stacks=0;stacks<=5;stacks++)
            {
                int soulEff=SoulreaperAxeEffects.effectiveStrength(str,prayer.getStrength(),stance.getStrengthBoost(),voidMelee,stacks);
                int soulMax=WikiIntegerStages.maxHitFromEffective(soulEff,strBonus+64);
                if(salve>1.0) soulMax=MeleeLoadoutEffects.salveMaxHitFromNumerator(soulEff,strBonus,gear,monster);
                if(slayerMeleeBonus) soulMax=SlayerMeleeEffects.maxHit(soulMax,true,true,false);
                soulMax=(int)Math.floor(soulMax*MeleeWeaponEffects.damageMultiplier(weapon,monster,style));
                soulMax=(int)Math.floor(soulMax*inquisitor);
                HitDistribution soulDist=MeleeWeaponEffects.standardDistribution(soulMax,accuracy);
                if(CorporealBeastRules.reduced(monster,weapon,style)) soulDist=soulDist.transform(HitDistribution.divide(2,0));
                soulDist=WikiNpcTransforms.apply(soulDist,monster,style,weapon,null,false);
                stackEv[stacks]=soulDist.expectedHit();
                if(stacks==5) potentialMax=soulDist.max();
            }
            displayedMaxHit=potentialMax;
            dps=SoulreaperAxeEffects.rampDps(stackEv,targetHp,seconds);
            ttk=ExpectedKillTime.approximateSeconds(targetHp,dps);
        }


        // Kurasks/Turoths calculate an ordinary accuracy roll for unsupported weapons,
        // but the hit itself is ineffective. Preserve accuracy/roll diagnostics while
        // forcing damage to zero so the optimizer cannot recommend an unusable weapon.
        if (VampyreTargetRules.tier2HalfDamage(gear,weapon,monster)) { displayedMaxHit/=2; dps/=2.0; ttk=ExpectedKillTime.approximateSeconds(targetHp,dps); }
        if (VampyreTargetRules.tier2SilverCap10(gear,weapon,monster)) { displayedMaxHit=Math.min(displayedMaxHit,10); dps=accuracy*MeleeWeaponEffects.successfulHitAverage(displayedMaxHit)/seconds; ttk=ExpectedKillTime.approximateSeconds(targetHp,dps); }
        if (!WikiTargetEligibility.meleeCanDamage(monster,weapon) || !LeafyTargetRules.meleeCanDamage(monster,weapon) || !MeleeWeaponEffects.ratBoneCanDamage(weapon,monster) || !VampyreTargetRules.canDamageMelee(gear,weapon,monster))
        {
            displayedMaxHit=0;
            dps=0.0;
            ttk=Double.POSITIVE_INFINITY;
        }

        return new CombatResult(dps,ttk,accuracy,displayedMaxHit,attackRoll,defenceRoll,
            attackBonus,strBonus,speed,effAtk,effStr,stance,prayer,preWeaponAttackRoll,preWeaponMaxHit);
    }


    private boolean fullVerac(Map<EquipmentSlot,EquipmentCandidate> gear)
    {
        return named(gear.get(EquipmentSlot.WEAPON),"Verac's flail")&&named(gear.get(EquipmentSlot.HEAD),"Verac's helm")
            &&named(gear.get(EquipmentSlot.BODY),"Verac's brassard")&&named(gear.get(EquipmentSlot.LEGS),"Verac's plateskirt");
    }

    private boolean named(EquipmentCandidate c,String name)
    { return c!=null&&c.getItem()!=null&&c.getItem().getName().equalsIgnoreCase(name); }

    private MeleePrayer[] availablePrayers()
    {
        int p = account.real(Skill.PRAYER);
        // The optimiser's objective is maximum DPS. Every supported offensive
        // Melee prayer increases both Attack and Strength, so NONE is strictly
        // dominated whenever a prayer is available. Evaluating it for every
        // temporary beam state doubled the hottest part of the search without
        // ever being able to produce the winning loadout.
        if (p >= 70 && account.isPietyUnlocked()) return new MeleePrayer[]{MeleePrayer.PIETY};
        if (p >= 60 && account.isChivalryUnlocked()) return new MeleePrayer[]{MeleePrayer.CHIVALRY};
        if (p >= 44) return new MeleePrayer[]{MeleePrayer.HIGH};
        if (p >= 31) return new MeleePrayer[]{MeleePrayer.MID};
        if (p >= 13) return new MeleePrayer[]{MeleePrayer.LOW};
        return new MeleePrayer[]{MeleePrayer.NONE};
    }
}

package com.personalbis;

import java.util.Map;

/** Passive effects which depend on multiple equipped items rather than the weapon alone. */
public final class MeleeLoadoutEffects
{
    private MeleeLoadoutEffects() {}

    public static double salveMultiplier(Map<EquipmentSlot,EquipmentCandidate> gear, MonsterDefinition monster)
    {
        if (monster == null || !monster.hasAttribute("undead")) return 1.0;
        EquipmentCandidate neck=gear.get(EquipmentSlot.NECK);
        if (neck==null) return 1.0;
        String n=name(neck);
        if (!n.contains("salve amulet")) return 1.0;
        return (n.contains("(e)") || n.contains("(ei)")) ? 1.20 : (7.0/6.0);
    }

    public static boolean hasSalveEffect(Map<EquipmentSlot,EquipmentCandidate> gear, MonsterDefinition monster)
    {
        return salveMultiplier(gear,monster) > 1.0;
    }

    public static int salveAttackRoll(int baseAttackRoll, Map<EquipmentSlot,EquipmentCandidate> gear, MonsterDefinition monster)
    {
        return (int)Math.floor(baseAttackRoll * salveMultiplier(gear,monster));
    }

    public static int salveMaxHitFromNumerator(int effectiveStrength, int strengthBonus,
        Map<EquipmentSlot,EquipmentCandidate> gear, MonsterDefinition monster)
    {
        // OSRS/Wiki keeps the max-hit numerator exact through multiplicative
        // damage modifiers, then performs the /640 max-hit truncation.
        // This avoids losing a max hit by truncating before Salve.
        double salve = salveMultiplier(gear,monster);
        return (int)Math.floor((effectiveStrength * (strengthBonus + 64) + 320.0) * salve / 640.0);
    }

    public static boolean hasVoidMelee(Map<EquipmentSlot,EquipmentCandidate> gear)
    {
        return named(gear.get(EquipmentSlot.HEAD),"void melee helm")
            && (named(gear.get(EquipmentSlot.BODY),"void knight top") || named(gear.get(EquipmentSlot.BODY),"elite void top"))
            && (named(gear.get(EquipmentSlot.LEGS),"void knight robe") || named(gear.get(EquipmentSlot.LEGS),"elite void robe"))
            && named(gear.get(EquipmentSlot.HANDS),"void knight gloves");
    }

    public static double voidAccuracyMultiplier(Map<EquipmentSlot,EquipmentCandidate> gear)
    {
        return hasVoidMelee(gear) ? 1.10 : 1.0;
    }

    public static double voidDamageMultiplier(Map<EquipmentSlot,EquipmentCandidate> gear)
    {
        return hasVoidMelee(gear) ? 1.10 : 1.0;
    }

    /**
     * Current (22 July 2026+) Inquisitor crush bonus. The old full-set and
     * mace-amplified effects were removed: helm is +0.5%, hauberk +1.0%,
     * plateskirt +1.0%, independently, for +2.5% with all three. The mace
     * now carries its former synergy as raw +7 crush/+7 strength stats.
     */
    public static double inquisitorBonus(Map<EquipmentSlot,EquipmentCandidate> gear, AttackStyle style)
    {
        if (style != AttackStyle.MELEE_CRUSH || gear == null) return 0.0;
        double bonus=0.0;
        if (named(gear.get(EquipmentSlot.HEAD),"inquisitor's great helm")) bonus += 0.005;
        if (named(gear.get(EquipmentSlot.BODY),"inquisitor's hauberk")) bonus += 0.010;
        if (named(gear.get(EquipmentSlot.LEGS),"inquisitor's plateskirt")) bonus += 0.010;
        return bonus;
    }

    public static double inquisitorMultiplier(Map<EquipmentSlot,EquipmentCandidate> gear, AttackStyle style)
    {
        return 1.0 + inquisitorBonus(gear,style);
    }


    /** Full obsidian armour (helm/body/legs) gives obsidian melee weapons +10% accuracy and damage. */
    public static boolean hasObsidianArmourSet(Map<EquipmentSlot,EquipmentCandidate> gear)
    {
        return gear!=null && named(gear.get(EquipmentSlot.HEAD),"obsidian helmet")
            && named(gear.get(EquipmentSlot.BODY),"obsidian platebody")
            && named(gear.get(EquipmentSlot.LEGS),"obsidian platelegs");
    }

    public static double obsidianAccuracyMultiplier(Map<EquipmentSlot,EquipmentCandidate> gear, EquipmentCandidate weapon)
    {
        return hasObsidianArmourSet(gear) && MeleeWeaponEffects.isObsidianMeleeWeapon(weapon) ? 1.10 : 1.0;
    }

    /** Berserker necklace gives obsidian melee weapons +20% damage; stacks with full obsidian armour. */
    public static double obsidianDamageMultiplier(Map<EquipmentSlot,EquipmentCandidate> gear, EquipmentCandidate weapon)
    {
        if (!MeleeWeaponEffects.isObsidianMeleeWeapon(weapon)) return 1.0;
        double mult=hasObsidianArmourSet(gear) ? 1.10 : 1.0;
        if (gear!=null && (named(gear.get(EquipmentSlot.NECK),"berserker necklace")
            || named(gear.get(EquipmentSlot.NECK),"berserker necklace (or)"))) mult*=1.20;
        return mult;
    }

    /**
     * Obsidian/Berserker-necklace damage is applied to each raw 0..baseMax
     * damage roll, with integer truncation on the modified roll. The Wiki
     * Vorkath checkpoint (base max 32, x1.32) averages 20.63636 rather than
     * treating the result as a fresh uniform 0..42 distribution.
     */
    public static double obsidianModifiedRollAverage(int baseMax, double multiplier)
    {
        if (baseMax<=0) return 0.0;
        if (multiplier<=1.0) return MeleeWeaponEffects.successfulHitAverage(baseMax);
        long total=0;
        for(int roll=0;roll<=baseMax;roll++) total += (int)Math.floor(roll*multiplier);
        return total/(double)(baseMax+1);
    }

    public static boolean isSynergyItem(EquipmentCandidate c)
    {
        if(c==null)return false;
        String n=name(c);
        return n.contains("salve amulet")
            || n.contains("slayer helmet") || n.contains("slayer helm") || n.contains("black mask")
            || n.contains("void melee helm") || n.contains("void knight top") || n.contains("elite void top")
            || n.contains("void knight robe") || n.contains("elite void robe") || n.contains("void knight gloves")
            || n.contains("inquisitor's great helm") || n.contains("inquisitor's hauberk")
            || n.contains("inquisitor's plateskirt") || n.contains("inquisitor's mace")
            || n.contains("obsidian helmet") || n.contains("obsidian platebody") || n.contains("obsidian platelegs")
            || n.contains("berserker necklace") || n.contains("verac's helm")
            || n.contains("verac's brassard") || n.contains("verac's plateskirt");
    }

    private static boolean named(EquipmentCandidate c,String text){return c!=null&&name(c).contains(text);}
    private static String name(EquipmentCandidate c){return c.getItem().getName().toLowerCase();}
}

package com.personalbis;

import java.util.*;
import java.util.stream.IntStream;
import javax.inject.Inject;

public class MeleeLoadoutOptimizer
{
    private static final int SLOT_CHOICES=4, BEAM_WIDTH=32;
    private final EquipmentIntelligence intelligence;
    private final MeleeCombatCalculator calculator;
    private static final class SearchContext
    {
        final EnumMap<EquipmentSlot,List<EquipmentCandidate>> choices=new EnumMap<>(EquipmentSlot.class);
        final Map<String,CombatResult> exact=new HashMap<>();
    }
    private static final class WeaponSearchResult
    {
        final EquipmentCandidate weapon; final OptimizedLoadout loadout;
        WeaponSearchResult(EquipmentCandidate w,OptimizedLoadout l){weapon=w;loadout=l;}
    }

    @Inject
    public MeleeLoadoutOptimizer(EquipmentIntelligence intelligence,MeleeCombatCalculator calculator)
    {
        this.intelligence=intelligence;
        this.calculator=calculator;
    }

    // alpha50.4.34 DEV synthetic melee harness: evaluate one explicitly fixed
    // equipment map without adding synthetic weapons to the production bank/optimizer.
    public CombatResult evaluateFixed(Map<EquipmentSlot,EquipmentCandidate> gear, AttackStyle style,
        MonsterDefinition monster, boolean onSlayerTask)
    {
        return calculator.calculate(gear, style, monster, onSlayerTask);
    }

    public OptimizedLoadout optimize(List<BankItem> bank,AttackStyle style,MonsterDefinition monster,boolean onSlayerTask)
    {
        MeleeOptimizationReport report=optimizeWithReport(bank,style,monster,onSlayerTask);
        return report==null ? null : report.getBest();
    }

    public MeleeOptimizationReport optimizeWithReport(List<BankItem> bank,AttackStyle style,
        MonsterDefinition monster,boolean onSlayerTask)
    {
        if(style!=AttackStyle.MELEE_STAB&&style!=AttackStyle.MELEE_SLASH&&style!=AttackStyle.MELEE_CRUSH)
            return null;

        Map<EquipmentSlot,List<EquipmentCandidate>> ranked=intelligence.rank(bank,style,onSlayerTask);
        return optimizeWithReportRanked(ranked,style,monster,onSlayerTask);
    }

    public MeleeOptimizationReport optimizeWithReportRanked(Map<EquipmentSlot,List<EquipmentCandidate>> ranked,
        AttackStyle style,MonsterDefinition monster,boolean onSlayerTask)
    {
        if(style!=AttackStyle.MELEE_STAB&&style!=AttackStyle.MELEE_SLASH&&style!=AttackStyle.MELEE_CRUSH)return null;
        ranked=SlayerTargetRequirements.constrainRanked(monster,ranked);
        EquipmentSlot requiredSlot=SlayerTargetRequirements.requiredEquipmentSlot(monster);
        EquipmentCandidate requiredEquipment=requiredSlot==null?null:
            SlayerTargetRequirements.firstRequiredEquipment(monster,ranked.get(requiredSlot));
        List<EquipmentCandidate> weapons=shortlist(ranked.get(EquipmentSlot.WEAPON),monster);
        List<WeaponComparison> comparisons=new ArrayList<>();
        List<String> audit=new ArrayList<>();
        appendSlotAudit(audit,"BODY",ranked.get(EquipmentSlot.BODY));
        appendSlotAudit(audit,"LEGS",ranked.get(EquipmentSlot.LEGS));
        OptimizedLoadout best=null;
        List<EquipmentCandidate> searchable=new ArrayList<>();
        for(EquipmentCandidate weapon:weapons)
        {
            if(requiredSlot==EquipmentSlot.SHIELD&&weapon.isTwoHanded())continue;
            boolean supported=MeleeAttackStyleResolver.supports(weapon, style);
            String wn=weapon.getItem().getName();
            boolean focus=wn.toLowerCase().contains("keris");
            if (!supported)
            {
                if(focus) audit.add("KERIS id="+weapon.getItem().getItemId()+" "+wn+" cat="+weapon.getWeaponCategory()+" -> REJECT style");
                continue;
            }
            searchable.add(weapon);
        }
        final Map<EquipmentSlot,List<EquipmentCandidate>> searchRanked=ranked;
        List<WeaponSearchResult> results=IntStream.range(0,searchable.size()).parallel().mapToObj(i->{
            EquipmentCandidate weapon=searchable.get(i);
            return new WeaponSearchResult(weapon,optimizeForWeapon(weapon,searchRanked,style,monster,
                onSlayerTask,requiredEquipment,new SearchContext()));
        }).collect(java.util.stream.Collectors.toList());
        for(WeaponSearchResult result:results)
        {
            EquipmentCandidate weapon=result.weapon;
            OptimizedLoadout weaponBest=result.loadout;
            if(weaponBest!=null)
            {
                comparisons.add(new WeaponComparison(weapon.getItem().getName(),weaponBest));
                if(weapon.getItem().getName().toLowerCase().contains("keris"))
                    audit.add(weaponAudit("KERIS",weapon,weaponBest,monster,onSlayerTask));
                if(best==null||FinalLoadoutSelection.betterTtk(weaponBest.getResult().getExpectedTtkSeconds(),weaponBest.getResult().getDps(),best.getResult().getExpectedTtkSeconds(),best.getResult().getDps())) best=weaponBest;
            }
        }

        comparisons.sort((a,b)->FinalLoadoutSelection.compareTtk(a.getResult().getExpectedTtkSeconds(),a.getResult().getDps(),b.getResult().getExpectedTtkSeconds(),b.getResult().getDps()));
        for(int i=0;i<Math.min(6,comparisons.size());i++)
            audit.add(weaponAudit("TOP"+(i+1), findWeapon(weapons,comparisons.get(i).getWeaponName()), comparisons.get(i).getLoadout(),monster,onSlayerTask));
        return new MeleeOptimizationReport(best,comparisons,audit);
    }

    private OptimizedLoadout optimizeForWeapon(EquipmentCandidate weapon,
        Map<EquipmentSlot,List<EquipmentCandidate>> ranked,AttackStyle style,
        MonsterDefinition monster,boolean onSlayerTask,EquipmentCandidate requiredEquipment,SearchContext context)
    {
        Map<EquipmentSlot,EquipmentCandidate> seed=new EnumMap<>(EquipmentSlot.class);
        seed.put(EquipmentSlot.WEAPON,weapon);
        if(requiredEquipment!=null)seed.put(requiredEquipment.getSlot(),requiredEquipment);
        List<Map<EquipmentSlot,EquipmentCandidate>> beam=new ArrayList<>();
        beam.add(seed);
        Map<EquipmentSlot,EquipmentCandidate> verac=veracsBundle(ranked,weapon);
        if(verac!=null){if(requiredEquipment!=null)verac.put(requiredEquipment.getSlot(),requiredEquipment);beam.add(verac);}
        Map<EquipmentSlot,EquipmentCandidate> crystal=crystalBlessingBundle(ranked,weapon);
        if(crystal!=null){if(requiredEquipment!=null)crystal.put(requiredEquipment.getSlot(),requiredEquipment);beam.add(crystal);}

        for(EquipmentSlot slot:EquipmentSlot.values())
        {
            if(slot==EquipmentSlot.WEAPON) continue;
            if(SlayerTargetRequirements.requiredEquipmentSlot(monster)==slot)continue;
            if(weapon.isTwoHanded()&&slot==EquipmentSlot.SHIELD) continue;
            List<EquipmentCandidate> choices=context.choices.computeIfAbsent(slot,
                s->dominancePrune(usable(ranked.get(s),SLOT_CHOICES)));
            if(choices.isEmpty()) continue;

            List<Map<EquipmentSlot,EquipmentCandidate>> next=new ArrayList<>();
            for(Map<EquipmentSlot,EquipmentCandidate>b:beam)
            {
                // Empty optional slots are legal. This prevents a negative-bonus item
                // from being forced into an otherwise stronger complete loadout.
                next.add(new EnumMap<>(b));
                for(EquipmentCandidate c:choices)
                {
                    Map<EquipmentSlot,EquipmentCandidate> n=new EnumMap<>(b);
                    n.put(slot,c);
                    next.add(n);
                }
            }
            final Map<Map<EquipmentSlot,EquipmentCandidate>,Double> dpsCache=new IdentityHashMap<>();
            for(Map<EquipmentSlot,EquipmentCandidate> g:next)
                dpsCache.put(g,calculateCached(g,style,monster,onSlayerTask,context).getDps());
            next.sort((a,b)->{
                int d=Double.compare(dpsCache.get(b),dpsCache.get(a));
                return d!=0?d:Integer.compare(prayerBonus(b),prayerBonus(a));
            });
            beam=new ArrayList<>(next.subList(0,Math.min(BEAM_WIDTH,next.size())));
        }

        OptimizedLoadout best=null;
        for(Map<EquipmentSlot,EquipmentCandidate> g:beam)
        {
            CombatResult r=calculateCached(g,style,monster,onSlayerTask,context);
            if(best==null||FinalLoadoutSelection.betterTtk(r.getExpectedTtkSeconds(),r.getDps(),best.getResult().getExpectedTtkSeconds(),best.getResult().getDps())
                ||(Double.compare(r.getExpectedTtkSeconds(),best.getResult().getExpectedTtkSeconds())==0
                   && prayerBonus(g)>prayerBonus(best.getItems())))
                best=new OptimizedLoadout(style,g,r);
        }
        return completeNeutralSlots(best,ranked,style,monster,onSlayerTask,weapon,context);
    }

    /**
     * Beam search may intentionally keep an optional slot empty while comparing
     * offensive candidates. Once the DPS winner is known, fill any remaining
     * slot with the best owned item that does not reduce that winner's DPS.
     * This is deliberately post-search so it cannot distort weapon/style ranking.
     */
    private OptimizedLoadout completeNeutralSlots(OptimizedLoadout best,
        Map<EquipmentSlot,List<EquipmentCandidate>> ranked,AttackStyle style,
        MonsterDefinition monster,boolean onSlayerTask,EquipmentCandidate weapon,SearchContext context)
    {
        if(best==null)return null;
        Map<EquipmentSlot,EquipmentCandidate> gear=new EnumMap<>(best.getItems());
        CombatResult current=best.getResult();

        for(EquipmentSlot slot:EquipmentSlot.values())
        {
            if(slot==EquipmentSlot.WEAPON||gear.containsKey(slot))continue;
            if(weapon.isTwoHanded()&&slot==EquipmentSlot.SHIELD)continue;

            EquipmentCandidate chosen=null;
            CombatResult chosenResult=current;
            List<EquipmentCandidate> all=ranked.get(slot);
            if(all==null)continue;

            int examined=0;
            for(EquipmentCandidate c:all)
            {
                if (examined++ >= 8) break;
                if(c.getRequirementResult().isBlocked())continue;
                Map<EquipmentSlot,EquipmentCandidate> trial=new EnumMap<>(gear);
                trial.put(slot,c);
                CombatResult r=calculateCached(trial,style,monster,onSlayerTask,context);

                // Never sacrifice the offensive result merely to make the grid full.
                if(FinalLoadoutSelection.betterTtk(current.getExpectedTtkSeconds(),current.getDps(),r.getExpectedTtkSeconds(),r.getDps()))continue;
                if(chosen==null
                    || FinalLoadoutSelection.betterTtk(r.getExpectedTtkSeconds(),r.getDps(),chosenResult.getExpectedTtkSeconds(),chosenResult.getDps())
                    || (Double.compare(r.getExpectedTtkSeconds(),chosenResult.getExpectedTtkSeconds())==0
                        && c.getPrayer()>chosen.getPrayer()))
                {
                    chosen=c;
                    chosenResult=r;
                }
            }

            if(chosen!=null)
            {
                gear.put(slot,chosen);
                current=chosenResult;
            }
        }
        return new OptimizedLoadout(style,gear,current);
    }

    private CombatResult calculateCached(Map<EquipmentSlot,EquipmentCandidate> gear,AttackStyle style,
        MonsterDefinition monster,boolean onSlayerTask,SearchContext context)
    {
        StringBuilder key=new StringBuilder();
        for(EquipmentSlot slot:EquipmentSlot.values())
        {
            EquipmentCandidate c=gear.get(slot);
            key.append(c==null?0:c.getItem().getItemId()).append(',');
        }
        String k=key.toString();
        CombatResult hit=context.exact.get(k);
        if(hit!=null)return hit;
        CombatResult calculated=calculator.calculate(gear,style,monster,onSlayerTask);
        context.exact.put(k,calculated);
        return calculated;
    }

    private List<EquipmentCandidate> dominancePrune(List<EquipmentCandidate> raw)
    {
        if(raw.size()<2)return raw;
        List<EquipmentCandidate> out=new ArrayList<>();
        for(int i=0;i<raw.size();i++)
        {
            EquipmentCandidate c=raw.get(i); boolean dominated=false;
            if(MeleeLoadoutEffects.isSynergyItem(c)){out.add(c);continue;}
            for(int j=0;j<raw.size();j++)
            {
                if(i==j)continue;
                EquipmentCandidate d=raw.get(j);
                if(MeleeLoadoutEffects.isSynergyItem(d))continue;
                boolean noWorse=d.getAttackBonus()>=c.getAttackBonus()
                    &&d.getStrengthBonus()>=c.getStrengthBonus()&&d.getPrayer()>=c.getPrayer();
                boolean strict=d.getAttackBonus()>c.getAttackBonus()
                    ||d.getStrengthBonus()>c.getStrengthBonus()||d.getPrayer()>c.getPrayer();
                boolean exact=d.getAttackBonus()==c.getAttackBonus()
                    &&d.getStrengthBonus()==c.getStrengthBonus()&&d.getPrayer()==c.getPrayer();
                if((noWorse&&strict)||(exact&&j<i)){dominated=true;break;}
            }
            if(!dominated)out.add(c);
        }
        return out;
    }

    private void appendSlotAudit(List<String> audit,String label,List<EquipmentCandidate> all)
    {
        if(all==null)return;
        int rank=0;
        for(EquipmentCandidate c:all)
        {
            if(c==null||c.getRequirementResult().isBlocked())continue;
            rank++;
            String n=c.getItem().getName().toLowerCase();
            if(rank<=6||n.contains("bandos")||n.contains("mixed hide"))
                audit.add(label+" #"+rank+" "+c.getItem().getName()+" id="+c.getItem().getItemId()+" atk="+c.getAttackBonus()+" str="+c.getStrengthBonus()+" score="+c.getScore()+(rank<=SLOT_CHOICES?" IN":" OUT"));
        }
    }

    private EquipmentCandidate findWeapon(List<EquipmentCandidate> weapons,String name)
    {
        for(EquipmentCandidate w:weapons)if(w.getItem().getName().equals(name))return w;
        return null;
    }

    private String weaponAudit(String prefix,EquipmentCandidate w,OptimizedLoadout l,MonsterDefinition monster,boolean onSlayerTask)
    {
        if(w==null||l==null)return prefix+" unavailable";
        CombatResult r=l.getResult();
        EquipmentCandidate b=l.getItems().get(EquipmentSlot.BODY), g=l.getItems().get(EquipmentSlot.LEGS);
        String base=String.format(java.util.Locale.ROOT,"%s id=%d %s | cat=%s | keris=%s | dps=%.5f acc=%.2f%% max=%d speed=%d | body=%s | legs=%s",
            prefix,w.getItem().getItemId(),w.getItem().getName(),w.getWeaponCategory(),MeleeWeaponEffects.isKeris(w),r.getDps(),r.getAccuracy()*100.0,r.getMaxHit(),r.getAttackSpeed(),
            b==null?"—":b.getItem().getName(),g==null?"—":g.getItem().getName());
        if(MeleeWeaponEffects.isKeris(w) && r.getMaxHit()>0)
        {
            int proc=MeleeWeaponEffects.kerisProcMax(r.getMaxHit());
            double avg=MeleeWeaponEffects.kerisAverageHit(r.getMaxHit());
            double ev=r.getAccuracy()*avg;
            double accMult=MeleeWeaponEffects.accuracyMultiplier(w,monster,l.getStyle());
            String detail=base+String.format(java.util.Locale.ROOT,
                " | Keris detail: effAtk=%d effStr=%d stabAtk=%d str=%d preAtkRoll=%d accMult=%.3f finalAtkRoll=%d defRoll=%d | base=%d -> kalphite=%d -> proc=%d | successAvg=%.5f | EV/attack=%.5f",
                r.getEffectiveAttack(),r.getEffectiveStrength(),r.getAttackBonus(),r.getStrengthBonus(),
                r.getPreWeaponAttackRoll(),accMult,r.getAttackRoll(),r.getDefenceRoll(),
                r.getPreWeaponMaxHit(),r.getMaxHit(),proc,avg,ev);
            // Alpha50.4.33: expose each legal stance independently. Alternative weapons are
            // intentionally allowed to choose their own best stance; the selected Fang's
            // stance must not be assumed to apply to a Keris candidate.
            StringBuilder stanceAudit=new StringBuilder(detail);
            for(MeleeStance stance:MeleeAttackStyleResolver.legalStances(w,l.getStyle()))
            {
                CombatResult sr=calculator.calculateForStance(l.getItems(),l.getStyle(),monster,onSlayerTask,
                    stance,r.getPrayer());
                int sp=MeleeWeaponEffects.isKeris(w)&&monster!=null&&
                    (monster.hasAttribute("kalphite")||monster.hasAttribute("scabarite"))
                    ? MeleeWeaponEffects.kerisProcMax(sr.getMaxHit()) : sr.getMaxHit();
                double savg=MeleeWeaponEffects.isKeris(w)&&monster!=null&&
                    (monster.hasAttribute("kalphite")||monster.hasAttribute("scabarite"))
                    ? MeleeWeaponEffects.kerisAverageHit(sr.getMaxHit())
                    : MeleeWeaponEffects.successfulHitAverage(sr.getMaxHit());
                stanceAudit.append(String.format(java.util.Locale.ROOT,
                    " | %s: effAtk=%d effStr=%d roll=%d acc=%.2f%% base=%d max=%d proc=%d EV=%.5f dps=%.5f",
                    stance,sr.getEffectiveAttack(),sr.getEffectiveStrength(),sr.getAttackRoll(),
                    sr.getAccuracy()*100.0,sr.getPreWeaponMaxHit(),sr.getMaxHit(),sp,
                    sr.getAccuracy()*savg,sr.getDps()));
            }
            return stanceAudit.toString();
        }
        return base;
    }

    private List<EquipmentCandidate> shortlist(List<EquipmentCandidate> all,MonsterDefinition m)
    {
        // Alpha 50.4 completeness pass: a raw-stat weapon rank must never decide
        // whether an owned/equippable weapon gets an exact target DPS evaluation.
        // Attack-interface eligibility is still enforced in optimizeWithReportRanked.
        List<EquipmentCandidate> x=new ArrayList<>();
        if(all!=null)for(EquipmentCandidate c:all)
            if(c!=null&&!c.getRequirementResult().isBlocked())x.add(c);
        return x;
    }

    private Map<EquipmentSlot,EquipmentCandidate> veracsBundle(Map<EquipmentSlot,List<EquipmentCandidate>> ranked,
        EquipmentCandidate weapon)
    {
        if(weapon==null||weapon.getItem()==null||!weapon.getItem().getName().equalsIgnoreCase("Verac's flail"))return null;
        EquipmentCandidate head=findNamed(ranked.get(EquipmentSlot.HEAD),"Verac's helm");
        EquipmentCandidate body=findNamed(ranked.get(EquipmentSlot.BODY),"Verac's brassard");
        EquipmentCandidate legs=findNamed(ranked.get(EquipmentSlot.LEGS),"Verac's plateskirt");
        if(head==null||body==null||legs==null)return null;
        Map<EquipmentSlot,EquipmentCandidate> g=new EnumMap<>(EquipmentSlot.class);g.put(EquipmentSlot.WEAPON,weapon);
        g.put(EquipmentSlot.HEAD,head);g.put(EquipmentSlot.BODY,body);g.put(EquipmentSlot.LEGS,legs);return g;
    }

    private EquipmentCandidate findNamed(List<EquipmentCandidate> items,String name)
    {
        if(items!=null)for(EquipmentCandidate c:items)if(c!=null&&!c.getRequirementResult().isBlocked()
            &&c.getItem()!=null&&c.getItem().getName().equalsIgnoreCase(name))return c;
        return null;
    }

    private Map<EquipmentSlot,EquipmentCandidate> crystalBlessingBundle(
        Map<EquipmentSlot,List<EquipmentCandidate>> ranked, EquipmentCandidate weapon)
    {
        if (weapon == null) return null;
        EquipmentCandidate blessing=findNamed(ranked.get(EquipmentSlot.NECK),"Crystal blessing");
        EquipmentCandidate helm=findNamed(ranked.get(EquipmentSlot.HEAD),"Crystal helm");
        EquipmentCandidate body=findNamed(ranked.get(EquipmentSlot.BODY),"Crystal body");
        EquipmentCandidate legs=findNamed(ranked.get(EquipmentSlot.LEGS),"Crystal legs");
        if (blessing==null||helm==null||body==null||legs==null) return null;
        Map<EquipmentSlot,EquipmentCandidate> g=new EnumMap<>(EquipmentSlot.class);
        g.put(EquipmentSlot.WEAPON,weapon); g.put(EquipmentSlot.NECK,blessing);
        g.put(EquipmentSlot.HEAD,helm); g.put(EquipmentSlot.BODY,body); g.put(EquipmentSlot.LEGS,legs);
        return g;
    }

    private List<EquipmentCandidate> usable(List<EquipmentCandidate> all,int limit)
    {
        List<EquipmentCandidate>x=new ArrayList<>();
        if(all!=null)
        {
            for(EquipmentCandidate c:all)
            {
                if(!c.getRequirementResult().isBlocked() && x.size()<limit) x.add(c);
            }
            EquipmentCandidate prayerBest=null;
            for(EquipmentCandidate c:all)if(!c.getRequirementResult().isBlocked()
                &&(prayerBest==null||c.getPrayer()>prayerBest.getPrayer()))prayerBest=c;
            if(prayerBest!=null&&prayerBest.getPrayer()>0&&!x.contains(prayerBest))x.add(prayerBest);
            // Set-effect pieces can look weak individually, so always preserve owned,
            // usable synergy pieces even when they fall outside the ordinary top-N.
            for(EquipmentCandidate c:all)
            {
                if(!c.getRequirementResult().isBlocked()
                    && MeleeLoadoutEffects.isSynergyItem(c) && !x.contains(c)) x.add(c);
            }
        }
        return x;
    }

    private int prayerBonus(Map<EquipmentSlot,EquipmentCandidate> g)
    {
        int p=0; for(EquipmentCandidate c:g.values())if(c!=null)p+=c.getPrayer(); return p;
    }

    private boolean isSpecial(String name,MonsterDefinition m)
    {
        if(name==null||m==null)return false;
        String n=name.toLowerCase();
        if(m.hasAttribute("demon")&&(n.contains("arclight")||n.contains("emberlight")||
            n.contains("silverlight")||n.contains("darklight")))return true;
        if(m.hasAttribute("undead")&&(n.contains("salve")||n.contains("blisterwood")))return true;
        if(n.contains("fang")||n.contains("scythe")||n.contains("keris")||n.contains("dragon hunter"))return true;
        return false;
    }
}

