            if ((requestedStyle == AttackStyle.MELEE_SLASH || requestedStyle == AttackStyle.MELEE_STAB || requestedStyle == AttackStyle.MELEE_CRUSH)
                && selectedCombat != null)
            {
                validation.append(System.lineSeparator()).append(System.lineSeparator());
