import net.runelite.client.plugins.slayer.SlayerPlugin;
import net.runelite.client.ui.ClientToolbar;
import net.runelite.client.ui.NavigationButton;
import net.runelite.client.ui.overlay.OverlayManager;
import net.runelite.client.util.ImageUtil;

@PluginDescriptor(
    name = "My BiS Finder",
    description = "Find your best owned gear for any target using your bank, levels and Slayer task.",
    tags = {"bis", "gear", "equipment", "bank", "combat", "slayer"}
)
@PluginDependency(SlayerPlugin.class)
public class PersonalBisPlugin extends Plugin
{
    @Inject private ClientToolbar clientToolbar;
    @Inject private OverlayManager overlayManager;
    @Inject private MouseManager mouseManager;
    @Inject private PersonalBisPanel panel;
    @Inject private BankBisOverlay bankBisOverlay;
    @Inject private ClientThread clientThread;
    @Inject private EventBus eventBus;
    @Inject private PersonalBisBankFilter bankFilter;

    private NavigationButton navigationButton;
    private int tickCounter;

    private final MouseListener bankButtonMouseListener = new MouseListener()
    {
        @Override public MouseEvent mouseClicked(MouseEvent event) { return event; }
        @Override public MouseEvent mousePressed(MouseEvent event)
        {
            if (bankBisOverlay.contains(event.getPoint()))
            {
                bankFilter.toggle();
                event.consume();
            }
            return event;
        }
        @Override public MouseEvent mouseReleased(MouseEvent event) { return event; }
        @Override public MouseEvent mouseEntered(MouseEvent event) { return event; }
        @Override public MouseEvent mouseExited(MouseEvent event) { return event; }
        @Override public MouseEvent mouseDragged(MouseEvent event) { return event; }
        @Override public MouseEvent mouseMoved(MouseEvent event) { return event; }
    };

    @Provides
    PersonalBisConfig provideConfig(ConfigManager configManager)
    {
        return configManager.getConfig(PersonalBisConfig.class);
    }

    @Override
    protected void startUp()
    {
        BufferedImage icon = ImageUtil.loadImageResource(getClass(), "/personal-bis-icon.png");
        navigationButton = NavigationButton.builder()
            .tooltip("My BiS Finder")
            .icon(icon)
            .priority(50)
            .panel(panel)
            .build();

        clientToolbar.addNavigation(navigationButton);
        overlayManager.add(bankBisOverlay);
        eventBus.register(bankFilter);
        mouseManager.registerMouseListener(bankButtonMouseListener);
        clientThread.invokeLater(() ->
        {
            panel.refreshAll();
        });
    }

    @Override
    protected void shutDown()
    {
        mouseManager.unregisterMouseListener(bankButtonMouseListener);
        bankFilter.deactivate();
        eventBus.unregister(bankFilter);
        overlayManager.remove(bankBisOverlay);
        if (navigationButton != null)
        {
            clientToolbar.removeNavigation(navigationButton);
        }
    }

    @Subscribe
    public void onStatChanged(StatChanged event)
    {
        panel.updatePlayerStats();
    }

    @Subscribe
    public void onItemContainerChanged(ItemContainerChanged event)
    {
        if (event.getContainerId() == InventoryID.BANK)
        {
            // Keep ownership current without discarding generated loadouts or
            // rerunning the optimiser. Recalculation remains a manual action.
            panel.refreshBankItems();
        }
        else if (event.getContainerId() == InventoryID.INV
            || event.getContainerId() == InventoryID.WORN)
        {
            panel.refreshRubyBoltOwnership();
        }
    }

    @Subscribe
    public void onGameStateChanged(GameStateChanged event)
    {
        if (event.getGameState() == GameState.LOGGED_IN)
        {
            panel.refreshAll();
        }
    }

    @Subscribe
    public void onGameTick(GameTick event)
    {
        if (++tickCounter >= 2)
        {
            tickCounter = 0;
            panel.refreshSlayerTaskIfChanged();
        }
    }

    @Subscribe
    public void onConfigChanged(ConfigChanged event)
    {
        if ("personalbis".equals(event.getGroup()))
        {
            clientThread.invokeLater(panel::updatePlayerStats);
        }
    }
}

package com.personalbis;
public final class PoweredStaff {
 public final String label; public final int minLevel,speed;
 private final int offset,minHit;
 private PoweredStaff(String l,int ml,int s,int o,int mh){label=l;minLevel=ml;speed=s;offset=o;minHit=mh;}
 public int baseMaxHit(int visibleMagic){
  if("Tumeken's shadow".equals(label)) return Math.max(1,(visibleMagic/3)+1);
  if("Eye of ayak".equals(label)) return Math.max(1,(visibleMagic/3)-6);
  if("Sanguinesti staff".equals(label)) return Math.max(1,visibleMagic/3);
  if("Warped sceptre".equals(label)) return Math.max(1,(8*visibleMagic+96)/37);
  return Math.max(minHit,(visibleMagic/3)+offset);
 }
 public static boolean requiresContext(String raw){String n=raw==null?"":raw.toLowerCase();return n.contains("accursed sceptre")||n.contains("thammaron");}
 public static PoweredStaff forWeapon(String raw){
  if(raw==null)return null;String n=raw.toLowerCase();
  if(n.contains("trident of the swamp"))return new PoweredStaff("Trident of the swamp",78,4,-2,23);
  if(n.contains("trident of the seas"))return new PoweredStaff("Trident of the seas",75,4,-5,20);
  if(n.contains("sanguinesti staff")||n.contains("holy sanguinesti staff"))return new PoweredStaff("Sanguinesti staff",82,4,-1,6);
  if(n.contains("warped sceptre"))return new PoweredStaff("Warped sceptre",62,4,-8,1);
  if(n.equals("bone staff"))return new PoweredStaff("Bone staff",50,4,5,21);
  if(n.equals("tumeken's shadow"))return new PoweredStaff("Tumeken's shadow",85,5,-20,1);
  if(n.equals("eye of ayak"))return new PoweredStaff("Eye of ayak",83,3,-6,21);
  return null;
 }
}

package com.personalbis;

public final class PrayerUnlockPolicy
{
    private PrayerUnlockPolicy(){}

    public static boolean chivalry(int prayerLevel,int knightWavesState)
    {
        return prayerLevel>=60 && knightWavesState>=8;
    }

    public static boolean piety(int prayerLevel,int knightWavesState)
    {
        return prayerLevel>=70 && knightWavesState>=8;
    }

    public static boolean rigour(int prayerLevel,boolean unlocked)
    {
        return prayerLevel>=74 && unlocked;
    }

    public static boolean augury(int prayerLevel,boolean unlocked)
    {
        return prayerLevel>=77 && unlocked;
    }
}

package com.personalbis;
/** Phase-1 weapon/ammunition compatibility and ranged defence classification. */
public final class RangedAmmoRules {
 private RangedAmmoRules(){}

 public static RangedAmmoType weaponAmmo(EquipmentCandidate w){
  if(w==null)return RangedAmmoType.NONE;
  String n=name(w), c=w.getWeaponCategory().toLowerCase();
  if(n.contains("bow of faerdhinen")||n.contains("crystal bow")||n.contains("twisted bow")&&false)return RangedAmmoType.INTERNAL;
  if(n.contains("blowpipe"))return RangedAmmoType.DART;
  if(c.contains("crossbow")||n.contains("crossbow"))return RangedAmmoType.BOLT;
  if(c.equals("bow")||n.endsWith(" bow")||n.contains("shortbow")||n.contains("longbow")||n.contains("twisted bow"))return RangedAmmoType.ARROW;
  if(c.contains("thrown")||n.contains("knife")||n.contains("javelin")||n.contains("thrownaxe"))return RangedAmmoType.INTERNAL;
  return RangedAmmoType.NONE;
 }

 public static RangedAmmoType ammoType(EquipmentCandidate a){
  if(a==null)return RangedAmmoType.NONE; String n=name(a);
  if(n.contains("arrow"))return RangedAmmoType.ARROW;
  if(n.contains("bolt")&&!n.contains("bolt pouch"))return RangedAmmoType.BOLT;
  if(n.contains("dart"))return RangedAmmoType.DART;
  return RangedAmmoType.NONE;
 }

 public static boolean compatible(EquipmentCandidate w,EquipmentCandidate a){
  // Blowpipe darts are stored inside the weapon rather than equipped in the
  // ammo slot. The Wiki equipment table therefore reports no equipped-ammo
  // applicability; production optimisation must still pair the weapon with
  // an owned dart so its Ranged Strength is included.
  if(usesLoadedDarts(w))return a!=null&&ammoType(a)==RangedAmmoType.DART;
  if(w!=null){ WikiEquipmentEngine.AmmoApplicability wa=WikiEquipmentEngine.ammoApplicability(w.getItem().getItemId(),a==null?null:a.getItem().getItemId()); if(wa==WikiEquipmentEngine.AmmoApplicability.INVALID)return false; if(wa==WikiEquipmentEngine.AmmoApplicability.INCLUDED)return true; }
  RangedAmmoType need=weaponAmmo(w);
  if(need==RangedAmmoType.NONE||need==RangedAmmoType.INTERNAL)return a==null;
  if(a==null||ammoType(a)!=need)return false;
  return tierCompatible(w,a);
 }
 public static String ammoDisplay(EquipmentCandidate w){
  RangedAmmoType t=weaponAmmo(w);
  if(t==RangedAmmoType.INTERNAL)return "Internal";
  if(t==RangedAmmoType.DART)return "Loaded darts";
  if(t==RangedAmmoType.NONE)return "None";
  return t.toString();
 }
 private static boolean tierCompatible(EquipmentCandidate w,EquipmentCandidate a){
  String wn=name(w), an=name(a);

  // Dedicated ammunition families must be resolved before the generic metal-bolt
  // progression. Their names contain "bolt", but they are not interchangeable.
  if(isHuntersSunlightCrossbow(wn))
   return an.contains("sunlight antler bolt")||an.contains("moonlight antler bolt");
  if(isHuntersCrossbow(wn))
   return an.contains("kebbit bolt")||an.contains("long kebbit bolt");
  if(wn.contains("karil")&&wn.contains("crossbow"))return an.contains("bolt rack");
  if(wn.contains("dorgeshuun crossbow"))return an.contains("bone bolt");
  if(wn.contains("ballista"))return an.contains("javelin");

  // Special-family ammunition must never leak into ordinary crossbows.
  if(an.contains("kebbit bolt")||an.contains("antler bolt")||an.contains("bolt rack")||an.contains("bone bolt"))
   return false;

  if(weaponAmmo(w)==RangedAmmoType.ARROW){
   int cap=arrowCap(wn), tier=arrowTier(an); return tier==0||cap==0||tier<=cap;
  }
  if(weaponAmmo(w)==RangedAmmoType.BOLT){
   // Crossbow families have many special exceptions; enforce the common metal progression.
   int cap=boltCap(wn), tier=boltTier(an); return tier==0||cap==0||tier<=cap;
  }
  return true;
 }
 private static boolean isHuntersSunlightCrossbow(String n){
  return n.contains("hunter")&&n.contains("sunlight")&&n.contains("crossbow");
 }
 private static boolean isHuntersCrossbow(String n){
  return n.contains("hunter")&&n.contains("crossbow")&&!n.contains("sunlight");
 }
 private static int arrowTier(String n){
  if(n.contains("dragon arrow"))return 7;if(n.contains("amethyst arrow"))return 6;if(n.contains("rune arrow"))return 5;
  if(n.contains("adamant arrow"))return 4;if(n.contains("mithril arrow"))return 3;if(n.contains("steel arrow"))return 2;if(n.contains("iron arrow"))return 1;return 0;
 }
 private static int arrowCap(String n){
  if(n.contains("twisted bow")||n.contains("dark bow"))return 7;if(n.contains("magic")||n.contains("seercull"))return 5;
  if(n.contains("yew"))return 5;if(n.contains("maple"))return 4;if(n.contains("willow"))return 3;if(n.contains("oak"))return 2;if(n.contains("shortbow")||n.contains("longbow"))return 1;return 0;
 }
 private static int boltTier(String n){
  if(n.contains("dragon bolt")||n.contains("dragon bolts"))return 7;
  if(n.contains("runite bolt")||n.contains("rune bolt")||n.contains("dragonstone bolt")||n.contains("onyx bolt"))return 6;
  if(n.contains("adamant bolt")||n.contains("ruby bolt")||n.contains("diamond bolt"))return 5;
  if(n.contains("mithril bolt")||n.contains("sapphire bolt")||n.contains("emerald bolt"))return 4;
  if(n.contains("steel bolt")||n.contains("red topaz bolt"))return 3;
  if(n.contains("iron bolt")||n.contains("pearl bolt"))return 2;
  if(n.contains("bronze bolt")||n.contains("opal bolt"))return 1;
  return 0;
 }
 private static int boltCap(String n){
  if(n.contains("dragon hunter crossbow")||n.contains("dragon crossbow")||n.contains("zaryte crossbow"))return 7;
  if(n.contains("rune crossbow"))return 6;if(n.contains("adamant crossbow"))return 5;if(n.contains("mithril crossbow"))return 4;
  if(n.contains("steel crossbow"))return 3;if(n.contains("iron crossbow"))return 2;if(n.contains("bronze crossbow"))return 1;return 0;
 }

 public enum DefenceClass { LIGHT, STANDARD, HEAVY }

 public static DefenceClass defenceClass(EquipmentCandidate w){
  if(w==null)return DefenceClass.STANDARD;
  String n=name(w), c=w.getWeaponCategory().toLowerCase();
  // Light: arrows, darts, knives and blowpipe-like rapid projectiles.
  if(weaponAmmo(w)==RangedAmmoType.ARROW || weaponAmmo(w)==RangedAmmoType.DART ||
     n.contains("knife") || n.contains("dart") || n.contains("blowpipe"))
   return DefenceClass.LIGHT;
  // Heavy projectile families. Keep crossbows STANDARD: bolts use standard defence.
  if(n.contains("ballista") || n.contains("javelin") || n.contains("thrownaxe") ||
     c.contains("ballista"))
   return DefenceClass.HEAVY;
  return DefenceClass.STANDARD;
 }

 public static int targetDefence(MonsterDefinition m,EquipmentCandidate w){
  if(m==null)return 0;
  switch(defenceClass(w)){
   case LIGHT:return m.getLightDefence();
   case HEAVY:return m.getHeavyDefence();
   default:return m.getStandardDefence();
  }
 }

 /** True when the equipped ammo slot is reserved for ammunition. */
 public static boolean requiresEquippedAmmo(EquipmentCandidate w){
  RangedAmmoType t=weaponAmmo(w);
  return t==RangedAmmoType.ARROW||t==RangedAmmoType.BOLT;
 }

 /** True when the ammo equipment slot is free for a blessing/neutral item. */
 public static boolean ammoSlotFreeForNeutralGear(EquipmentCandidate w){
  return !requiresEquippedAmmo(w);
 }

 public static boolean usesLoadedDarts(EquipmentCandidate w){return w!=null&&name(w).contains("blowpipe");}

 /** Defensive guard for mandatory-shield targets when upstream item metadata is incomplete. */
 public static boolean occupiesBothHands(EquipmentCandidate w){
  if(w==null)return false;
  String n=name(w);
  // Rune crossbows are one-handed. Keep this authoritative override ahead of
  // imported metadata so mandatory shields remain eligible after data refreshes.
  if(n.equals("rune crossbow")||n.startsWith("rune crossbow ("))return false;
  return w.isTwoHanded()||n.contains("blowpipe")
    ||((n.endsWith(" bow")||n.contains("shortbow")||n.contains("longbow")||n.contains("twisted bow"))
       &&!n.contains("crossbow"));
 }

 public static boolean usesExternalAmmo(EquipmentCandidate w){
  return requiresEquippedAmmo(w);
 }
 private static String name(EquipmentCandidate c){return c.getItem().getName().toLowerCase();}
}

package com.personalbis;
import java.util.Map;
import java.util.HashMap;
import javax.inject.Inject;
import net.runelite.api.Skill;
public class RangedCombatCalculator {
 private final AccountSnapshot account;
 @Inject public RangedCombatCalculator(AccountSnapshot a){account=a;}
 public RangedCombatResult calculate(Map<EquipmentSlot,EquipmentCandidate> gear,MonsterDefinition m,boolean task){
  RangedCombatResult best=null;
  for(RangedStance st:RangedStance.values())for(RangedPrayer p:prayers()){
   RangedCombatResult r=calculate(gear,m,task,st,p); if(best==null||FinalLoadoutSelection.betterTtk(r.getExpectedTtkSeconds(),r.getDps(),best.getExpectedTtkSeconds(),best.getDps()))best=r;
  } return best;
 }
 public RangedCombatResult calculate(Map<EquipmentSlot,EquipmentCandidate> gear,MonsterDefinition m,boolean task,RangedStance st,RangedPrayer p){
  int atk=0,str=0,speed=4; boolean slayer=false; EquipmentCandidate weapon=gear.get(EquipmentSlot.WEAPON);
  for(EquipmentCandidate c:gear.values()){if(c==null)continue;
   if(c.getSlot()==EquipmentSlot.AMMO && !RangedAmmoRules.compatible(weapon,c)) continue;
   atk+=c.getRangedAttack();str+=c.getRangedStrength();
   if(c.getSlot()==EquipmentSlot.WEAPON&&c.getAttackSpeed()>0)speed=c.getAttackSpeed();
   String n=c.getItem().getName().toLowerCase(); if(c.getSlot()==EquipmentSlot.HEAD&&(n.contains("slayer helm")||n.contains("slayer helmet")||n.contains("black mask"))&&(n.contains("(i)")||n.contains("imbued")))slayer=true;}
  // transform(str, rangedStr, magicAttack, magicDamage, rangedAttack): ranged
  // strength must occupy the second numeric channel. Passing it as melee Str
  // zeroed every weapon/ammo Ranged Strength during the exact final evaluation.
  WikiEquipmentEngine.Totals wikiEq=WikiEquipmentEngine.transform(gear,m,null,0,str,0,0.0,atk); atk=wikiEq.rangedAttack; str=wikiEq.rangedStr;
  int level=Math.max(1,account.boosted(Skill.RANGED));
  boolean voidRanged=RangedLoadoutEffects.voidRanged(gear), eliteVoid=RangedLoadoutEffects.eliteVoidRanged(gear);
  int eff=CombatEffectiveLevels.ranged(level,p.getRanged(),st.getRangedBoost(),voidRanged);
  boolean salve=RangedLoadoutEffects.rangedSalveActive(gear,m);
  int roll=eff*(atk+64);
  roll=(int)Math.floor(roll*RangedLoadoutEffects.crystalAccuracy(gear,weapon));
  roll=WikiRangedEffects.accuracyAfterExclusive(roll,gear.values(),m,task,slayer);
  roll=WikiRangedEffects.postAccuracy(roll,weapon,m,st,4);
  int def=m==null?1:Math.max(1,m.getDefenceLevel()), bonus=RangedAmmoRules.targetDefence(m,weapon);
  int defRoll=(def+9)*(bonus+64);
  double acc=WikiAccuracyRoll.normal(roll,defRoll);
  int dmgEff=CombatEffectiveLevels.rangedDamage(level,p.getRangedStrength(),st.getRangedBoost(),voidRanged,eliteVoid);
  int max=WikiIntegerStages.maxHitFromEffective(dmgEff,str+64);
  max=(int)Math.floor(max*RangedLoadoutEffects.crystalDamage(gear,weapon));
  max=WikiRangedEffects.damageAfterExclusive(max,gear.values(),m,weapon,task,slayer);
  max=WikiRangedEffects.postDamage(max,weapon,m,task,slayer);
  // Wiki parity: Bone shortbow receives the ratbane flat +10 max hit on rat targets.
  max += MeleeWeaponEffects.ratbaneBonusMax(weapon,m);
  int actualSpeed=WikiAttackSpeedRules.attackTicks(Math.max(1,speed+st.getSpeedDelta()),weapon,m);
  EquipmentCandidate ammo=gear.get(EquipmentSlot.AMMO);
  HitDistribution.AttackDistribution rangedDist=WikiPlayerVsNpcCalc.rangedFinalDistribution(
      weapon,ammo,m,level,max,acc,account.isKandarinHardCompleted(),gear.values());
  final int normalMax=max;
  double expectedDamage=WikiPlayerVsNpcCalc.expectedDamage(rangedDist);
  double dps=WikiPlayerVsNpcCalc.dps(rangedDist,actualSpeed);
  int targetHp=m==null?1:Math.max(1,m.getHitpoints());
  boolean ruby=ammo!=null&&ammo.getItem()!=null&&ammo.getItem().getName().toLowerCase().contains("ruby");
  Map<Integer,HitDistribution.AttackDistribution> hpDists=ruby?new HashMap<>():null;
  HitDistribution rubyBase=ruby?WikiPlayerVsNpcCalc.rangedRubyBaseDistribution(
      m,level,normalMax,acc,account.isKandarinHardCompleted()):null;
  double ttk=ruby
      ?ExpectedKillTime.seconds(targetHp,actualSpeed,hp->hpDists.computeIfAbsent(EnchantedBoltEffects.rubyHpBucket(hp),key->
          WikiPlayerVsNpcCalc.rangedRubyFinalDistributionAtHp(rubyBase,weapon,ammo,m,
              account.isKandarinHardCompleted(),key)))
      :ExpectedKillTime.seconds(rangedDist,targetHp,actualSpeed);
  max=rangedDist.max();
  if(!WikiTargetEligibility.rangedCanDamage(m) || !LeafyTargetRules.rangedCanDamage(m,ammo) || !MeleeWeaponEffects.ratBoneCanDamage(weapon,m)){max=0;dps=0.0;ttk=Double.POSITIVE_INFINITY;}
  return new RangedCombatResult(dps,ttk,acc,max,roll,defRoll,atk,str,actualSpeed,eff,dmgEff,st,p);
 }
 private RangedPrayer[] prayers(){int x=account.real(Skill.PRAYER);
  if(x>=74 && account.isRigourUnlocked())return new RangedPrayer[]{RangedPrayer.NONE,RangedPrayer.RIGOUR};
  if(x>=62 && account.isDeadeyeUnlocked())return new RangedPrayer[]{RangedPrayer.NONE,RangedPrayer.DEADEYE};
  if(x>=44)return new RangedPrayer[]{RangedPrayer.NONE,RangedPrayer.EAGLE_EYE};
  if(x>=26)return new RangedPrayer[]{RangedPrayer.NONE,RangedPrayer.HAWK_EYE};
  if(x>=8)return new RangedPrayer[]{RangedPrayer.NONE,RangedPrayer.SHARP_EYE};
  return new RangedPrayer[]{RangedPrayer.NONE};}
}

package com.personalbis;
public final class RangedCombatResult {
 private final double dps,expectedTtkSeconds,accuracy; private final int maxHit,attackRoll,defenceRoll,rangedAttack,rangedStrength,speed,effectiveRanged,effectiveDamage;
 private final RangedStance stance; private final RangedPrayer prayer;
 public RangedCombatResult(double d,double a,int m,int ar,int dr,int ra,int rs,int sp,int er,int ed,RangedStance st,RangedPrayer p)
 {this(d,Double.POSITIVE_INFINITY,a,m,ar,dr,ra,rs,sp,er,ed,st,p);}
 public RangedCombatResult(double d,double ttk,double a,int m,int ar,int dr,int ra,int rs,int sp,int er,int ed,RangedStance st,RangedPrayer p)
 {dps=d;expectedTtkSeconds=ttk;accuracy=a;maxHit=m;attackRoll=ar;defenceRoll=dr;rangedAttack=ra;rangedStrength=rs;speed=sp;effectiveRanged=er;effectiveDamage=ed;stance=st;prayer=p;}
 public double getDps(){return dps;} public double getAccuracy(){return accuracy;} public int getMaxHit(){return maxHit;}
 public double getExpectedTtkSeconds(){return expectedTtkSeconds;}
 public int getAttackRoll(){return attackRoll;} public int getDefenceRoll(){return defenceRoll;} public int getRangedAttack(){return rangedAttack;}
 public int getRangedStrength(){return rangedStrength;} public int getAttackSpeed(){return speed;} public int getEffectiveRanged(){return effectiveRanged;} public int getEffectiveDamage(){return effectiveDamage;}
 public RangedStance getStance(){return stance;} public RangedPrayer getPrayer(){return prayer;}
}

package com.personalbis;
import java.util.Map;
public final class RangedLoadoutEffects {
 private RangedLoadoutEffects(){}
 public static double crystalAccuracy(Map<EquipmentSlot,EquipmentCandidate> g,EquipmentCandidate w){
  if(!RangedWeaponEffects.usesCrystalArmourBonus(w))return 1.0; double b=0;
  if(named(g.get(EquipmentSlot.HEAD),"crystal helm"))b+=0.05;
  if(named(g.get(EquipmentSlot.BODY),"crystal body"))b+=0.15;
  if(named(g.get(EquipmentSlot.LEGS),"crystal legs"))b+=0.10;
  return 1+b;
 }
 public static double crystalDamage(Map<EquipmentSlot,EquipmentCandidate> g,EquipmentCandidate w){
  if(!RangedWeaponEffects.usesCrystalArmourBonus(w))return 1.0; double b=0;
  if(named(g.get(EquipmentSlot.HEAD),"crystal helm"))b+=0.025;
  if(named(g.get(EquipmentSlot.BODY),"crystal body"))b+=0.075;
  if(named(g.get(EquipmentSlot.LEGS),"crystal legs"))b+=0.05;
  return 1+b;
 }
 public static boolean voidRanged(Map<EquipmentSlot,EquipmentCandidate> g){
  return named(g.get(EquipmentSlot.HEAD),"void ranger helm") &&
   (named(g.get(EquipmentSlot.BODY),"void knight top")||named(g.get(EquipmentSlot.BODY),"elite void top")) &&
   (named(g.get(EquipmentSlot.LEGS),"void knight robe")||named(g.get(EquipmentSlot.LEGS),"elite void robe")) &&
   named(g.get(EquipmentSlot.HANDS),"void knight gloves");
 }
 public static boolean eliteVoidRanged(Map<EquipmentSlot,EquipmentCandidate> g){
  return named(g.get(EquipmentSlot.HEAD),"void ranger helm") &&
   named(g.get(EquipmentSlot.BODY),"elite void top") &&
   named(g.get(EquipmentSlot.LEGS),"elite void robe") &&
   named(g.get(EquipmentSlot.HANDS),"void knight gloves");
 }
 public static double voidAccuracy(Map<EquipmentSlot,EquipmentCandidate> g){return voidRanged(g)?1.10:1.0;}
 public static double voidDamage(Map<EquipmentSlot,EquipmentCandidate> g){return voidRanged(g)?1.10:1.0;}
 public static boolean synergy(EquipmentCandidate c){if(c==null)return false;String n=c.getItem().getName().toLowerCase();
  return n.contains("crystal helm")||n.contains("crystal body")||n.contains("crystal legs")||n.contains("void ranger helm")||
   n.contains("void knight top")||n.contains("elite void top")||n.contains("void knight robe")||n.contains("elite void robe")||
   n.contains("void knight gloves")||n.contains("salve amulet(i)")||n.contains("salve amulet (i)")||
   n.contains("salve amulet(ei)")||n.contains("salve amulet (ei)")||n.contains("karil's coif")||
   n.contains("karil's leathertop")||n.contains("karil's leatherskirt")||n.contains("amulet of the damned");}
 private static boolean named(EquipmentCandidate c,String n){return c!=null&&c.getItem().getName().toLowerCase().contains(n);}

 public static double salveAccuracy(Map<EquipmentSlot,EquipmentCandidate> gear, MonsterDefinition m){
  if(!isUndead(m)) return 1.0;
  String n=neckName(gear);
  if(n.contains("salve amulet(ei)")||n.contains("salve amulet (ei)")) return 1.20;
  if(n.contains("salve amulet(i)")||n.contains("salve amulet (i)")) return 7.0/6.0;
  return 1.0;
 }
 public static double salveDamage(Map<EquipmentSlot,EquipmentCandidate> gear, MonsterDefinition m){
  return salveAccuracy(gear,m);
 }
 public static boolean rangedSalveActive(Map<EquipmentSlot,EquipmentCandidate> gear, MonsterDefinition m){
  return salveAccuracy(gear,m)>1.0;
 }
 private static boolean isUndead(MonsterDefinition m){
  return m!=null && (m.hasAttribute("undead") || m.hasAttribute("spectral"));
 }
 private static String neckName(Map<EquipmentSlot,EquipmentCandidate> gear){
  EquipmentCandidate c=gear.get(EquipmentSlot.NECK);
  return c==null?"":c.getItem().getName().toLowerCase();
 }
}

package com.personalbis;
import java.util.*;
import java.util.stream.IntStream;
import javax.inject.Inject;
import net.runelite.api.Skill;

public class RangedLoadoutOptimizer {
 // alpha50.4.50.80: accuracy-first rollback. The narrower 6/48/8 search was
 // fast, but real banks showed it could discard complete Crystal/Bowfa and
 // crossbow branches. Retain the safe caches/parallelism while restoring broad
 // supporting-gear coverage and exact final comparison.
 private static final int SLOT=12, BEAM=128, EXACT_FINALISTS=48;
 private final EquipmentIntelligence intel; private final RangedCombatCalculator calc; private final AccountSnapshot account;
 private volatile String lastProfileSummary="";
 private final ThreadLocal<Profile> activeProfile=new ThreadLocal<>();
 private static final class Profile {
  long started=System.nanoTime(), trimNanos, finalNanos, completionNanos;
  int weapons, ammoBranches, trimCalls, dpsCalls, fastScoreCalls, statesScored, uniqueStatesScored, dedupedStates, scoreCacheHits, finalStates, completionTrials;
  int slotCandidatesBefore, slotCandidatesAfter, slotCandidatesPruned;
  final Map<String,Double> scoreCache=new HashMap<>();
  final Map<String,RangedCombatResult> exactCache=new HashMap<>();
  final EnumMap<EquipmentSlot,List<EquipmentCandidate>> choiceCache=new EnumMap<>(EquipmentSlot.class);
 }
 private static final class WeaponResult {
  final EquipmentCandidate weapon; final OptimizedRangedLoadout loadout;
  WeaponResult(EquipmentCandidate w,OptimizedRangedLoadout l){weapon=w;loadout=l;}
 }
 public String getLastProfileSummary(){return lastProfileSummary;}
 @Inject public RangedLoadoutOptimizer(EquipmentIntelligence i,RangedCombatCalculator c,AccountSnapshot a){intel=i;calc=c;account=a;}

 public OptimizedRangedLoadout optimize(List<BankItem>b,MonsterDefinition m,boolean task){return optimizeWithReport(b,m,task).getBest();}

 public RangedOptimizationReport optimizeWithReport(List<BankItem>b,MonsterDefinition m,boolean task){
  Map<EquipmentSlot,List<EquipmentCandidate>> ranked=intel.rank(b,AttackStyle.RANGED,task);
  return optimizeWithReportRanked(ranked,m,task);
 }
 public RangedOptimizationReport optimizeWithReportRanked(Map<EquipmentSlot,List<EquipmentCandidate>> ranked,MonsterDefinition m,boolean task){
  Profile profile=new Profile(); activeProfile.set(profile);
  try {
  ranked=SlayerTargetRequirements.constrainRanked(m,ranked);
  EquipmentSlot requiredSlot=SlayerTargetRequirements.requiredEquipmentSlot(m);
  EquipmentCandidate requiredEquipment=requiredSlot==null?null:SlayerTargetRequirements.firstRequiredEquipment(m,ranked.get(requiredSlot));
  // Alpha 50.4 completeness pass: evaluate every owned/equippable ranged
  // weapon. Exact target DPS, ammo compatibility and complete gear decide BiS;
  // raw Equipment Intelligence rank no longer excludes a weapon up front.
  List<EquipmentCandidate> weapons=allUsable(ranked.get(EquipmentSlot.WEAPON));
  profile.weapons=weapons.size();
  List<RangedWeaponComparison> comps=new ArrayList<>(); OptimizedRangedLoadout best=null;
  final Map<EquipmentSlot,List<EquipmentCandidate>> searchRanked=ranked;
  final Profile masterProfile=profile;
  List<WeaponResult> weaponResults=IntStream.range(0,weapons.size()).parallel().mapToObj(i->{
   EquipmentCandidate w=weapons.get(i);
   if(requiredSlot==EquipmentSlot.SHIELD&&RangedAmmoRules.occupiesBothHands(w))return new WeaponResult(w,null);
   Profile branch=new Profile();activeProfile.set(branch);
   try{return new WeaponResult(w,optimizeWeapon(searchRanked,w,m,task,requiredEquipment));}
   finally{activeProfile.remove();mergeProfile(masterProfile,branch);}
  }).collect(java.util.stream.Collectors.toList());
  activeProfile.set(profile);
  for(WeaponResult wr:weaponResults){
   EquipmentCandidate w=wr.weapon;OptimizedRangedLoadout one=wr.loadout;
   if(one==null)continue;
   EquipmentCandidate ammo=one.getLoadedAmmo()!=null?one.getLoadedAmmo():one.getItems().get(EquipmentSlot.AMMO);
   comps.add(new RangedWeaponComparison(w.getItem().getName(),ammo==null?RangedAmmoRules.ammoDisplay(w):ammo.getItem().getName(),RangedAmmoRules.weaponAmmo(w),RangedAmmoRules.defenceClass(w),
    ammo==null?"":EnchantedBoltEffects.effectLabel(ammo),one.getResult(),gearSummary(one.getItems()),one.getItems()));
   if(best==null||FinalLoadoutSelection.betterTtk(one.getResult().getExpectedTtkSeconds(),one.getResult().getDps(),best.getResult().getExpectedTtkSeconds(),best.getResult().getDps()))best=one;
  }
  comps.sort((a,z)->FinalLoadoutSelection.compareTtk(a.getResult().getExpectedTtkSeconds(),a.getResult().getDps(),z.getResult().getExpectedTtkSeconds(),z.getResult().getDps()));
  return new RangedOptimizationReport(best,comps);
  } finally {
   long total=System.nanoTime()-profile.started;
   long other=Math.max(0,total-profile.trimNanos-profile.finalNanos-profile.completionNanos);
   lastProfileSummary="Ranged detail:"+System.lineSeparator()+
    "  Weapons: "+profile.weapons+" | ammo branches: "+profile.ammoBranches+System.lineSeparator()+
