 public static boolean isBlowpipeId(int id){return id==12926||id==28688||id==31575||id==31579||id==31583;}
 public static int transformMeleeAttack(Map<EquipmentSlot,EquipmentCandidate> gear,MonsterDefinition monster,int attack){ return "keris partisan of amascut".equals(name(gear.get(EquipmentSlot.WEAPON)))&&!isToa(monster)?attack-50:attack; }
 public static Totals transform(Map<EquipmentSlot,EquipmentCandidate> gear,MonsterDefinition monster,String spellbook,
                                int str,int rangedStr,int magicAttack,double magicDamage,int rangedAttack){
  EquipmentCandidate weapon=gear.get(EquipmentSlot.WEAPON); String wn=name(weapon);
  if("keris partisan of amascut".equals(wn) && !isToa(monster)){str-=22;}
  if(("dinh's bulwark".equals(wn)||"dinh's blazing bulwark".equals(wn))){
   int defenceSum=0;
   for(EquipmentCandidate c:gear.values()){WikiEquipment w=item(c); if(w!=null&&w.defensive!=null)defenceSum+=w.defensive.stab+w.defensive.slash+w.defensive.crush+w.defensive.ranged;}
   str+=Math.max(0,((defenceSum-800)/12)-38);
  }
  if("ancient".equals(spellbook)){
   int pieces=0; for(EquipmentSlot s:Arrays.asList(EquipmentSlot.HEAD,EquipmentSlot.BODY,EquipmentSlot.LEGS)){String n=name(gear.get(s));if(n.contains("virtus"))pieces++;}
   magicDamage+=0.03*pieces;
  }
  if(isEliteVoidMage(gear))magicDamage+=0.05;
  if("tumeken's shadow".equals(wn)){
   int factor=isToa(monster)?4:3; magicAttack*=factor; magicDamage=Math.min(1.0,magicDamage*factor);
  }
  EquipmentCandidate cape=gear.get(EquipmentSlot.CAPE), ammo=gear.get(EquipmentSlot.AMMO);
  WikiEquipment cw=item(cape);
  boolean dizana=cw!=null && ("Dizana's max cape".equals(cw.name)||"Blessed Dizana's quiver".equals(cw.name)||("Dizana's quiver".equals(cw.name)&&"Charged".equals(cw.version)));
  if(dizana && weapon!=null && ammo!=null && ammoApplicability(weapon.getItem().getItemId(),ammo.getItem().getItemId())==AmmoApplicability.INCLUDED){rangedAttack+=10;rangedStr+=1;}
  return new Totals(str,rangedStr,magicAttack,magicDamage,rangedAttack);
 }
 /** Exact Equipment.ts attack-speed ordering. */
 public static int calculateAttackSpeed(int weaponSpeed,String weaponName,MonsterDefinition monster,boolean rangedRapid,boolean castStance,boolean standardSpellbook,boolean manualCast){
  int speed=weaponSpeed>0?weaponSpeed:4;
  if(rangedRapid)speed-=1;
  else if(castStance){if("Harmonised Nightmare staff".equals(weaponName)&&standardSpellbook&&!manualCast)speed=4;else if("Twinflame staff".equals(weaponName))speed=6;else speed=5;}
  if(monster!=null&&monster.getId()==7223&&!manualCast&&("Bone mace".equals(weaponName)||"Bone shortbow".equals(weaponName)||"Bone staff".equals(weaponName)))speed=1;
  return Math.max(speed,1);
 }
 /** Returns the Wiki offensive style name with the greatest value; ties keep stab->slash->crush->magic->ranged order. */
 public static String highestOffensiveStyle(int stab,int slash,int crush,int magic,int ranged){
  String best="stab";int v=stab;if(slash>v){best="slash";v=slash;}if(crush>v){best="crush";v=crush;}if(magic>v){best="magic";v=magic;}if(ranged>v)best="ranged";return best;
 }
 /**
  * Full data-driven Equipment.ts aggregation. item IDs are canonicalised before stats/ammo checks.
  * blowpipeDartId models the Wiki itemVars.blowpipeDartId field; null means no loaded dart.
  */
 public static EquipmentBonuses calculateEquipmentBonuses(Map<EquipmentSlot,Integer> ids,MonsterDefinition monster,String spellbook,
    boolean castStance,boolean manualCast,boolean rangedRapid,Integer blowpipeDartId){
  EquipmentBonuses t=new EquipmentBonuses();
  Integer weaponId=ids.get(EquipmentSlot.WEAPON),ammoId=ids.get(EquipmentSlot.AMMO); WikiEquipment weapon=weaponId==null?null:canonicalItem(weaponId);
  for(Map.Entry<EquipmentSlot,Integer> e:ids.entrySet()){WikiEquipment w=canonicalItem(e.getValue());if(w==null)continue;
   boolean apply=e.getKey()!=EquipmentSlot.AMMO||ammoApplicability(weaponId==null?-1:weaponId,e.getValue())==AmmoApplicability.INCLUDED;
   if(w.bonuses!=null){t.str+=w.bonuses.str;if(apply)t.rangedStr+=w.bonuses.ranged_str;t.magicDamage+=w.bonuses.magic_str/1000.0;t.prayer+=w.bonuses.prayer;}
   if(w.offensive!=null){t.stabAttack+=w.offensive.stab;t.slashAttack+=w.offensive.slash;t.crushAttack+=w.offensive.crush;t.magicAttack+=w.offensive.magic;if(apply)t.rangedAttack+=w.offensive.ranged;}
   if(w.defensive!=null){t.stabDefence+=w.defensive.stab;t.slashDefence+=w.defensive.slash;t.crushDefence+=w.defensive.crush;t.magicDefence+=w.defensive.magic;t.rangedDefence+=w.defensive.ranged;}
  }
  if(weapon!=null&&isBlowpipeId(weapon.id)&&blowpipeDartId!=null){WikiEquipment dart=canonicalItem(blowpipeDartId);if(dart!=null&&dart.bonuses!=null)t.rangedStr+=dart.bonuses.ranged_str;}
  String wn=weapon==null?"":weapon.name;
  if("Tumeken's shadow".equals(wn)&&!manualCast){int f=isToa(monster)?4:3;t.magicDamage=Math.min(1.0,t.magicDamage*f);t.magicAttack*=f;}
  if("Keris partisan of amascut".equals(wn)&&!isToa(monster)){t.str-=22;t.stabAttack-=50;}
  if("Dinh's bulwark".equals(wn)||"Dinh's blazing bulwark".equals(wn)){int ds=t.stabDefence+t.slashDefence+t.crushDefence+t.rangedDefence;t.str+=Math.max(0,((ds-800)/12)-38);}
  if("ancient".equals(spellbook)&&castStance){int pieces=0;for(EquipmentSlot s:Arrays.asList(EquipmentSlot.HEAD,EquipmentSlot.BODY,EquipmentSlot.LEGS)){Integer id=ids.get(s);WikiEquipment w=id==null?null:canonicalItem(id);if(w!=null&&w.name.contains("Virtus"))pieces++;}t.magicDamage+=.03*pieces;}
  if(named(ids,EquipmentSlot.HEAD,"Void mage helm")&&named(ids,EquipmentSlot.BODY,"Elite void top")&&named(ids,EquipmentSlot.LEGS,"Elite void robe")&&named(ids,EquipmentSlot.HANDS,"Void knight gloves"))t.magicDamage+=.05;
  Integer capeId=ids.get(EquipmentSlot.CAPE);WikiEquipment cape=capeId==null?null:canonicalItem(capeId);boolean dizana=cape!=null&&("Dizana's max cape".equals(cape.name)||"Blessed Dizana's quiver".equals(cape.name)||("Dizana's quiver".equals(cape.name)&&"Charged".equals(cape.version)));
  if(dizana&&weaponId!=null&&ammoId!=null&&ammoApplicability(weaponId,ammoId)==AmmoApplicability.INCLUDED){t.rangedAttack+=10;t.rangedStr+=1;}
  t.attackSpeed=calculateAttackSpeed(weapon==null?4:weapon.speed,wn,monster,rangedRapid,castStance,"standard".equals(spellbook),manualCast);return t;
 }
 private static boolean named(Map<EquipmentSlot,Integer> ids,EquipmentSlot slot,String n){Integer id=ids.get(slot);WikiEquipment w=id==null?null:canonicalItem(id);return w!=null&&n.equals(w.name);}
 private static boolean isEliteVoidMage(Map<EquipmentSlot,EquipmentCandidate> g){return "void mage helm".equals(name(g.get(EquipmentSlot.HEAD)))&&"elite void top".equals(name(g.get(EquipmentSlot.BODY)))&&"elite void robe".equals(name(g.get(EquipmentSlot.LEGS)))&&"void knight gloves".equals(name(g.get(EquipmentSlot.HANDS)));}
 private static boolean isToa(MonsterDefinition m){return m!=null&&TOA.contains(m.getId());}
 private static WikiEquipment item(EquipmentCandidate c){return c==null?null:canonicalItem(c.getItem().getItemId());}
 private static String name(EquipmentCandidate c){return c==null||c.getItem()==null||c.getItem().getName()==null?"":c.getItem().getName().toLowerCase();}
}

package com.personalbis;

/** Exact integer checkpoints used by the OSRS Wiki DPS calculator. */
public final class WikiIntegerStages
{
    private WikiIntegerStages() {}

    /** Equivalent to Wiki BaseCalc.trackFactor(): truncate immediately after factor application. */
    public static int factor(int base, int numerator, int denominator)
    {
        if (denominator == 0) throw new IllegalArgumentException("denominator");
        return (int)(((long)base * numerator) / denominator);
    }

    /** Equivalent to Wiki BaseCalc.trackAdd(): truncate the completed addition. */
    public static int add(int base, double addend)
    {
        return (int)(base + addend);
    }

    /** Wiki max-hit checkpoint: trunc((effectiveLevel * gearBonus + 320) / 640). */
    public static int maxHitFromEffective(int effectiveLevel, int gearBonus)
    {
        return (int)(((long)effectiveLevel * gearBonus + 320L) / 640L);
    }
}

package com.personalbis;

import java.util.Collection;

/**
 * Source-ordered port of PlayerVsNPCCalc.getPlayerMaxMagicAttackRoll().
 * PBIS supplies account/loadout state; this class owns the Wiki integer stages.
 */
public final class WikiMagicAccuracy
{
    private WikiMagicAccuracy() {}

    public static final class Result
    {
        public final int effectiveLevel;
        public final int baseRoll;
        public final int attackRoll;

        Result(int effectiveLevel, int baseRoll, int attackRoll)
        {
            this.effectiveLevel = effectiveLevel;
            this.baseRoll = baseRoll;
            this.attackRoll = attackRoll;
        }
    }

    public static Result calculate(int magicLevel, double prayerFactor, int magicBonus,
        Collection<EquipmentCandidate> gear, MonsterDefinition monster, MagicSpell spell,
        boolean onSlayerTask)
    {
        int prayerNumerator = (int)Math.round(prayerFactor * 100.0);
        int effective = WikiIntegerStages.factor(Math.max(1, magicLevel), prayerNumerator, 100);
        // PBIS optimizes autocast loadouts. Accurate (+2) is reserved for a later
        // explicit manual-cast stance input, matching the upstream distinction.
        effective += 9;

        boolean magicVoid = has(gear, "Void mage helm")
            && has(gear, "Void knight gloves")
            && (has(gear, "Void knight top") || has(gear, "Elite void top"))
            && (has(gear, "Void knight robe") || has(gear, "Elite void robe"));
        if (magicVoid) effective = WikiIntegerStages.factor(effective, 29, 20);

        int baseRoll = effective * (magicBonus + 64);
        int additivePercent = 0;
        boolean undead = monster != null && monster.hasAttribute("undead");
        boolean salveEi = undead && has(gear, "Salve amulet(ei)");
        boolean salveI = undead && has(gear, "Salve amulet(i)");
        boolean blackMask = !salveEi && !salveI && onSlayerTask
            && (has(gear, "Slayer helmet (i)") || has(gear, "Slayer helm (i)") || has(gear, "Black mask (i)"));
        if (salveEi) additivePercent += 20;
        else if (salveI) additivePercent += 15;

        String weapon = weaponName(gear);
        if (MagicWeaponEffects.isSmokeStaff(weapon) || MagicWeaponEffects.isTwinflame(weapon))
        {
            if (spell != null && "standard".equals(spell.spellbook)) additivePercent += 10;
        }

        int roll = additivePercent == 0 ? baseRoll
            : WikiIntegerStages.factor(baseRoll, 100 + additivePercent, 100);

        if (MagicWeaponEffects.isDraconic(monster))
        {
            if (equals(weapon, "Dragon hunter crossbow")) roll = WikiIntegerStages.factor(roll, 13, 10);
            else if (equals(weapon, "Dragon hunter lance")) roll = WikiIntegerStages.factor(roll, 6, 5);
            else if (MagicWeaponEffects.isDragonHunterWand(weapon)) roll = WikiIntegerStages.factor(roll, 7, 4);
        }

        if (blackMask) roll = WikiIntegerStages.factor(roll, 23, 20);

        if (spell != null && spell.name != null && spell.name.contains("Demonbane")
            && monster != null && monster.hasAttribute("demon"))
        {
            int percent = spell.markOfDarkness ? 40 : 20;
            if (equals(weapon, "Purging staff")) percent *= 2;
            int scaled = percent * DemonbaneEffects.vulnerability(monster) / 100;
            roll += WikiIntegerStages.factor(roll, scaled, 100);
        }

        // Forinthry Surge is intentionally false until PBIS exposes that buff as account state.

        if (has(gear, "Tome of Water") && tomeWaterAccuracyApplies(spell))
            roll = WikiIntegerStages.factor(roll, 6, 5);

        if (monster != null && spell != null && monster.weakTo(spell.element()))
            roll += WikiIntegerStages.factor(baseRoll, monster.getWeaknessSeverity(), 100);

        return new Result(effective, baseRoll, roll);
    }

    static int orderedRoll(int baseRoll, int additivePercent, int dragonNumerator, int dragonDenominator,
        boolean blackMask, int demonbanePercent, int vulnerability, boolean revenant,
        boolean tomeWater, int weaknessPercent)
    {
        int roll = additivePercent == 0 ? baseRoll : WikiIntegerStages.factor(baseRoll, 100 + additivePercent, 100);
        if (dragonNumerator != dragonDenominator) roll = WikiIntegerStages.factor(roll, dragonNumerator, dragonDenominator);
        if (blackMask) roll = WikiIntegerStages.factor(roll, 23, 20);
        int scaledDemonbane = demonbanePercent * vulnerability / 100;
        if (scaledDemonbane != 0) roll += WikiIntegerStages.factor(roll, scaledDemonbane, 100);
        if (revenant) roll = WikiIntegerStages.factor(roll, 3, 2);
        if (tomeWater) roll = WikiIntegerStages.factor(roll, 6, 5);
        if (weaknessPercent != 0) roll += WikiIntegerStages.factor(baseRoll, weaknessPercent, 100);
        return roll;
    }

    private static boolean tomeWaterAccuracyApplies(MagicSpell spell)
    {
        if (spell == null) return false;
        if ("water".equals(spell.element())) return true;
        String n = spell.name == null ? "" : spell.name.toLowerCase();
        return n.contains("bind") || n.contains("snare") || n.contains("entangle");
    }

    private static String weaponName(Collection<EquipmentCandidate> gear)
    {
        if (gear != null) for (EquipmentCandidate c : gear)
            if (c != null && c.getSlot() == EquipmentSlot.WEAPON && c.getItem() != null) return c.getItem().getName();
        return "";
    }

    private static boolean has(Collection<EquipmentCandidate> gear, String name)
    {
        if (gear != null) for (EquipmentCandidate c : gear)
            if (c != null && c.getItem() != null && equals(c.getItem().getName(), name)) return true;
        return false;
    }

    private static boolean equals(String a, String b) { return a != null && a.equalsIgnoreCase(b); }
}

package com.personalbis;

import java.util.Collection;

/** Source-ordered auto-attack port of PlayerVsNPCCalc.getPlayerMaxMagicHit(). */
public final class WikiMagicDamage
{
    private WikiMagicDamage() {}

    public static final class Result
    {
        public final int baseMax;
        public final int minHit;
        public final int maxHit;

        Result(int baseMax, int minHit, int maxHit)
        {
            this.baseMax = baseMax;
            this.minHit = minHit;
            this.maxHit = maxHit;
        }
    }

    public static Result standard(int magicLevel, double equipmentDamage, double prayerDamage,
        Collection<EquipmentCandidate> gear, MonsterDefinition monster, MagicSpell spell,
        boolean onSlayerTask)
    {
        int base = spell == null ? 0 : spell.scaledBaseMax(magicLevel);
        String weapon = weaponName(gear);
        if (spell != null && "Magic Dart".equals(spell.name))
        {
            boolean enhanced = equals(weapon, "Slayer's staff (e)") && onSlayerTask;
            base = enhanced ? 13 + magicLevel / 6 : 10 + magicLevel / 10;
        }
        if (spell != null && spell.name != null && spell.name.toLowerCase().contains("bolt")
            && has(gear, "Chaos gauntlets")) base += 3;
        // Charge is not assumed until its active buff state is exposed by PBIS.
        base += ElementalAmuletEffects.evaluate(gear, spell).flatMaxHit;
        return ordered(base, equipmentDamage, prayerDamage, gear, monster, spell, onSlayerTask, false);
    }

    public static Result powered(int base, double equipmentDamage, double prayerDamage,
        Collection<EquipmentCandidate> gear, MonsterDefinition monster, boolean onSlayerTask)
    {
        return ordered(base, equipmentDamage, prayerDamage, gear, monster, null, onSlayerTask, false);
    }

    static Result ordered(int base, double equipmentDamage, double prayerDamage,
        Collection<EquipmentCandidate> gear, MonsterDefinition monster, MagicSpell spell,
        boolean onSlayerTask, boolean sunfireRunes)
    {
        if (base <= 0) return new Result(0, 0, 0);
        int baseMax = base;
        int damageThousandths = (int)Math.round((equipmentDamage + prayerDamage) * 1000.0);
        String weapon = weaponName(gear);

        if ((MagicWeaponEffects.isSmokeStaff(weapon) || MagicWeaponEffects.isTwinflame(weapon))
            && spell != null && "standard".equals(spell.spellbook)) damageThousandths += 100;

        boolean undead = monster != null && monster.hasAttribute("undead");
        boolean salveEi = undead && has(gear, "Salve amulet(ei)");
        boolean salveI = undead && has(gear, "Salve amulet(i)");
        boolean blackMask = !salveEi && !salveI && onSlayerTask
            && (has(gear, "Slayer helmet (i)") || has(gear, "Slayer helm (i)") || has(gear, "Black mask (i)"));
        if (salveEi) damageThousandths += 200;
        else if (salveI) damageThousandths += 150;

        int max = base + WikiIntegerStages.factor(base, damageThousandths, 1000);
        if (blackMask) max = WikiIntegerStages.factor(max, 23, 20);
        if (equals(weapon, "Dawnbringer")) max = Math.max(2, max / 2);

        if (MagicWeaponEffects.isDraconic(monster))
        {
            if (equals(weapon, "Dragon hunter lance")) max = WikiIntegerStages.factor(max, 6, 5);
            else if (MagicWeaponEffects.isDragonHunterWand(weapon)) max = WikiIntegerStages.factor(max, 7, 5);
            else if (equals(weapon, "Dragon hunter crossbow")) max = WikiIntegerStages.factor(max, 5, 4);
        }

        if (monster != null && spell != null && monster.weakTo(spell.element()))
            max += WikiIntegerStages.factor(baseMax, monster.getWeaknessSeverity(), 100);

        int min = sunfireRunes && spell != null && "fire".equals(spell.element()) ? max / 10 : 0;
        if (chargedMatchingTome(gear, spell)) max = WikiIntegerStages.factor(max, 11, 10);
        return new Result(baseMax, Math.max(0, min), Math.max(0, max));
    }

    private static boolean chargedMatchingTome(Collection<EquipmentCandidate> gear, MagicSpell spell)
    {
        if (spell == null || spell.element().isEmpty()) return false;
        // Bank snapshots cannot expose charge count; PBIS retains its established
        // charged-form ownership assumption until item charge state is available.
        return has(gear, "Tome of " + spell.element());
    }

    private static String weaponName(Collection<EquipmentCandidate> gear)
    {
        if (gear != null) for (EquipmentCandidate c : gear)
            if (c != null && c.getSlot() == EquipmentSlot.WEAPON && c.getItem() != null) return c.getItem().getName();
        return "";
    }

    private static boolean has(Collection<EquipmentCandidate> gear, String name)
    {
        if (gear != null) for (EquipmentCandidate c : gear)
            if (c != null && c.getItem() != null && equals(c.getItem().getName(), name)) return true;
        return false;
    }

    private static boolean equals(String a, String b) { return a != null && a.equalsIgnoreCase(b); }
}

package com.personalbis;

import java.util.Collection;

/** Source-ordered sustained melee Wilderness and exclusive-necklace modifiers. */
public final class WikiMeleeEffects
{
    private WikiMeleeEffects() {}


    public static boolean avariceRevenant(Collection<EquipmentCandidate> gear, MonsterDefinition monster)
    {
        return monster != null && monster.getName().toLowerCase().startsWith("revenant")
            && has(gear, "Amulet of avarice");
    }

    public static int accuracyAfterAvarice(int roll, Collection<EquipmentCandidate> gear,
        MonsterDefinition monster)
    {
        return avariceRevenant(gear, monster) ? WikiIntegerStages.factor(roll, 24, 20) : roll;
    }

    public static int maxAfterAvarice(int maxHit, Collection<EquipmentCandidate> gear,
        MonsterDefinition monster)
    {
        return avariceRevenant(gear, monster) ? WikiIntegerStages.factor(maxHit, 24, 20) : maxHit;
    }

    /** Crystal blessing applies only to melee max hit and counts helm/body/legs as 1/3/2 pieces. */
    public static int maxAfterCrystalBlessing(int maxHit, Collection<EquipmentCandidate> gear)
    {
        if (!has(gear, "Crystal blessing")) return maxHit;
        int pieces = has(gear, "Crystal helm") ? 1 : 0;
        pieces += has(gear, "Crystal body") ? 3 : 0;
        pieces += has(gear, "Crystal legs") ? 2 : 0;
        return WikiIntegerStages.factor(maxHit, 40 + pieces, 40);
    }

    public static boolean isChargedRevWeapon(EquipmentCandidate weapon, MonsterDefinition monster)
    {
        if (weapon == null || weapon.getItem() == null || !WikiRangedEffects.isWildernessTarget(monster))
        {
            return false;
        }
        int id = weapon.getItem().getItemId();
        return id == 22545 || id == 27660;
    }

    public static int postAccuracy(int roll, EquipmentCandidate weapon, MonsterDefinition monster)
    {
        return isChargedRevWeapon(weapon, monster) ? WikiIntegerStages.factor(roll, 3, 2) : roll;
    }

    public static int postDamage(int maxHit, EquipmentCandidate weapon, MonsterDefinition monster)
    {
        return isChargedRevWeapon(weapon, monster) ? WikiIntegerStages.factor(maxHit, 3, 2) : maxHit;
    }

    private static boolean has(Collection<EquipmentCandidate> gear, String name)
    {
        if (gear != null)
        {
            for (EquipmentCandidate candidate : gear)
            {
                if (candidate != null && candidate.getItem() != null
                    && candidate.getItem().getName().equalsIgnoreCase(name))
                {
                    return true;
                }
            }
        }
        return false;
    }
}

package com.personalbis;
import java.util.*;
/** Post-attacker per-hitsplat target transforms ported from PlayerVsNPCCalc.applyNpcTransforms(). */
public final class WikiNpcTransforms {
 private WikiNpcTransforms(){}
 private static final Set<Integer> TEKTON=new HashSet<>(Arrays.asList(7540,7543,7544,7545));
 private static final Set<Integer> GLOWING=new HashSet<>(Arrays.asList(7568));
 private static final Set<Integer> OLM_HEAD=new HashSet<>(Arrays.asList(7551,7554));
 private static final Set<Integer> OLM_MELEE=new HashSet<>(Arrays.asList(7552,7555));
 private static final Set<Integer> OLM_MAGE=new HashSet<>(Arrays.asList(7550,7553));
 private static final Set<Integer> ICE_DEMON=new HashSet<>(Arrays.asList(7584,7585));
 private static final Set<Integer> NIGHTMARE_TOTEM=new HashSet<>(Arrays.asList(9434,9437,9440,9443,9435,9438,9441,9444));
 public static HitDistribution apply(HitDistribution d, MonsterDefinition m, AttackStyle style, EquipmentCandidate weapon, String spellElement, boolean demonbane){
  return applyInternal(d,m,style,weapon==null?null:weapon.getItem().getName(),weapon==null?null:weapon.getWeaponCategory(),spellElement,demonbane);
 }
 /** Explicit name-based entry point for calculators that do not retain the weapon EquipmentCandidate. */
 public static HitDistribution applyByWeaponName(HitDistribution d, MonsterDefinition m, AttackStyle style, String weaponName, String spellElement, boolean demonbane){
  return applyInternal(d,m,style,weaponName,null,spellElement,demonbane);
 }
 private static HitDistribution applyInternal(HitDistribution d, MonsterDefinition m, AttackStyle style, String weaponName, String weaponCategory, String spellElement, boolean demonbane){
  if(d==null||m==null)return d; int id=m.getId(); String n=m.getName();
  if("Zulrah".equalsIgnoreCase(n)) d=d.transform(HitDistribution.cappedReroll(50,5,45));
  if("Fragment of Seren".equalsIgnoreCase(n)) d=d.transform(HitDistribution.linearMin(2,22));
  if(("Kraken".equalsIgnoreCase(n)||"Cave kraken".equalsIgnoreCase(n))&&style==AttackStyle.RANGED) d=d.transform(HitDistribution.divide(7,1));
  if(TEKTON.contains(id)&&style==AttackStyle.MAGIC) d=d.transform(HitDistribution.divide(5,1));
  if(GLOWING.contains(id)&&style==AttackStyle.MAGIC) d=d.transform(HitDistribution.divide(3,0));
  if((OLM_MELEE.contains(id)||OLM_HEAD.contains(id))&&style==AttackStyle.MAGIC) d=d.transform(HitDistribution.divide(3,0));
  if((OLM_MAGE.contains(id)||OLM_MELEE.contains(id))&&style==AttackStyle.RANGED) d=d.transform(HitDistribution.divide(3,0));
  boolean usingDemonbane=demonbane || isDemonbaneWeapon(weaponName);
  if(ICE_DEMON.contains(id)&&!"fire".equalsIgnoreCase(spellElement)&&!usingDemonbane) d=d.transform(HitDistribution.divide(3,0));
  if("Slagilith".equalsIgnoreCase(n) && !isPickaxe(weaponName,weaponCategory)) d=d.transform(HitDistribution.divide(3,0));
  if(NIGHTMARE_TOTEM.contains(id)&&style==AttackStyle.MAGIC) d=d.transform(HitDistribution.multiply(2,1,0));
  if(m.getFlatArmour()!=0 && style!=AttackStyle.MAGIC) d=d.transform(HitDistribution.flatAdd(-m.getFlatArmour(),0),false);
  return d.flatten();
 }
 private static boolean isDemonbaneWeapon(String weaponName){
  if(weaponName==null)return false;
  return weaponName.equalsIgnoreCase("Scorching bow") || weaponName.equalsIgnoreCase("Arclight") || weaponName.equalsIgnoreCase("Emberlight") || weaponName.equalsIgnoreCase("Silverlight") || weaponName.equalsIgnoreCase("Darklight");
 }
 private static boolean isPickaxe(String weaponName,String weaponCategory){
  if(weaponCategory!=null && weaponCategory.equalsIgnoreCase("pickaxe"))return true;
  return weaponName!=null && weaponName.toLowerCase(Locale.ROOT).contains("pickaxe");
 }

}

package com.personalbis;

/**
 * Structural Java port boundary for the OSRS Wiki PlayerVsNPCCalc attack pipeline.
 * PBIS owns loadout discovery; this class owns Wiki ordering once rolls/distributions exist.
 */
public final class WikiPlayerVsNpcCalc {
    private WikiPlayerVsNpcCalc() {}

    /** Wiki getDistributionImpl ordering: attacker distribution, encounter phase overrides, then NPC transforms. */
    public static HitDistribution.AttackDistribution finalDistribution(
        HitDistribution.AttackDistribution attacker,
        MonsterDefinition monster,
        AttackStyle style,
        EquipmentCandidate weapon,
        String spellElement,
        boolean demonbane)
    {
        if (attacker == null || monster == null) return attacker;
        java.util.List<HitDistribution> out = new java.util.ArrayList<>();
        for (HitDistribution d : attacker.dists())
            out.add(WikiNpcTransforms.apply(d, monster, style, weapon, spellElement, demonbane));
        return new HitDistribution.AttackDistribution(out).flatten();
    }

    /** Name-based final transform boundary for Magic calculators, which retain the weapon label rather than candidate. */
    public static HitDistribution.AttackDistribution finalDistributionByWeaponName(
        HitDistribution.AttackDistribution attacker, MonsterDefinition monster, AttackStyle style,
        String weaponName, String spellElement, boolean demonbane)
    {
        if (attacker == null || monster == null) return attacker;
        java.util.List<HitDistribution> out = new java.util.ArrayList<>();
        for (HitDistribution d : attacker.dists())
            out.add(WikiNpcTransforms.applyByWeaponName(d, monster, style, weaponName, spellElement, demonbane));
        return new HitDistribution.AttackDistribution(out).flatten();
    }

    /** Wiki Magic base distribution. Magic Dart preserves accurate zero; modern spells convert it to one. */
    public static HitDistribution.AttackDistribution magicAttacker(int maxHit, double accuracy, boolean magicDart) {
        HitDistribution d = HitDistribution.linear(accuracy, 0, Math.max(0, maxHit));
        if (!magicDart) d = d.accurateZeroToOne();
        return new HitDistribution.AttackDistribution(java.util.Collections.singletonList(d));
    }

    /** Full sustained-Magic attacker effects in upstream getAttackerDist() order. */
    public static HitDistribution.AttackDistribution magicAttacker(
        int minHit, int maxHit, double accuracy, Double brimstoneAccuracy,
        java.util.Collection<EquipmentCandidate> gear, MonsterDefinition monster, MagicSpell spell)
    {
        HitDistribution d = HitDistribution.linear(accuracy, Math.max(0,minHit), Math.max(minHit,maxHit));
        if (brimstoneAccuracy != null)
        {
            java.util.List<HitDistribution.WeightedHit> mixed = new java.util.ArrayList<>();
            mixed.addAll(d.scaleProbability(.75).hits());
            mixed.addAll(HitDistribution.linear(brimstoneAccuracy,Math.max(0,minHit),Math.max(minHit,maxHit)).scaleProbability(.25).hits());
            d = new HitDistribution(mixed).flatten();
        }

        String weapon = equipmentName(gear,EquipmentSlot.WEAPON);
        if (equalsAny(weapon,"Sanguinesti staff","Holy sanguinesti staff"))
        {
            d = d.transform(h -> new HitDistribution(java.util.Arrays.asList(
                new HitDistribution.WeightedHit(.8,java.util.Collections.singletonList(h)),
                new HitDistribution.WeightedHit(.2,java.util.Collections.singletonList(new HitDistribution.Hitsplat(h.damage+8,h.accurate)))
            )),false);
        }

        boolean marked = spell != null && spell.markOfDarkness && spell.isDemonbane()
            && monster != null && monster.hasAttribute("demon");
        if (marked)
        {
            final int factor = equalsAny(weapon,"Purging staff") ? 50 : 25;
            final int vulnerability = DemonbaneEffects.vulnerability(monster);
            d = d.transform(h -> {
                int first = WikiIntegerStages.factor(h.damage,factor,100);
                int bonus = WikiIntegerStages.factor(first,vulnerability,100);
                return HitDistribution.single(h.damage+bonus,h.accurate);
            });
        }

        if (fullAhrim(gear))
        {
            d = d.transform(h -> new HitDistribution(java.util.Arrays.asList(
                new HitDistribution.WeightedHit(.75,java.util.Collections.singletonList(h)),
                new HitDistribution.WeightedHit(.25,java.util.Collections.singletonList(
                    new HitDistribution.Hitsplat(WikiIntegerStages.factor(h.damage,13,10),h.accurate)))
            )));
        }

        boolean preservesZero = spell != null && "Magic Dart".equalsIgnoreCase(spell.name);
        if (!preservesZero) d = d.accurateZeroToOne();

        if (MagicWeaponEffects.isTwinflame(weapon) && spell != null && "standard".equals(spell.spellbook)
            && ("bolt".equals(spell.tier()) || "blast".equals(spell.tier()) || "wave".equals(spell.tier())))
        {
            d = d.transform(h -> HitDistribution.single(1.0,java.util.Arrays.asList(
                new HitDistribution.Hitsplat(h.damage,h.accurate),
                new HitDistribution.Hitsplat(WikiIntegerStages.factor(h.damage,4,10),h.accurate))));
        }
        return new HitDistribution.AttackDistribution(java.util.Collections.singletonList(d.flatten()));
    }

    /** Full Magic ordering: spell/powered attacker distribution first, NPC transforms last. */
    public static HitDistribution.AttackDistribution magicFinalDistribution(
        int maxHit, double accuracy, boolean magicDart, MonsterDefinition monster,
        String weaponName, String spellElement, boolean demonbane)
    {
        return finalDistributionByWeaponName(magicAttacker(maxHit, accuracy, magicDart), monster,
            AttackStyle.MAGIC, weaponName, spellElement, demonbane);
    }

    public static HitDistribution.AttackDistribution magicFinalDistribution(
        int minHit, int maxHit, double accuracy, Double brimstoneAccuracy,
        MonsterDefinition monster, java.util.Collection<EquipmentCandidate> gear, MagicSpell spell)
    {
        HitDistribution.AttackDistribution attacker=magicAttacker(minHit,maxHit,accuracy,brimstoneAccuracy,gear,monster,spell);
        return finalDistributionByWeaponName(attacker,monster,AttackStyle.MAGIC,
            equipmentName(gear,EquipmentSlot.WEAPON),spell==null?null:spell.element(),spell!=null&&spell.isDemonbane());
    }

    private static boolean fullAhrim(java.util.Collection<EquipmentCandidate> gear)
    {
        return hasEquipment(gear,"Ahrim's staff") && hasEquipment(gear,"Ahrim's hood")
            && hasEquipment(gear,"Ahrim's robetop") && hasEquipment(gear,"Ahrim's robeskirt")
            && hasEquipment(gear,"Amulet of the damned");
    }

    private static boolean hasEquipment(java.util.Collection<EquipmentCandidate> gear,String name)
    { return !equipmentName(gear,null,name).isEmpty(); }

    private static String equipmentName(java.util.Collection<EquipmentCandidate> gear,EquipmentSlot slot)
    { return equipmentName(gear,slot,null); }

    private static String equipmentName(java.util.Collection<EquipmentCandidate> gear,EquipmentSlot slot,String exact)
    {
        if(gear!=null)for(EquipmentCandidate c:gear)if(c!=null&&c.getItem()!=null
            && (slot==null||c.getSlot()==slot)&&(exact==null||c.getItem().getName().equalsIgnoreCase(exact)))return c.getItem().getName();
        return "";
    }

    private static boolean equalsAny(String value,String... names)
    { if(value!=null)for(String n:names)if(value.equalsIgnoreCase(n))return true;return false; }

    public static double expectedDamage(HitDistribution.AttackDistribution d) {
        return d == null ? 0.0 : d.expectedDamage();
    }

    public static double dps(HitDistribution.AttackDistribution d, int attackTicks) {
        return attackTicks <= 0 ? 0.0 : expectedDamage(d) / (attackTicks * 0.6);
    }


    /** Wiki getAttackerDist standard linear path with modern accurate-zero conversion. */
    public static HitDistribution.AttackDistribution standardAttacker(int maxHit, double accuracy) {
        return new HitDistribution.AttackDistribution(java.util.Collections.singletonList(
            MeleeWeaponEffects.standardDistribution(maxHit, accuracy)));
    }

    /** Wiki sustained melee distribution branches that must precede accurate-zero and NPC transforms. */
    public static HitDistribution.AttackDistribution meleeSustainedAttacker(int maxHit,double accuracy,
        java.util.Collection<EquipmentCandidate> gear,MonsterDefinition monster) {
        HitDistribution raw=HitDistribution.linear(accuracy,0,Math.max(0,maxHit));
        String weapon=equipmentName(gear,EquipmentSlot.WEAPON);
        HitDistribution d=raw;
        if(equalsAny(weapon,"Gadderhammer")&&monster!=null&&monster.hasAttribute("shade")) {
            java.util.List<HitDistribution.WeightedHit> out=new java.util.ArrayList<>();
            out.addAll(raw.scaleProbability(.95).scaleDamage(5,4).hits());
            out.addAll(raw.scaleProbability(.05).scaleDamage(2).hits());
            d=new HitDistribution(out).flatten();
        }
        if(fullVerac(gear)) {
            java.util.List<HitDistribution.WeightedHit> out=new java.util.ArrayList<>();
            out.addAll(raw.scaleProbability(.75).hits());
            out.addAll(HitDistribution.linear(1.0,1,Math.max(0,maxHit)+1).scaleProbability(.25).hits());
            d=new HitDistribution(out).flatten();
        }
        d=d.accurateZeroToOne();
        return new HitDistribution.AttackDistribution(java.util.Collections.singletonList(d.flatten()));
    }

    private static boolean fullVerac(java.util.Collection<EquipmentCandidate> gear) {
        return hasEquipment(gear,"Verac's helm")&&hasEquipment(gear,"Verac's brassard")
            &&hasEquipment(gear,"Verac's plateskirt")&&hasEquipment(gear,"Verac's flail");
    }

    /** Wiki Scythe branch: one independent distribution per target-size hitsplat. */
    public static HitDistribution.AttackDistribution scytheAttacker(int baseMax, int hits, double accuracy) {
        java.util.List<HitDistribution> d = new java.util.ArrayList<>();
        d.add(MeleeWeaponEffects.standardDistribution(Math.max(0, baseMax), accuracy));
        if (hits >= 2) d.add(MeleeWeaponEffects.standardDistribution(MeleeWeaponEffects.scytheSecondMax(baseMax), accuracy));
        if (hits >= 3) d.add(MeleeWeaponEffects.standardDistribution(MeleeWeaponEffects.scytheThirdMax(baseMax), accuracy));
        return new HitDistribution.AttackDistribution(d);
    }

    /** Wiki normal two-hit family: both split hits roll independently. */
    public static HitDistribution.AttackDistribution independentTwoHitAttacker(int combinedMax, double accuracy) {
        return new HitDistribution.AttackDistribution(java.util.Arrays.asList(
            MeleeWeaponEffects.standardDistribution(MeleeWeaponEffects.splitFirstMax(combinedMax), accuracy),
            MeleeWeaponEffects.standardDistribution(MeleeWeaponEffects.splitSecondMax(combinedMax), accuracy)));
    }

    /** Dual macuahuitl remains sequential, so its conditional second hit stays in one distribution. */
    public static HitDistribution.AttackDistribution dualMacuahuitlAttacker(int combinedMax, double accuracy) {
        return new HitDistribution.AttackDistribution(java.util.Collections.singletonList(
            MeleeWeaponEffects.dualMacuahuitlDistribution(combinedMax, accuracy)));
    }

    public static HitDistribution.AttackDistribution fangAttacker(int trueMax, double accuracy) {
        return new HitDistribution.AttackDistribution(java.util.Collections.singletonList(
            MeleeWeaponEffects.fangDistribution(trueMax, accuracy)));
    }

    public static HitDistribution.AttackDistribution kerisAttacker(int modifiedMax, double accuracy) {
        return new HitDistribution.AttackDistribution(java.util.Collections.singletonList(
            MeleeWeaponEffects.kerisDistribution(modifiedMax, accuracy)));
    }

    public static HitDistribution.AttackDistribution obsidianAttacker(int baseMax, double accuracy, double multiplier) {
        return new HitDistribution.AttackDistribution(java.util.Collections.singletonList(
            MeleeWeaponEffects.obsidianDistribution(baseMax, accuracy, multiplier)));
    }


    /** Wiki ranged ordering: non-Ruby bolt transforms -> accurate-zero -> Corp -> Ruby. */
    public static HitDistribution.AttackDistribution rangedAttacker(
        EquipmentCandidate weapon, EquipmentCandidate ammo, MonsterDefinition monster, int rangedLevel,
        int normalMax, double accuracy, boolean kandarinHard) {
        return rangedAttacker(weapon,ammo,monster,rangedLevel,normalMax,accuracy,kandarinHard,null);
    }

    /** Sustained ranged weapon/set/ammunition effects in upstream getAttackerDist() order. */
    public static HitDistribution.AttackDistribution rangedAttacker(
        EquipmentCandidate weapon, EquipmentCandidate ammo, MonsterDefinition monster, int rangedLevel,
        int normalMax, double accuracy, boolean kandarinHard,
        java.util.Collection<EquipmentCandidate> gear) {
        HitDistribution d = EnchantedBoltEffects.preAccurateZeroDistribution(
            ammo, monster, rangedLevel, normalMax, accuracy, kandarinHard);

        String weaponName=weapon==null||weapon.getItem()==null?"":weapon.getItem().getName();
        boolean twoIndependent=equalsAny(weaponName,"Dark bow") || isChargedTonalztics(weapon);
        if (fullKarils(gear))
            d=d.transform(h -> new HitDistribution(java.util.Arrays.asList(
                new HitDistribution.WeightedHit(.75,java.util.Collections.singletonList(h)),
                new HitDistribution.WeightedHit(.25,java.util.Arrays.asList(h,
                    new HitDistribution.Hitsplat(h.damage/2,true)))
            )),false);

        if (ammo != null && ammo.getItem() != null && ammo.getItem().getName().contains("Seeking"))
            d=d.transform(h -> HitDistribution.single(Math.max(h.damage,3),h.accurate),false);
        d = d.accurateZeroToOne();
        if (CorporealBeastRules.isCorp(monster)) d = d.transform(HitDistribution.divide(2, 0)).flatten();
        d = EnchantedBoltEffects.applyRubyAfterCorp(d, ammo, monster, kandarinHard);
        java.util.List<HitDistribution> hits=twoIndependent
            ? java.util.Arrays.asList(d.flatten(),d.flatten())
            : java.util.Collections.singletonList(d.flatten());
        return new HitDistribution.AttackDistribution(hits);
    }

    /** Full ranged final pipeline: attacker transforms first, NPC transforms last. */
    public static HitDistribution.AttackDistribution rangedFinalDistribution(
        EquipmentCandidate weapon, EquipmentCandidate ammo, MonsterDefinition monster, int rangedLevel,
        int normalMax, double accuracy, boolean kandarinHard) {
        return rangedFinalDistribution(weapon,ammo,monster,rangedLevel,normalMax,accuracy,kandarinHard,null);
    }

    public static HitDistribution.AttackDistribution rangedFinalDistribution(
        EquipmentCandidate weapon, EquipmentCandidate ammo, MonsterDefinition monster, int rangedLevel,
        int normalMax, double accuracy, boolean kandarinHard,
        java.util.Collection<EquipmentCandidate> gear) {
        return finalDistribution(rangedAttacker(weapon, ammo, monster, rangedLevel, normalMax, accuracy, kandarinHard,gear),
            monster, AttackStyle.RANGED, weapon, null, false);
    }

    /** Ranged distribution at a specific remaining HP, used by finite-fight Ruby TTK. */
    public static HitDistribution.AttackDistribution rangedFinalDistributionAtHp(
        EquipmentCandidate weapon, EquipmentCandidate ammo, MonsterDefinition monster, int rangedLevel,
        int normalMax, double accuracy, boolean kandarinHard,
        java.util.Collection<EquipmentCandidate> gear, int currentHp) {
        if(ammo!=null&&ammo.getItem()!=null&&ammo.getItem().getName().toLowerCase().contains("ruby")) {
            return rangedRubyFinalDistributionAtHp(rangedRubyBaseDistribution(monster,rangedLevel,normalMax,accuracy,kandarinHard),
                weapon,ammo,monster,kandarinHard,currentHp);
        }
        HitDistribution.AttackDistribution attacker=rangedAttacker(
            weapon,ammo,monster,rangedLevel,normalMax,accuracy,kandarinHard,gear);
        return finalDistribution(attacker,monster,AttackStyle.RANGED,weapon,null,false);
    }

    /** Static ordinary-hit portion reused by every remaining-HP Ruby-bolt state. */
    public static HitDistribution rangedRubyBaseDistribution(MonsterDefinition monster,int rangedLevel,
        int normalMax,double accuracy,boolean kandarinHard) {
        HitDistribution base=EnchantedBoltEffects.preAccurateZeroDistribution(
            null,monster,rangedLevel,normalMax,accuracy,kandarinHard).accurateZeroToOne();
        return CorporealBeastRules.isCorp(monster)?base.transform(HitDistribution.divide(2,0)).flatten():base;
    }

    public static HitDistribution.AttackDistribution rangedRubyFinalDistributionAtHp(HitDistribution base,
        EquipmentCandidate weapon,EquipmentCandidate ammo,MonsterDefinition monster,boolean kandarinHard,int currentHp) {
        HitDistribution ruby=EnchantedBoltEffects.applyRubyAfterCorp(base,ammo,monster,kandarinHard,currentHp);
        HitDistribution.AttackDistribution attacker=new HitDistribution.AttackDistribution(
            java.util.Collections.singletonList(ruby.flatten()));
        return finalDistribution(attacker,monster,AttackStyle.RANGED,weapon,null,false);
    }

    private static boolean isChargedTonalztics(EquipmentCandidate weapon) {
        return weapon!=null&&weapon.getItem()!=null&&weapon.getItem().getItemId()==28922;
    }

    private static boolean fullKarils(java.util.Collection<EquipmentCandidate> gear) {
        return hasEquipment(gear,"Karil's coif")&&hasEquipment(gear,"Karil's leathertop")
            &&hasEquipment(gear,"Karil's leatherskirt")&&hasEquipment(gear,"Karil's crossbow")
            &&hasEquipment(gear,"Amulet of the damned");
    }

    /** Corp is an encounter transform before generic NPC transforms, matching Wiki ordering. */
    public static HitDistribution.AttackDistribution applyCorp(
        HitDistribution.AttackDistribution attacker, MonsterDefinition monster, EquipmentCandidate weapon, AttackStyle style) {
        return CorporealBeastRules.reduced(monster, weapon, style)
            ? attacker.transform(HitDistribution.divide(2, 0), true).flatten() : attacker;
    }

    /** Wiki Tormented Demon accuracy override. Phase is explicit until PBIS exposes encounter inputs in the UI. */
    public static double tormentedDemonAccuracy(String monsterName, String phase, double ordinaryAccuracy) {
        if (monsterName != null && monsterName.equalsIgnoreCase("Tormented Demon") && !"Shielded".equalsIgnoreCase(phase)) return 1.0;
        return ordinaryAccuracy;
    }

    /** Wiki Tormented Demon shield transform: 20% reduction unless unshielded, demonbane, or abyssal. */
    public static HitDistribution tormentedDemonDamage(HitDistribution d, String monsterName, String phase, boolean demonbane, boolean abyssal) {
        if (d == null || monsterName == null || !monsterName.equalsIgnoreCase("Tormented Demon")) return d;
        if (!"Unshielded".equalsIgnoreCase(phase) && !demonbane && !abyssal)
            return d.transform(HitDistribution.multiply(4,5,1)).flatten();
        return d;
    }

    /** Giant rat (Scurrius) is guaranteed accuracy except Manual Cast in the Wiki pipeline. */
    public static double giantRatAccuracy(MonsterDefinition monster, boolean manualCast, double ordinaryAccuracy) {
        return monster != null && monster.getId() == 7223 && !manualCast ? 1.0 : ordinaryAccuracy;
    }
}

package com.personalbis;

import java.util.Collection;

/** Source-ordered sustained ranged roll/max modifiers from Wiki PlayerVsNPCCalc. */
public final class WikiRangedEffects {
 private WikiRangedEffects(){}

 public static int accuracyAfterExclusive(int roll,Collection<EquipmentCandidate> gear,MonsterDefinition m,
   boolean task,boolean slayer){
  if(avariceRevenant(gear,m))return WikiIntegerStages.factor(roll,24,20);
  if(RangedLoadoutEffects.rangedSalveActive(asMap(gear),m))return WikiIntegerStages.factor(roll,
    RangedLoadoutEffects.salveAccuracy(asMap(gear),m)>=1.2?6:7,
    RangedLoadoutEffects.salveAccuracy(asMap(gear),m)>=1.2?5:6);
  return task&&slayer?WikiIntegerStages.factor(roll,23,20):roll;
 }

 public static int damageAfterExclusive(int max,Collection<EquipmentCandidate> gear,MonsterDefinition m,
   EquipmentCandidate weapon,boolean task,boolean slayer){
  if(avariceRevenant(gear,m))return WikiIntegerStages.factor(max,24,20);
  java.util.Map<EquipmentSlot,EquipmentCandidate> map=asMap(gear);
  if(RangedLoadoutEffects.rangedSalveActive(map,m))return WikiIntegerStages.factor(max,
    RangedLoadoutEffects.salveDamage(map,m)>=1.2?6:7,RangedLoadoutEffects.salveDamage(map,m)>=1.2?5:6);
  if(task&&slayer){
   int numerator=23;
   if(isChargedRevWeapon(weapon,m))numerator+=10;
   if(RangedWeaponEffects.isDragonHunterCrossbow(weapon)&&RangedWeaponEffects.isDraconic(m))numerator+=5;
   return WikiIntegerStages.factor(max,numerator,20);
  }
  return max;
 }

 public static int postAccuracy(int roll,EquipmentCandidate weapon,MonsterDefinition m,RangedStance stance,int distance){
  roll=(int)Math.floor(roll*RangedWeaponEffects.accuracyMultiplier(weapon,m));
  if(isChargedRevWeapon(weapon,m))roll=WikiIntegerStages.factor(roll,3,2);
  if(isChinchompa(weapon))roll=WikiIntegerStages.factor(roll,chinchompaNumerator(stance,distance),4);
  return roll;
 }

 public static int postDamage(int max,EquipmentCandidate weapon,MonsterDefinition m,boolean task,boolean slayer){
  if(isChargedRevWeapon(weapon,m)&&!(task&&slayer))max=WikiIntegerStages.factor(max,3,2);
  // Rev and dragon-hunter damage were already folded into the additive Slayer
  // factor above; without Slayer they remain ordinary multiplicative stages.
  if(!(task&&slayer&&RangedWeaponEffects.isDragonHunterCrossbow(weapon)&&RangedWeaponEffects.isDraconic(m)))
   max=(int)Math.floor(max*RangedWeaponEffects.damageMultiplier(weapon,m));
  if(isTonalztics(weapon))max=WikiIntegerStages.factor(max,3,4);
  return max;
 }

 public static int chinchompaNumerator(RangedStance stance,int distance){
  int d=Math.max(1,Math.min(7,distance));
  if(stance==RangedStance.ACCURATE)return d>=7?2:d>=4?3:4;       // Short fuse
  if(stance==RangedStance.RAPID)return d<4||d>=7?3:4;           // Medium fuse
  return d<4?2:d<7?3:4;                                        // Long fuse
 }

 public static boolean isChargedRevWeapon(EquipmentCandidate w,MonsterDefinition m){
  if(w==null||w.getItem()==null||!isWildernessTarget(m))return false;
  int id=w.getItem().getItemId();return id==22550||id==27655;
 }
 public static boolean isTonalztics(EquipmentCandidate w){return w!=null&&w.getItem()!=null&&
   w.getItem().getName().equalsIgnoreCase("Tonalztics of Ralos");}
 public static boolean isChinchompa(EquipmentCandidate w){return w!=null&&w.getItem()!=null&&
   w.getItem().getName().toLowerCase().contains("chinchompa");}
 public static boolean isWildernessTarget(MonsterDefinition m){
  if(m==null)return false;String n=m.getName().toLowerCase(),v=m.getVersion().toLowerCase();
  if(n.startsWith("revenant")||n.contains("callisto")||n.contains("artio")||n.contains("venenatis")||
    n.contains("spindel")||n.contains("vet'ion")||n.contains("calvar'ion")||n.contains("scorpia")||
    n.contains("chaos elemental")||n.contains("chaos fanatic")||n.contains("crazy archaeologist"))return true;
  return n.contains("wilderness")||v.contains("wilderness");
 }
 private static boolean avariceRevenant(Collection<EquipmentCandidate> gear,MonsterDefinition m){
  return m!=null&&m.getName().toLowerCase().startsWith("revenant")&&has(gear,"Amulet of avarice");
 }
 private static boolean has(Collection<EquipmentCandidate> gear,String name){if(gear!=null)for(EquipmentCandidate c:gear)
  if(c!=null&&c.getItem()!=null&&c.getItem().getName().equalsIgnoreCase(name))return true;return false;}
 private static java.util.Map<EquipmentSlot,EquipmentCandidate> asMap(Collection<EquipmentCandidate> gear){
  java.util.Map<EquipmentSlot,EquipmentCandidate> out=new java.util.EnumMap<>(EquipmentSlot.class);
  if(gear!=null)for(EquipmentCandidate c:gear)if(c!=null)out.put(c.getSlot(),c);return out;
 }
}

package com.personalbis;

import java.util.Arrays;
import java.util.HashSet;
import java.util.Set;

/**
 * Shared target damage-eligibility rules ported from the OSRS Wiki DPS calculator
 * PlayerVsNPCCalc.isImmune() path. Keep these checks before optimiser ranking.
 */
public final class WikiTargetEligibility {
 private WikiTargetEligibility() {}
 private static Set<Integer> ids(Integer... x){ return new HashSet<>(Arrays.asList(x)); }
 private static final Set<Integer> MELEE_IMMUNE=ids(494,7533,7706,7708,12214,12215,12219,2042,2043,2044);
 private static final Set<Integer> ZULRAH=ids(2042,2043,2044);
 private static final Set<Integer> VESPULA=ids(7530,7531,7532);
 private static final Set<Integer> NON_SALAMANDER_MELEE=ids(3169,3170,3171,3172,3173,3174,3175,3176,3177,3178,3179,3180,3181,3182,3183,7037);
 private static final Set<Integer> GUARDIANS=ids(7569,7571,7570,7572);
 private static final Set<Integer> RANGED_IMMUNE=ids(
  7540,7543,7544,7545, 7851,7854,7855,7882,7883,7886,7887,7888,7889, 7568,
  2463,2465,2467,2464,2466,2468,2137,2138,2139,2140,2141,2142);
 private static final Set<Integer> MAGIC_IMMUNE=ids(
  7851,7854,7855,7882,7883,7886,7887,7888,7889,
  2463,2465,2467,2464,2466,2468,2137,2138,2139,2140,2141,2142);

 private static String cat(EquipmentCandidate w){ return w==null?"":w.getWeaponCategory().trim().toLowerCase(); }
 public static boolean polearm(EquipmentCandidate w){ return cat(w).equals("polearm"); }
 public static boolean salamander(EquipmentCandidate w){ return cat(w).equals("salamander"); }
 public static boolean pickaxe(EquipmentCandidate w){ return cat(w).equals("pickaxe"); }

 public static boolean meleeCanDamage(MonsterDefinition m, EquipmentCandidate w){
  if(m==null)return true; int id=m.getId();
  if(MELEE_IMMUNE.contains(id)){
   // Wiki exception: Zulrah may be hit by polearms.
   if(ZULRAH.contains(id)&&polearm(w))return true;
   return false;
  }
  if(m.hasAttribute("flying")){
   // Vespula remains melee-immune despite carrying the flying attribute.
   if(VESPULA.contains(id))return false;
   if(!polearm(w)&&!salamander(w))return false;
  }
  if(NON_SALAMANDER_MELEE.contains(id)&&!salamander(w))return false;
  if(GUARDIANS.contains(id)&&!pickaxe(w))return false;
  return true;
 }
 public static boolean rangedCanDamage(MonsterDefinition m){
  if(m==null)return true;
  if(RANGED_IMMUNE.contains(m.getId()))return false;
  if(GUARDIANS.contains(m.getId()))return false;
  return true;
 }
 public static boolean magicCanDamage(MonsterDefinition m){
  if(m==null)return true;
  if(MAGIC_IMMUNE.contains(m.getId()))return false;
  if(GUARDIANS.contains(m.getId()))return false;
  return true;
 }
 public static boolean isGuardian(MonsterDefinition m){ return m!=null&&GUARDIANS.contains(m.getId()); }
}

package com.personalbis.wiki;

import com.google.gson.Gson;
import com.google.gson.reflect.TypeToken;
import com.personalbis.WikiEquipmentEngine;
import java.io.InputStream;
import java.io.InputStreamReader;
import java.lang.reflect.Type;
import java.nio.charset.StandardCharsets;
import java.util.Collections;
import java.util.HashMap;
import java.util.List;
import java.util.Locale;
import java.util.Map;
import javax.inject.Inject;
import javax.inject.Singleton;

@Singleton
public class WikiDataPack
{
    private final Gson gson;
    private List<WikiEquipment> equipment = Collections.emptyList();
    private List<WikiMonster> monsters = Collections.emptyList();
    private List<WikiSpell> spells = Collections.emptyList();
    private Map<Integer, WikiEquipment> equipmentById = Collections.emptyMap();

    @Inject
    public WikiDataPack(Gson gson)
    {
        this.gson = gson;
        WikiEquipmentEngine.initialize(gson);
        reload();
    }

    public void reload()
    {
        equipment = loadList("/wiki-data/equipment.json", new TypeToken<List<WikiEquipment>>(){}.getType());
        monsters = loadList("/wiki-data/monsters.json", new TypeToken<List<WikiMonster>>(){}.getType());
        spells = loadList("/wiki-data/spells.json", new TypeToken<List<WikiSpell>>(){}.getType());

        Map<Integer, WikiEquipment> byId = new HashMap<>();
        for (WikiEquipment item : equipment)
        {
            WikiEquipment current = byId.get(item.id);
            if (current == null || preferredVersion(item.version, current.version))
            {
                byId.put(item.id, item);
            }
        }
        equipmentById = Collections.unmodifiableMap(byId);
    }

    private boolean preferredVersion(String candidate, String current)
    {
        String c = candidate == null ? "" : candidate.trim();
        String old = current == null ? "" : current.trim();
        if (c.isEmpty() && !old.isEmpty()) return true;
        return "Standard".equalsIgnoreCase(c) && !"Standard".equalsIgnoreCase(old);
    }

    private <T> List<T> loadList(String resource, Type type)
    {
        try (InputStream in = WikiDataPack.class.getResourceAsStream(resource))
        {
            if (in == null) return Collections.emptyList();
            List<T> result = gson.fromJson(new InputStreamReader(in, StandardCharsets.UTF_8), type);
            return result == null ? Collections.emptyList() : Collections.unmodifiableList(result);
        }
        catch (Exception ex)
        {
            return Collections.emptyList();
        }
    }

    public WikiEquipment getEquipment(int id) { return equipmentById.get(id); }
    public List<WikiEquipment> getEquipment() { return equipment; }
    public List<WikiMonster> getMonsters() { return monsters; }
    public List<WikiSpell> getSpells() { return spells; }

    public WikiMonster findMonster(String name)
    {
        if (name == null) return null;
        String target = name.trim().toLowerCase(Locale.ROOT);
        for (WikiMonster monster : monsters)
        {
            if (monster.name != null && monster.name.toLowerCase(Locale.ROOT).equals(target)) return monster;
        }
        return null;
    }

    public String status()
    {
        return "Wiki pack: " + equipment.size() + " equipment / " + monsters.size() + " monsters / " + spells.size() + " spells";
    }
}

